/* =====================================================================
   LEARNING PATHS, continued
   Second file for the same PATH()/PATHS registry defined in
   50-paths.js (loaded first, so PATH, PATHS, TRACKS and LEVELS
   already exist here). Kept separate so two content passes can work at
   once without touching the same file: this file is for the engineering
   tracks (gameplay-engineer-godot, gameplay-engineer-unity,
   live-game-backend-engineer, netcode-server-engineer,
   build-and-release-engineer, interview-prep-engineer), written the same
   way as the paths in 50-paths.js. Run `node src/inventory.js` for
   every valid ref before writing a path here. Empty until that content
   lands; an empty file is valid, since a path only has to exist once it is
   written.
   ===================================================================== */

PATH('gameplay-engineer-godot', {
  t:'Gameplay engineer, Godot', tag:'Ship the core loop in Godot: signals, physics ticks, and a technique you can debug.',
  pick:'Build a gameplay system end to end in Godot 4',
  track:'engineering', level:'beginner', hours:18.6,
  audience:'Programmers new to Godot who already know how to code and want to implement a documented gameplay system end to end, in Godot 4. Game designer foundations is optional: steps marked as refreshers repeat its ideas in a few minutes.',
  outcome:'You can build a core loop, a decision UI, and a chosen AI technique in Godot, and you can point at the physics tick, the signal, and the Resource that make each one work.',
  prereq:[], next:['performance-engineer','senior-game-developer-ai-era','interview-prep-engineer','ai-engineering-for-game-devs','game-ai-programmer','technical-lead'],
  stages:[
    { id:'s1', t:'The loop, in Godot', level:'beginner',
      goal:'See the design idea of a core loop, then build it as a physics tick with a signal for the consequence.', hours:2.5,
      steps:[
        { kind:'engine', ref:'godot', why:'Nothing in this path runs until Godot is installed and a project opens, so set that up first; then knowing which node, scene and signal holds what turns a loop you understand into one you can build.', do:'Install Godot 4, create a new 2D project and run an empty scene, then read the guide’s architecture and editor stages and write down which node, scene and signal your core loop’s first version will use.', min:25 },
        { kind:'topic', ref:'core-loop', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Godot’s callback names differ from the words designers use. Land the design idea before wiring _physics_process to it.', do:'Describe your loop’s five links (action, feedback, decision, consequence, new situation) in one sentence each, with no engine terms.', min:12 },
        { kind:'topic', ref:'core-loop', tab:'godot', why:'The physics tick owns the verb. Drop the multiply-by-delta habit before it makes your character sixty times too slow.', do:'Write a CharacterBody2D script with _physics_process driving move_and_slide() and a signal emitted on the consequence. Do not multiply velocity by delta before move_and_slide.', min:30 },
        { kind:'tool', ref:'loop', why:'Building the loop as a diagram exposes the weak link your script hides inside one function.', do:'Build the same loop in the Loop Builder, run its weak-link check, and note which link the check flags that your script does not yet handle.', min:25 },
        { kind:'topic', ref:'decisions', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. A decision only counts if the player can make it. That is a design claim before it is an engine problem.', do:'List the three decisions your loop should offer the player and write the trade-off sentence for each.', min:12 },
        { kind:'topic', ref:'decisions', tab:'godot', why:'A Control with the wrong mouse_filter swallows the click and turns a decision into a decision nobody made.', do:'Build a Button-per-option menu from an Array of option data, set the first option to grab_focus, and check every overlay above it uses mouse_filter IGNORE.', min:25 },
        { kind:'topic', ref:'craft-design-patterns', tab:'godot', why:'Godot already hands you the component, prototype and observer patterns as nodes, scenes and signals, so the loop you just planned is built from patterns before you name any.', do:'Read the Godot tab, then label each node, scene and signal in your core loop plan with the pattern it plays, and write the player’s states as an enum and a match.', min:25 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why does move_and_slide() already apply delta, and what happens if you multiply by delta anyway?', a:'move_and_slide() integrates velocity over the physics step itself, so velocity is already in units per second. Multiplying by delta again scales it by the step length, roughly sixty times too slow at sixty physics ticks per second, and makes speed change whenever the physics tick rate changes.' },
          { q:'What is the difference between an action, a decision, and a consequence in the core loop?', a:'A decision is the choice the player makes, an action is what they physically do to carry it out, and a consequence is the state change the action causes; feedback then shows that change, and the changed state is the new situation the next decision responds to.', ideas:['A decision is the choice the player makes, an action is what they physically do to carry it out, and a consequence is the state change the action causes', 'feedback then shows that change', 'the changed state is the new situation the next decision responds to'] },
          { q:'Which mouse_filter value makes an overlay invisible to clicks, and which value makes it swallow them?', a:'STOP makes an overlay swallow clicks so nothing beneath it receives them, and IGNORE lets clicks pass through to whatever is underneath. A decorative overlay left at the default STOP silently blocks every button below it.' },
          { q:'Which Godot features play the component, prototype and observer patterns?', a:'Nodes composed in a scene are components, a scene instanced many times is a prototype, and signals are the observer pattern, visible in the Node dock.', ideas:['Nodes composed in a scene are components', 'a scene instanced many times is a prototype', 'signals are the observer pattern, visible in the Node dock'] }
        ],
        build:'Export the Loop Builder diagram, then paste your CharacterBody2D script and Button menu script under it in one page.',
        solution:{ outline:'Start with the Loop Builder diagram: one core loop with its action, feedback and consequence named. Then the CharacterBody2D script: read input in _physics_process, set velocity, call move_and_slide(), and emit a signal when a consequence happens. Do not multiply velocity by delta before move_and_slide(), because the method already does it. Then the Button menu script: connect pressed to a handler and set mouse_filter on any overlay so clicks reach the button. Put the diagram and both scripts on one page, with a line saying which pattern each scene part plays.', selfcheck:['Does the diagram name one action, its feedback and its consequence?', 'Does the movement script avoid multiplying velocity by delta before move_and_slide()?', 'Does a signal announce the consequence instead of the player node reaching into other nodes?', 'Does every overlay over the menu have a mouse_filter that matches whether it should swallow clicks?'] },
        skip:['Can you write a CharacterBody2D script with _physics_process and a consequence signal without checking the docs?','Do you know why multiplying velocity by delta before move_and_slide() breaks the loop, and could you spot it in review?','Have you already fixed a UI click that a Control higher in the tree was swallowing?','Can you name the trade-off sentence for every decision in your current game right now?','Can you name the pattern each node, scene and signal in your loop plays, and write its state machine as an enum and a match?']
      } },
    { id:'fund', t:'Engine fundamentals, in Godot', level:'beginner',
      goal:'Get the timestep, the vector maths, collision and scene composition right, and make the world survive a quit, because every system after this sits on them.', hours:3.5,
      steps:[
        { kind:'topic', ref:'craft-game-loop-timestep', tab:'godot', why:'The loop you built in stage one runs on a tick, and a late frame is where a game starts behaving differently on different machines.', do:'Read the Godot tab, then log delta in _process and _physics_process for ten seconds, cap the frame rate at 30 with Engine.max_fps, and write which of the two changed and what that means for where your movement code lives.', min:30 },
        { kind:'topic', ref:'craft-gameplay-math', tab:'godot', why:'Nearly every enemy, camera and ability reduces to a direction, a distance or a blend, and getting them right the first time saves the debug session.', do:'Read the Godot tab, then write a view-cone check with direction_to() and dot() against the cosine of half the field of view, and turn toward the target with an exponential smoothing factor so it looks the same at 30 and 144 fps.', min:35 },
        { kind:'topic', ref:'craft-physics-and-collision', tab:'godot', why:'Layers, masks and body types are decisions you make once and pay for whenever they are wrong, and a fast object that tunnels through a thin wall is the classic way to find out.', do:'Read the Godot tab, then put a CharacterBody2D player, a wall, a pickup Area2D and an enemy on four named collision layers with only the masks each needs, and fire a fast RigidBody2D at a thin wall with continuous_cd off, then on.', min:35 },
        { kind:'game', ref:'celeste', lens:'gameplay', why:'Celeste hides coyote time, jump buffering and corner correction under a hard game, so the controller and not the level makes a failure feel fair.', do:'Read the gameplay lens, then give your CharacterBody2D a jump if it has none, add a jump buffer and a coyote-time window, tune both in frames until a near-miss lands, and write the two values you kept.', min:20 },
        { kind:'topic', ref:'craft-entities-and-scenes', tab:'godot', why:'A scene is a reusable piece you instance as one node, and how you compose them decides how much of your game you can change without breaking the rest.', do:'Read the Godot tab, then build an enemy scene with a Health child node that emits a died signal, instance it five times, and write where you would need packed arrays instead of nodes if there were five thousand.', min:30 },
        { kind:'tool', ref:'sysmap', why:'With scenes, physics and the loop all in play, a map shows which of them everything else depends on.', do:'Map your project’s scenes and autoloads in the System Relationship Map, mark the node every other scene reaches into, and write which link you would replace with a signal.', min:25 },
        { kind:'topic', ref:'craft-save-systems', tab:'godot', why:'A game that forgets progress is not finished, and a save that can be half-written is worse than none, so the format and the write both need a plan before content piles up.', do:'Read the Godot tab, then save your player position and a version number to user:// through a temporary file and a rename, load it back, and corrupt the file on purpose to see your fallback.', min:30 }
      ],
      review:['core-loop'],
      check:{
        recall:[
          { q:'Why does movement code belong in the fixed step and not the per-frame callback?', a:'The fixed step runs at a constant rate with a constant delta, so speed and collisions come out the same at 30 and 144 frames per second. The per-frame callback runs once per rendered frame with a varying delta, so it suits visuals that only need smoothing.' },
          { q:'What does the dot product of a facing direction and the direction to a target tell you?', a:'For unit vectors it is 1 when the target is straight ahead, 0 at right angles and -1 behind, so comparing it with the cosine of half the field of view gives an in-cone test without computing an angle.', ideas:['For unit vectors it is 1 when the target is straight ahead, 0 at right angles and -1 behind', 'comparing it with the cosine of half the field of view gives an in-cone test without computing an angle'] },
          { q:'What is the difference between a collision layer and a collision mask?', a:'The layer says what an object is and the mask says which layers it looks for. Giving each thing its own layer and each mask only what it needs stops pickups reacting to enemies and keeps physics queries cheap.' },
          { q:'Why write a save to a temporary file and swap it in?', a:'If the power fails during a direct overwrite the only save is half written. Writing a temporary file and replacing the old one, keeping a backup, means a valid save always exists, and a version number lets a later patch migrate the old format.' }
        ],
        build:'Bring one scene together: the frame-rate log, the view-cone check, the four-layer setup, an enemy scene with a Health node, and a save that survives a deliberately corrupted write, plus the System Relationship Map export with the most-reached-into object marked.',
        solution:{ outline:'Build one small scene and record each piece. Log frame time with a fixed physics step so you can see the budget. Add a view-cone check using the angle between facing and the target. Set up the four collision layers and masks, and list which layer talks to which. Make an enemy scene with a Health node that owns its own death. Write the save with a temporary file and rename, then corrupt it on purpose and show the game recovers. Export the System Relationship Map and mark the object most others reach into.', selfcheck:['Does the frame log separate physics steps from render frames?', 'Does the view-cone test use a dot product or angle, not a distance only?', 'Can you say, for each layer, who is on it and who scans it?', 'Does the game start cleanly after the corrupted write, using the last good save?', 'Is the most-reached-into object marked, with a reason?'] },
        skip:['Can you say from memory which callback runs at a fixed rate and which runs once per frame?','Can you write a field-of-view check with a dot product without looking it up?','Can you explain what a collision layer and a mask each do in your own project?','Have you already written a save that survives a half-written file?']
      } },
    { id:'s2', t:'Rules, in Godot', level:'beginner',
      goal:'Turn a design mechanic into a Resource, and use failure and recovery to make retries fast and honest.', hours:2.25,
      steps:[
        { kind:'topic', ref:'challenge-failure-recovery', tab:'overview', why:'Recovery time is a design decision before it is a reload call: too slow, and a five-second lesson becomes a fifteen-second wait.', do:'Write what your player loses and keeps on failure, and the recovery time you are targeting, in seconds.', min:20 },
        { kind:'topic', ref:'challenge-failure-recovery', tab:'godot', why:'reload_current_scene() does not reset autoloads, so state from the failed run can leak into the retry.', do:'Write a die() function that times the reload with Time.get_ticks_msec(), calls an autoload Checkpoint.restore(), then reload_current_scene(). List every value the autoload must clear.', min:25 },
        { kind:'topic', ref:'mechanics-and-rules', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. A mechanic is only worth keeping if it feeds a decision. Sort your list before you turn any of it into data.', do:'List every mechanic your loop needs and cross out the ones that do not feed a decision you wrote in stage one.', min:12 },
        { kind:'topic', ref:'mechanics-and-rules', tab:'godot', why:'A Resource with a class_name puts the mechanic’s numbers in a .tres file a designer can open, instead of buried in code.', do:'Turn one surviving mechanic into a MechanicDef Resource with @export fields, and write the one-line decision_line() it can print.', min:25 },
        { kind:'checklist', ref:'design-review', why:'A design review forces every question about the mechanic to get an actual answer before you spend more time coding it.', do:'Run the design review checklist against the mechanic you just turned into a Resource, and write down what each group answered.', min:30 },
        { kind:'game', ref:'sonic', lens:'gameplay', why:'Sonic makes one rule carry the game: the ground stores and spends speed, so a movement rule, not an effect layered on top, decides how fast play feels.', do:'Read the Sonic gameplay lens, then give a CharacterBody2D a slope that adds speed going down and costs it going up, using get_floor_normal(); compare how it feels against a flat run button.', min:30 }
      ],
      review:['core-loop'],
      check:{
        recall:[
          { q:'What does reload_current_scene() NOT reset, and why does that matter?', a:'It leaves autoloads running with whatever state they held, so a buff, a timer, or a music value from the failed attempt leaks into the retry. Anything not explicitly cleared in the autoload’s own restore function survives across the reload.' },
          { q:'How do you decide whether a rule belongs in code or in a Resource?', a:'The rule stays in code, since logic is what governs behaviour, but its numbers and flags move into a Resource once there is more than one instance of the mechanic, so a designer can tune values in a .tres file without touching code.', ideas:['The rule stays in code, since logic is what governs behaviour', 'its numbers and flags move into a Resource once there is more than one instance of the mechanic', 'a designer can tune values in a .tres file without touching code'] },
          { q:'Why does a mechanic that touches no decision get cut?', a:'A mechanic only earns its place by creating or feeding a decision the player faces. One that touches nothing else is a mini-game sharing a menu with the real game, costing teaching and implementation time for no return.' }
        ],
        build:'Export the design review checklist results for your MechanicDef, alongside the die() function and the Resource script.',
        solution:{ outline:'Fill in the design review checklist for one MechanicDef: its inputs, rules, outputs and failure case, with the answers written down. Show the die() function with one exit path that cleans up, emits its signal and does nothing twice if called again. Show the Resource script holding the tunable numbers so a designer edits data, not code. Add a line tying the failure and recovery of the mechanic to the challenge page: what does the player lose, and how fast can they try again?', selfcheck:['Does the MechanicDef state its rules in terms a designer could change without code?', 'Does die() run its effects once even if called twice?', 'Do the tunable numbers live in the Resource, not as constants in the script?', 'Does the checklist name what the player loses on failure and how quickly they retry?'] },
        skip:['Have you already written a die() function that measures and logs its own recovery time?','Can you turn a mechanic into an @export Resource without checking the Godot docs?','Do you know what happens to an autoload’s state across reload_current_scene(), from experience rather than a guess?','Can you run a design review checklist on your own feature and act on an answer you did not want to hear?']
      } },
    { id:'s3', t:'Feel, in Godot', level:'intermediate',
      goal:'Make outcomes legible with feedback, buy that legibility with juice, and keep controls forgiving.', hours:3.6,
      steps:[
        { kind:'topic', ref:'feedback-and-affordance', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Without feedback the player cannot tell if their action worked, no matter how good the mechanic is underneath.', do:'List your three most common actions and, for each, what confirms the input and what confirms the outcome. Mark the empty cells.', min:12 },
        { kind:'topic', ref:'feedback-and-affordance', tab:'godot', why:'One outcome signal fanning out to animation, sound, and a tween means the miss case cannot be the one nobody wired.', do:'Emit a single outcome signal (hit, blocked, missed) from your resolver and connect one AnimationPlayer clip, one sound, and one create_tween() scale-pop to each of the three outcomes.', min:30 },
        { kind:'topic', ref:'game-feel-and-juice', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Juice amplifies feedback that already exists. It cannot manufacture meaning the loop does not have.', do:'Name the two actions in your game most worth emphasising, and the one thing each emphasis should communicate.', min:12 },
        { kind:'topic', ref:'game-feel-and-juice', tab:'godot', why:'Forgiveness (an input buffer) and emphasis (hit-stop) are both measured, not guessed.', do:'Add a buffer_sec input buffer for your attack action, and a hitstop() that scales Engine.time_scale for 0.05 seconds using a timer set to ignore the time scale.', min:30 },
        { kind:'topic', ref:'controls-and-friction', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Controls are the interface the player never stops touching. Friction there costs more than friction anywhere else.', do:'List your three most-repeated inputs and rate each for how forgiving it currently is, from instant to punishing a late press.', min:12 },
        { kind:'topic', ref:'controls-and-friction', tab:'godot', why:'Remapping rewrites the InputMap at runtime, and it has to be persisted or the player loses it on relaunch.', do:'Write a rebind() function that erases and re-adds an InputMap action, then saves the binding to a ConfigFile in user://.', min:25 },
        { kind:'tool', ref:'hypothesis', why:'A feel change is a claim, not a fact, until you write down the signal that would prove it worked.', do:'Write a hypothesis in the Hypothesis Builder for one feel change you just made (the buffer, the hit-stop, or the rebind), naming the signal and the kill criterion.', min:35 },
        { kind:'topic', ref:'craft-audio-clock-and-input-latency', tab:'godot', why:'Anything timed to music drifts if it runs on the frame clock; feel that depends on sound needs the audio clock and a stated latency budget.', do:'Read the Godot tab, then play a short track and log the song position from the audio clock beside your frame-counted time every second, and write how far apart they are after a minute.', min:30 },
        { kind:'topic', ref:'craft-performance', tab:'godot', why:'Juice adds particles, tweens and shakes every frame, and only a profiler shows which one costs the frame.', do:'Read the Godot tab, then open the Debugger’s Profiler and Visual Profiler on your juiced scene, and write the three most expensive functions and the frame budget they share.', min:30 }
      ],
      review:['decisions'],
      check:{
        recall:[
          { q:'What is the difference between confirming an input and confirming an outcome?', a:'Confirming an input tells the player their press registered, ideally within about a hundred milliseconds. Confirming an outcome tells them what the action accomplished, such as a hit, a block, or a miss. Games that skip the second leave failure silent.' },
          { q:'Why can juice not fix a loop that is not compelling underneath?', a:'Juice amplifies feedback that already exists inside a compelling loop. It cannot manufacture meaning or a decision the design never gave the player, so polishing before the bare loop is validated only delays discovering that the loop itself is not fun.' },
          { q:'What are the two things that make Godot’s input buffer and hit-stop measured instead of guessed?', a:'The input buffer is a numeric window, buffer_sec, measured in seconds rather than felt out. Hit-stop runs on an explicit timer that ignores Engine.time_scale, so its freeze duration is a set, tunable value instead of an arbitrary pause.' },
          { q:'Where do you look in Godot to see what a frame costs?', a:'The Debugger panel: the Profiler for script functions, the Visual Profiler for CPU and GPU render time, and Monitors for engine counters; the Performance singleton reads the same monitors in code.', ideas:['The Debugger panel: the Profiler for script functions, the Visual Profiler for CPU and GPU render time, and Monitors for engine counters', 'the Performance singleton reads the same monitors in code'] }
        ],
        build:'Export your Hypothesis Builder brief for the feel change you tested, and attach the buffer, hit-stop, or rebind script it is testing.',
        solution:{ outline:'Write the hypothesis in one sentence: if we change this feel parameter, this player behaviour or measure will move by this much. Name what you will watch and what result would make you revert. Attach one script: an input buffer window, a hit-stop of a few frames, or a rebind mapping that goes through the InputMap. State the value you tried and the value you compared it to. Add one line on how an observer could see the feedback and affordance without being told.', selfcheck:['Does the hypothesis name a measure and a revert threshold?', 'Is only one feel value changed between the two versions?', 'Is the buffer, hit-stop or rebind script short enough to read in one screen?', 'Could a new player notice the feedback without an explanation?'] },
        skip:['Can you name the empty cell in your own feedback matrix right now?','Have you already tuned a buffer_sec or hitstop() value against a playtest, not a guess?','Do you know why Engine.time_scale needs a timer that ignores it, to make hit-stop work at all?','Can you write a hypothesis with a signal and a kill criterion for a feel change in under ten minutes?','Have you profiled a juiced scene in Godot’s Debugger and named the function that costs the most?']
      } },
    { id:'s4', t:'Choose and see, in Godot', level:'advanced',
      goal:'Pick an AI technique by decision shape, then give agents the senses and the pathing to use it.', hours:3.75,
      steps:[
        { kind:'topic', ref:'choosing-ai-technique', tab:'overview', why:'The technique you pick decides what is easy and what is impossible for the rest of the project. Choose by decision shape, not by what sounds impressive.', do:'For your hardest enemy or ally, answer: is its decision reactive (pick among options now) or goal-directed (a sequence towards a state)? Write which technique that implies.', min:20 },
        { kind:'topic', ref:'choosing-ai-technique', tab:'godot', why:'A state machine in Godot is Nodes forwarding the physics tick to whichever child state is active, with the data on a Resource a designer can edit.', do:'Write a StateMachine Node that forwards _physics_process(delta) to an active child state and swaps when that state returns a different one.', min:30 },
        { kind:'tool', ref:'gameai', why:'The chooser turns “which technique” from a hunch into an answer you can defend, before you write the state machine or tree.', do:'Run your agent’s decision through the In-game AI Technique Chooser and compare its answer to what you built in the previous step.', min:20 },
        { kind:'topic', ref:'navigation-and-pathfinding', tab:'godot', why:'A perfect decision is worthless if the agent gets stuck on a doorframe. Players read pathing failures as stupidity.', do:'Bake a NavigationRegion3D from your level, give the agent a NavigationAgent3D, and drive its velocity from get_next_path_position() each physics tick.', min:30 },
        { kind:'topic', ref:'perception-and-awareness', tab:'godot', why:'Sensing is a physics query and belongs in _physics_process, or the space lock throws or answers late.', do:'Write a sight check that tests distance, a cone with Vector3.dot(), and a PhysicsDirectSpaceState3D ray, and write the result to a memory node instead of letting behaviour read the target directly.', min:35 },
        { kind:'topic', ref:'ai-budgets-and-debugging', tab:'godot', why:'Thirty agents thinking every frame is a classic frame-rate killer. Staggering the work and graphing its cost is how you keep it invisible.', do:'Write a scheduler that ticks a slice of your agents each physics frame by Engine.get_physics_frames() modulo the slice count, and register the cost with Performance.add_custom_monitor().', min:35 },
        { kind:'topic', ref:'craft-memory-and-gc', tab:'godot', why:'Agents that spawn, sense and path every frame are where object lifetime goes wrong: GDScript frees RefCounted objects at zero references, but Nodes and plain Objects stay until you free them.', do:'Read the Godot tab, then list every object your AI system creates per frame or per spawn, mark which are RefCounted and which you must free, and pool the one created most often.', min:30 },
        { kind:'game', ref:'pac-man', lens:'gameplay', why:'Pac-Man’s four ghosts share one steering rule and differ only in the tile each one aims for, the smallest case of AI where the choice of target is the whole personality.', do:'Read its gameplay lens, then in a new 2D scene, use a 10 by 10 Array grid and give two chasers the rule “at each junction take the turn that shortens the distance to a target tile”; aim one at the player’s tile and one four tiles ahead, then play until you are trapped from both sides and note how often that takes.', min:30 }
      ],
      review:['mechanics-and-rules'],
      check:{
        recall:[
          { q:'How do you decide whether a decision is reactive or goal-directed?', a:'A reactive decision picks among options available right now, which fits a state machine or behaviour tree. A goal-directed decision needs a sequence of actions towards a future state, which calls for a planner such as GOAP or HTN, while utility scoring answers a different question: how to weigh many competing considerations right now. Name the hardest decision first to tell which.' },
          { q:'Why must a sight or perception query run inside _physics_process in Godot?', a:'Physics queries such as ray casts are only valid inside _physics_process, because the physics server locks its space outside that step. Calling them from _process or a signal callback either errors or silently answers from a stale, previous-tick state, which reads as an enemy seeing through walls.' },
          { q:'What problem does staggering agent updates by frame index solve?', a:'Staggering spreads the cost of many agents thinking across several frames instead of all deciding on the same tick, preventing a frame-rate spike whenever a large fight starts. It trades a little reaction latency for a bounded, predictable per-frame AI budget.' },
          { q:'Which Godot objects free themselves and which do you free?', a:'RefCounted objects free themselves when their references reach zero; Nodes and plain Objects are freed by you, and C# scripts use the .NET collector instead.', ideas:['RefCounted objects free themselves when their references reach zero', 'Nodes and plain Objects are freed by you', 'C# scripts use the .NET collector instead'] }
        ],
        build:'Export the In-game AI Technique Chooser result, and attach your state machine, navigation, and scheduler scripts as the worked example.',
        solution:{ outline:'Run the chooser for one agent and keep its answer. Attach three short scripts: a state machine with an explicit enter and exit per state, a navigation call that handles an unreachable target, and a scheduler that spreads expensive AI work across frames. Say which technique the chooser picked and why the three scripts fit that choice. Add the perception rule the agent uses and one number from the profiler for the AI cost per frame.', selfcheck:['Does the chooser result match the technique you actually built?', 'Does each state clean up what it started when it exits?', 'What does the agent do when the navigation target cannot be reached?', 'Is the AI work spread so one frame does not pay for every agent?', 'Is there a measured cost, not a guess?'] },
        skip:['Can you justify picking a state machine over a behaviour tree (or the reverse) for a specific enemy, out loud, in one sentence?','Have you already fixed an agent that got stuck on level geometry?','Do you know why a physics-space query from _process or a signal callback fails or lies in Godot?','Can you read an AI cost monitor and say which of your agents is too expensive, right now?','Do you know which of your AI system’s objects are RefCounted and which leak unless you free them?']
      } },
    { id:'s5', t:'Test it, in Godot', level:'advanced',
      goal:'Turn the system you just built into a disposable prototype and a build that stays playable.', hours:3,
      steps:[
        { kind:'topic', ref:'prototyping', tab:'godot', why:'A prototype scene with its knobs as @export_range sliders is what makes a feel or AI change testable in one sitting.', do:'Put the one number you are least sure about (buffer_sec, a technique’s tuning, an AI budget) on the root node as an @export_range slider in its own throwaway scene.', min:30 },
        { kind:'topic', ref:'quality-and-build-health', tab:'godot', why:'A prototype that crashes cannot be played, and a leaked node report at exit is the cheapest regression signal Godot gives you for free.', do:'Write one GdUnit4 test that asserts your budget scheduler never exceeds its slice count, and run it headless through GdUnit4’s command-line tool (GdUnitCmdTool.gd with --headless --ignoreHeadlessMode, or the runtest script).', min:30 },
        { kind:'topic', ref:'craft-over-defensive-code', tab:'godot', why:'A prototype grows null checks on every node, and most of them guard @export wiring that should be checked once in _ready(), not on every frame.', do:'Read the Godot tab, then find three checks in your prototype that guard wiring or a state upstream code already excludes, remove them, and keep is_instance_valid() only where a node can really be freed underneath you.', min:25 },
        { kind:'checklist', ref:'pre-prototype', why:'A prototype without a hypothesis and a scope cut is a demo with extra steps, however good the code underneath is.', do:'Run the pre-prototype checklist against the scene you just built and fix whatever it fails.', min:30 },
        { kind:'reflect', why:'Writing your own answer, not the guide’s, is what makes the sequence yours to repeat on the next system.', do:'In your own words, write which of the four categories (loop, feel, AI, build health) was weakest in what you just built, and the one change you would make first.', min:30 },
        { kind:'game', ref:'five-nights-at-freddys', lens:'gameplay', why:'Five Nights at Freddy’s is one power number drained by three tools, a small system whose balance can be tested without a player.', do:'Read its gameplay lens, then write a small PowerDrain script with one power float and three drain rates, then a GdUnit4 test that runs a full night with a seeded RandomNumberGenerator and a fixed checking routine and asserts whether the power lasts until 6 AM.', min:30 }
      ],
      review:['game-feel-and-juice'],
      check:{
        recall:[
          { q:'Why does putting a tuning value on @export_range beat hardcoding it, even for a throwaway scene?', a:'An export_range slider lets you retune the one value you are least sure about live, in the inspector or during play, without editing and recompiling code, which is what makes a throwaway scene fast enough to test something in one sitting.' },
          { q:'What does Godot’s leaked-instance report at exit tell you?', a:'It counts objects still alive in the engine’s object database when the process quits, flagging nodes a script or a test created but never freed. A leak invisible in a passing test suite is the same leak that later shows up as a slow memory climb in play.' },
          { q:'What is the difference between a prototype and a demo?', a:'A prototype exists to answer one specific question, ideally with a stated kill criterion, using the cheapest build that can answer it. A demo shows off a feature or the current state of the game and answers no question at all, however polished it looks.' },
          { q:'When does a Godot node you called queue_free() on stop passing validity checks?', a:'Only at the end of the frame, when it is actually freed; until then != null and is_instance_valid() both still pass, and is_queued_for_deletion() is the check that says it is pending.', ideas:['Only at the end of the frame, when it is actually freed', 'until then != null and is_instance_valid() both still pass', 'is_queued_for_deletion() is the check that says it is pending'] }
        ],
        build:'Export the pre-prototype checklist result and your GdUnit4 test file as the artefact for this stage.',
        solution:{ outline:'Run the pre-prototype checklist on one idea and keep its result: the question the prototype answers, the cut list and the stop condition. Add one GdUnit4 test file that covers a pure rule from the prototype, such as damage or a score calculation, with the expected value worked out by hand rather than copied from the output. Keep the test small and fast. Add a line on what the test does not cover and how you will check that part by playing.', selfcheck:['Does the prototype have one question and a stop condition?', 'Is the expected value in the test worked out independently of the code?', 'Does the test run without starting a full scene?', 'Have you written down what the test leaves to playtesting?'] },
        skip:['Can you spin up a disposable Godot scene with export sliders in under ten minutes?','Have you already written and run a headless GdUnit4 test against your own code?','Can you run the pre-prototype checklist from memory?','Do you know what your project’s current leaked-instance count is at exit?','Can you tell a check that guards real freeing from one that re-defends wiring validated once?']
      } }
  ]
});

PATH('gameplay-engineer-unity', {
  t:'Gameplay engineer, Unity', tag:'Ship the core loop in Unity: the Input System, FixedUpdate, and a technique you can debug.',
  pick:'Build a gameplay system end to end in Unity 6',
  track:'engineering', level:'beginner', hours:19.02,
  audience:'Programmers new to Unity who already know how to code and want to implement a documented gameplay system end to end, in Unity 6. Game designer foundations is optional: steps marked as refreshers repeat its ideas in a few minutes.',
  outcome:'You can build a core loop, a decision UI, and a chosen AI technique in Unity, and you can point at the Update/FixedUpdate split, the UnityEvent, and the ScriptableObject that make each one work.',
  prereq:[], next:['performance-engineer','senior-game-developer-ai-era','interview-prep-engineer','ai-engineering-for-game-devs','game-ai-programmer','technical-lead'],
  stages:[
    { id:'s1', t:'The loop, in Unity', level:'beginner',
      goal:'See the design idea of a core loop, then build it across Update and FixedUpdate with an event for the consequence.', hours:2.5,
      steps:[
        { kind:'engine', ref:'unity', why:'Nothing in this path runs until Unity is installed and a project opens, so set that up first; then knowing the lifecycle, the asset database and where a MonoBehaviour sits turns a loop you understand into one you can build.', do:'Install Unity 6 through Unity Hub, create a new project and press Play on an empty scene, then read the guide’s architecture and pipeline stages and write down which GameObjects, components and lifecycle methods your core loop’s first version will use.', min:25 },
        { kind:'topic', ref:'core-loop', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Unity splits the loop across two callbacks. Land the design idea, action, feedback, decision, consequence, new situation, before you decide which callback owns which part.', do:'Describe your loop’s five links in one sentence each, with no engine terms.', min:12 },
        { kind:'topic', ref:'core-loop', tab:'unity', why:'Update never misses a press and FixedUpdate resolves movement on a fixed step. Reading a single-frame press inside FixedUpdate drops or double-counts it.', do:'Write a MonoBehaviour that reads WasPressedThisFrame() in Update, moves a Rigidbody with MovePosition() in FixedUpdate, with interpolation switched on, and invokes a UnityEvent<float> for the consequence.', min:30 },
        { kind:'tool', ref:'loop', why:'Building the loop as a diagram exposes the weak link your script hides inside two callbacks instead of one.', do:'Build the same loop in the Loop Builder, run its weak-link check, and note which link it flags that your script does not yet handle.', min:25 },
        { kind:'topic', ref:'decisions', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. A decision only counts if the player can make it. That is a design claim before it is a UI problem.', do:'List the three decisions your loop should offer the player and write the trade-off sentence for each.', min:12 },
        { kind:'topic', ref:'decisions', tab:'unity', why:'The action map is the list of things a player can do. Reading it aloud is the fastest fantasy audit a programmer can run.', do:'Say your InputActionAsset’s action names aloud, then generate one Button per option from a ScriptableObject list and wire EventSystem focus so a pad can answer too.', min:25 },
        { kind:'topic', ref:'craft-design-patterns', tab:'unity', why:'Unity already hands you components and prototypes as MonoBehaviours and prefabs, so naming the patterns early, and adding the state machine yourself, keeps the player’s behaviour from growing into a tangle of hand-combined booleans.', do:'Read the Unity tab, then label each GameObject, component and event in your loop plan with the pattern it plays, and write the player’s states as plain C# classes or an enum.', min:25 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why can reading a single-frame input inside FixedUpdate drop or double-count a press?', a:'FixedUpdate can run zero, one or several times within a single rendered frame, so a check for a press made there can miss it entirely or count it twice, producing exactly the input dropouts and double-triggers players report as an unresponsive control scheme.', ideas:['FixedUpdate can run zero, one or several times within a single rendered frame', 'a check for a press made there can miss it entirely or count it twice', 'producing exactly the input dropouts and double-triggers players report as an unresponsive control scheme'] },
          { q:'What is the difference between an action, a decision, and a consequence in the core loop?', a:'A decision is what the player chooses, an action is the move that carries it out, and a consequence is the state change the move causes; feedback shows that change, and the new state asks for the next decision. All of them sit inside the same repeating loop.' },
          { q:'What does reading your action map out loud tell you about your game’s fantasy?', a:'Reading the name of every action in an InputActionAsset aloud is a quick audit of everything the player can do, and therefore of the game’s real fantasy. A short or mismatched list reveals a fantasy thinner or different than intended.' },
          { q:'Which Unity features play the component, prototype and observer patterns?', a:'MonoBehaviours are components, prefabs are prototypes, and C# events and UnityEvent are the observer pattern; the state pattern is plain C#.', ideas:['MonoBehaviours are components', 'prefabs are prototypes', 'C# events and UnityEvent are the observer pattern', 'the state pattern is plain C#'] }
        ],
        build:'Export the Loop Builder diagram, then paste your MonoBehaviour and option-menu script under it in one page.',
        solution:{ outline:'Start with the Loop Builder diagram: one core loop with action, feedback and consequence named. Then a MonoBehaviour that reads input in Update, moves in FixedUpdate through the Rigidbody, and raises an event for the consequence. Do not multiply a Rigidbody velocity by deltaTime. Then the option-menu script: wire the buttons through listeners, and check that nothing in front of them blocks the raycast. Put the diagram and both scripts on one page with a line naming the pattern each piece plays.', selfcheck:['Does the diagram name one action, its feedback and its consequence?', 'Does movement happen in FixedUpdate through the Rigidbody, with input read in Update?', 'Does an event announce the consequence instead of one component reaching into others?', 'Can a click reach every option button, with no blocking raycast target in front?'] },
        skip:['Can you write an Update/FixedUpdate split with a UnityEvent consequence without checking the docs?','Do you know why sampling input in FixedUpdate is a trap, from experience rather than a guess?','Have you already generated a menu from ScriptableObject data instead of hand-placed buttons?','Can you name the Unity equivalent of a Godot Resource without looking it up?','Can you name the pattern each component, prefab and event in your loop plays?']
      } },
    { id:'fund', t:'Engine fundamentals, in Unity', level:'beginner',
      goal:'Get the timestep, the vector maths, collision and scene composition right, and make the world survive a quit, because every system after this sits on them.', hours:3.5,
      steps:[
        { kind:'topic', ref:'craft-game-loop-timestep', tab:'unity', why:'The loop you built in stage one runs on a tick, and a late frame is where a game starts behaving differently on different machines.', do:'Read the Unity tab, then log Time.deltaTime in Update and Time.fixedDeltaTime in FixedUpdate for ten seconds, cap the frame rate at 30 with Application.targetFrameRate, and write which of the two changed and what that means for where your movement code lives.', min:30 },
        { kind:'topic', ref:'craft-gameplay-math', tab:'unity', why:'Nearly every enemy, camera and ability reduces to a direction, a distance or a blend, and getting them right the first time saves the debug session.', do:'Read the Unity tab, then write a view-cone check with Vector3.Dot against the cosine of half the field of view, and turn toward the target with Quaternion.Slerp and an exponential smoothing factor so it looks the same at 30 and 144 fps.', min:35 },
        { kind:'topic', ref:'craft-physics-and-collision', tab:'unity', why:'Layers, masks and body types are decisions you make once and pay for whenever they are wrong, and a fast object that tunnels through a thin wall is the classic way to find out.', do:'Read the Unity tab, then put a CharacterController player, a wall, a pickup trigger and an enemy on four layers with the Layer Collision Matrix set to only what each needs, and fire a fast Rigidbody at a thin wall on Discrete, then on Continuous Dynamic.', min:35 },
        { kind:'game', ref:'celeste', lens:'gameplay', why:'Celeste hides coyote time, jump buffering and corner correction under a hard game, so the controller and not the level makes a failure feel fair.', do:'Read the gameplay lens, then give your CharacterController a jump if it has none, add a jump buffer and a coyote-time window, tune both in frames until a near-miss lands, and write the two values you kept.', min:20 },
        { kind:'topic', ref:'craft-entities-and-scenes', tab:'unity', why:'A prefab is a reusable piece you instantiate as one GameObject, and how you compose them decides how much of your game you can change without breaking the rest.', do:'Read the Unity tab, then build an enemy prefab with a Health component that raises a died event, instantiate it five times, and write where you would move to Entities (DOTS) if there were five thousand.', min:30 },
        { kind:'tool', ref:'sysmap', why:'With scenes, physics and the loop all in play, a map shows which of them everything else depends on.', do:'Map your project’s prefabs and singletons in the System Relationship Map, mark the object every other one reaches into, and write which link you would replace with an event.', min:25 },
        { kind:'topic', ref:'craft-save-systems', tab:'unity', why:'A game that forgets progress is not finished, and a save that can be half-written is worse than none, so the format and the write both need a plan before content piles up.', do:'Read the Unity tab, then save your player position and a version number under Application.persistentDataPath with File.Replace, load it back, and corrupt the file on purpose to see your fallback.', min:30 }
      ],
      review:['core-loop'],
      check:{
        recall:[
          { q:'Why does movement code belong in the fixed step and not the per-frame callback?', a:'The fixed step runs at a constant rate with a constant delta, so speed and collisions come out the same at 30 and 144 frames per second. The per-frame callback runs once per rendered frame with a varying delta, so it suits visuals that only need smoothing.' },
          { q:'What does the dot product of a facing direction and the direction to a target tell you?', a:'For unit vectors it is 1 when the target is straight ahead, 0 at right angles and -1 behind, so comparing it with the cosine of half the field of view gives an in-cone test without computing an angle.', ideas:['For unit vectors it is 1 when the target is straight ahead, 0 at right angles and -1 behind', 'comparing it with the cosine of half the field of view gives an in-cone test without computing an angle'] },
          { q:'What is the difference between a collision layer and a collision mask?', a:'The layer says what an object is and the mask says which layers it looks for. Giving each thing its own layer and each mask only what it needs stops pickups reacting to enemies and keeps physics queries cheap.' },
          { q:'Why write a save to a temporary file and swap it in?', a:'If the power fails during a direct overwrite the only save is half written. Writing a temporary file and replacing the old one, keeping a backup, means a valid save always exists, and a version number lets a later patch migrate the old format.' }
        ],
        build:'Bring one scene together: the frame-rate log, the view-cone check, the four-layer setup, an enemy prefab with a Health component, and a save that survives a deliberately corrupted write, plus the System Relationship Map export with the most-reached-into object marked.',
        solution:{ outline:'Build one small scene and record each piece. Log frame time with a fixed timestep so you can see the budget. Add a view-cone check using the angle between facing and the target. Set up the four physics layers and the collision matrix, and list who talks to whom. Make an enemy prefab with a Health component that owns its own death. Write the save to a temporary file then move it into place, then corrupt it on purpose and show the game recovers. Export the System Relationship Map and mark the object most others reach into.', selfcheck:['Does the frame log separate fixed updates from rendered frames?', 'Does the view-cone test use a dot product or angle?', 'Does the collision matrix match your written list of who talks to whom?', 'Does the game start cleanly after the corrupted write?', 'Is the most-reached-into object marked, with a reason?'] },
        skip:['Can you say from memory which callback runs at a fixed rate and which runs once per frame?','Can you write a field-of-view check with a dot product without looking it up?','Can you explain what a collision layer and a mask each do in your own project?','Have you already written a save that survives a half-written file?']
      } },
    { id:'s2', t:'Rules, in Unity', level:'beginner',
      goal:'Turn a design mechanic into a ScriptableObject, keep retries fast, and see how a shipped codebase enforces its own layering.', hours:3,
      steps:[
        { kind:'topic', ref:'challenge-failure-recovery', tab:'overview', why:'Recovery time is a design decision before it is a scene reload: too slow, and a five-second lesson becomes a wait a player abandons.', do:'Write what your player loses and keeps on failure, and the recovery time you are targeting, in seconds.', min:20 },
        { kind:'topic', ref:'challenge-failure-recovery', tab:'unity', why:'A scene reload past a certain size is why players stop retrying, and pooling the encounter buys the fast loop back.', do:'Write a retry path that resets only the handful of objects that matter using an ObjectPool, and measure its time against a full SceneManager.LoadScene() reload.', min:30 },
        { kind:'topic', ref:'mechanics-and-rules', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. A mechanic is only worth keeping if it feeds a decision. Sort your list before you turn any of it into an asset.', do:'List every mechanic your loop needs and cross out the ones that do not feed a decision you wrote in stage one.', min:12 },
        { kind:'topic', ref:'mechanics-and-rules', tab:'unity', why:'A ScriptableObject asset per mechanic means a diff shows exactly which number moved and who moved it.', do:'Turn one surviving mechanic into a ScriptableObject with CreateAssetMenu and Range fields, and add a FormerlySerializedAs guard for the field you are most likely to rename.', min:30 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/arch/arch-layering', why:'A real Unity codebase enforces mechanic and UI boundaries the same way: dependencies point one way, and nothing above core reaches back down.', do:'Say which of your own scripts would violate that rule today, based on how the client assembly stack keeps imports pointing one direction.', min:30 },
        { kind:'checklist', ref:'design-review', why:'A design review forces every question about the mechanic to get an actual answer before you spend more time coding it.', do:'Run the design review checklist against the mechanic you just turned into a ScriptableObject, and write down what each group answered.', min:35 },
        { kind:'game', ref:'crash-bandicoot', lens:'gameplay', why:'The N. Sane Trilogy rebuilt Crash’s levels from the original meshes and footage, yet a capsule collision shape and a faster jump arc made the same jumps harder: the rules of movement, not the art, decide difficulty.', do:'Read its gameplay lens, then build one ledge jump in Unity with a box collider, then swap it for a capsule and replay it ten times; write down where the capsule slips off the edge and which value you would change.', min:25 }
      ],
      review:['core-loop'],
      check:{
        recall:[
          { q:'Why does a full scene reload past a certain size cost you retries?', a:'SceneManager.LoadScene reloads and reinitializes the whole scene, including everything unrelated to the failed encounter, so past a certain scene size the load time itself turns a short failure lesson into a wait long enough that players stop retrying.', ideas:['SceneManager.LoadScene reloads and reinitializes the whole scene, including everything unrelated to the failed encounter', 'past a certain scene size the load time itself turns a short failure lesson into a wait long enough that players stop retrying'] },
          { q:'How do you decide whether a rule belongs in code or in a ScriptableObject?', a:'The logic stays in code, but once a mechanic has more than one instance its numbers and flags move into a ScriptableObject asset, so a diff shows exactly which value moved and a designer can tune it without touching a script.', ideas:['The logic stays in code', 'once a mechanic has more than one instance its numbers and flags move into a ScriptableObject asset', 'a diff shows exactly which value moved and a designer can tune it without touching a script'] },
          { q:'What direction do imports point in the client’s assembly stack, and why does it matter?', a:'Imports point down the stack, from a lean entry-point assembly through client and game layers to a shared layer and finally an engine-adjacent core layer, never upward. A backward import breaks the layering that keeps a large client compiling in pieces and its lower layers reusable.' }
        ],
        build:'Export the design review checklist results for your mechanic ScriptableObject, alongside the retry/pooling script and the assembly-layering note.',
        solution:{ outline:'Fill in the design review checklist for one mechanic ScriptableObject: inputs, rules, outputs and the failure case. Show the retry or pooling script so a failed attempt restarts quickly and spawned objects are reused, not destroyed and created. Add the assembly-layering note: which assembly may reference which, with gameplay never referencing UI. Add a line on what the player loses on failure and how fast they can try again.', selfcheck:['Do the tunable numbers live in the ScriptableObject, not in the script?', 'Does the retry path reuse objects instead of allocating new ones?', 'Does the layering note forbid gameplay from referencing UI?', 'Does the checklist say how quickly the player can retry?'] },
        skip:['Have you already pooled a retry path instead of reloading the whole scene?','Can you turn a mechanic into a ScriptableObject with a FormerlySerializedAs guard without checking the docs?','Do you know which of your own scripts breaks a strict one-way dependency direction, right now?','Can you run a design review checklist on your own feature and act on an answer you did not want to hear?']
      } },
    { id:'s3', t:'Feel, in Unity', level:'intermediate',
      goal:'Make outcomes legible with an event per outcome, buy that legibility with juice, and keep controls forgiving.', hours:3.27,
      steps:[
        { kind:'topic', ref:'feedback-and-affordance', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Without feedback the player cannot tell if their action worked, no matter how good the mechanic is underneath.', do:'List your three most common actions and, for each, what confirms the input and what confirms the outcome. Mark the empty cells.', min:12 },
        { kind:'topic', ref:'feedback-and-affordance', tab:'unity', why:'A UnityEvent per outcome, consumed by an Animator trigger, an AudioSource, and a particle burst, means the miss case cannot be the one nobody wired.', do:'Raise a UnityEvent<T> per outcome (hit, blocked, missed) from your resolver, wire an Animator.SetTrigger(), an AudioSource.PlayOneShot(), and a ParticleSystem.Play() to each, and reset triggers before setting a new one.', min:25 },
        { kind:'topic', ref:'game-feel-and-juice', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Juice amplifies feedback that already exists. It cannot manufacture meaning the loop does not have.', do:'Name the two actions in your game most worth emphasising, and the one thing each emphasis should communicate.', min:12 },
        { kind:'topic', ref:'game-feel-and-juice', tab:'unity', why:'Buffering runs on unscaled time, hit-stop on Time.timeScale, and shake on an impulse channel so it does not fight the follow camera.', do:'Add an input buffer on unscaled time for your attack action, and a hit-stop that sets Time.timeScale briefly, driven from WaitForSecondsRealtime so the pause itself is not scaled.', min:25 },
        { kind:'topic', ref:'controls-and-friction', tab:'overview', why:'A refresher if you finished Game designer foundations, so skim it; otherwise it is the design idea the code needs. Controls are the interface the player never stops touching. Friction there costs more than friction anywhere else.', do:'List your three most-repeated inputs and rate each for how forgiving it currently is, from instant to punishing a late press.', min:12 },
        { kind:'topic', ref:'controls-and-friction', tab:'unity', why:'Interactive rebinding excludes the pointer and the cancel key, then the override has to be saved as JSON or the player loses it on relaunch.', do:'Set up PerformInteractiveRebinding on one action excluding the pointer, then save the result with SaveBindingOverridesAsJson().', min:25 },
        { kind:'tool', ref:'hypothesis', why:'A feel change is a claim, not a fact, until you write down the signal that would prove it worked.', do:'Write a hypothesis in the Hypothesis Builder for one feel change you just made (the buffer, the hit-stop, or the rebind), naming the signal and the kill criterion.', min:25 },
        { kind:'topic', ref:'craft-audio-clock-and-input-latency', tab:'unity', why:'Anything timed to music drifts if it runs on the frame clock; feel that depends on sound needs the audio clock and a stated latency budget.', do:'Read the Unity tab, then play a short track and log AudioSettings.dspTime beside your frame-counted time every second, and write how far apart they are after a minute.', min:30 },
        { kind:'topic', ref:'craft-performance', tab:'unity', why:'Juice adds work to every frame, and only the Profiler shows which effect spends the budget.', do:'Read the Unity tab, then wrap your feedback code in a ProfilerMarker, open the Profiler on a juiced scene, and write the three most expensive markers against the 16.7 ms frame at 60 fps.', min:30 }
      ],
      review:['decisions'],
      check:{
        recall:[
          { q:'Why do a UnityEvent per outcome and a trigger reset avoid a stuck animation state?', a:'A separate UnityEvent for hit, blocked, and missed guarantees every outcome, including a whiffed attack, has a wired response instead of one path being silently forgotten. Resetting every trigger before setting the new one stops a stale trigger firing later on the wrong animation.' },
          { q:'Why does hit-stop need WaitForSecondsRealtime instead of a normal wait?', a:'Time.timeScale is set near zero during hit-stop, and a normal wait counts scaled time, so it would run many times longer than intended, or never resume if the scale hit zero. WaitForSecondsRealtime counts real time, so it can outlive the freeze it caused.' },
          { q:'What has to happen to a rebinding override for it to survive a relaunch?', a:'The override has to be serialized with SaveBindingOverridesAsJson and written to persistent storage, then loaded back before any action reads its binding at startup. Otherwise the remap exists only in memory and disappears the moment the player quits.' },
          { q:'How do you make your own code visible in the Unity Profiler, and read a counter in a build?', a:'Wrap it in a ProfilerMarker so it appears by name in the Profiler; ProfilerRecorder reads counters in code, so a build can report its own frame time.', ideas:['Wrap it in a ProfilerMarker so it appears by name in the Profiler', 'ProfilerRecorder reads counters in code, so a build can report its own frame time'] }
        ],
        build:'Export your Hypothesis Builder brief for the feel change you tested, and attach the feedback, buffer/hit-stop, or rebind script it is testing.',
        solution:{ outline:'Write the hypothesis in one sentence: if we change this feel parameter, this behaviour or measure moves by this much. Name what you watch and what result makes you revert. Attach one script: a feedback trigger (sound, shake or flash), an input buffer or hit-stop, or a rebind mapping through the Input System. State the value you tried and the value you compared it to. Add one line on how an observer would see the feedback without being told.', selfcheck:['Does the hypothesis name a measure and a revert threshold?', 'Is only one feel value changed between versions?', 'Is the script short enough to read on one screen?', 'Could a new player notice the feedback without an explanation?'] },
        skip:['Can you name the empty cell in your own feedback matrix right now?','Have you already tuned a buffer or hit-stop value against a playtest, not a guess?','Do you know why Time.timeScale alone is not enough for hit-stop, from experience rather than a guess?','Can you write a hypothesis with a signal and a kill criterion for a feel change in under ten minutes?','Have you named your own code with ProfilerMarker and found the effect that costs the frame?']
      } },
    { id:'s4', t:'Choose and see, in Unity', level:'advanced',
      goal:'Pick an AI technique by decision shape, see it grow into a real state machine, then give agents senses and pathing.', hours:3.5,
      steps:[
        { kind:'topic', ref:'choosing-ai-technique', tab:'overview', why:'The technique you pick decides what is easy and what is impossible for the rest of the project. Choose by decision shape, not by what sounds impressive.', do:'For your hardest enemy or ally, answer: is its decision reactive (pick among options now) or goal-directed (a sequence towards a state)? Write which technique that implies.', min:20 },
        { kind:'topic', ref:'choosing-ai-technique', tab:'unity', why:'Unity gives you the parts on the shelf: hand-rolled ScriptableObject states, or the Behavior package’s graph assets. Either way the decision is a file a designer can open.', do:'Write a runner MonoBehaviour that calls state.Tick(agent, dt) on a ScriptableObject state asset, and swap states through it instead of through the Animator.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/arch/arch-state-machines', why:'A shipped hierarchical state machine shows what your Tick-based version grows into once you have more than three states.', do:'List one transition your own machine cannot express yet, based on how the shipped state machine builds its transition table from an event id per state.', min:30 },
        { kind:'tool', ref:'gameai', why:'The chooser turns “which technique” from a hunch into an answer you can defend, before you write the state machine or tree.', do:'Run your agent’s decision through the In-game AI Technique Chooser and compare its answer to what you built.', min:20 },
        { kind:'topic', ref:'navigation-and-pathfinding', tab:'unity', why:'A perfect decision is worthless if the agent never lands on the NavMesh. Players read pathing failures as stupidity.', do:'Bake a NavMeshSurface from your level, call SetDestination() on a NavMeshAgent, and check its return value and isOnNavMesh before trusting the path.', min:30 },
        { kind:'topic', ref:'perception-and-awareness', tab:'unity', why:'Perception is a physics query plus a layer mask, and the result belongs in a knowledge component so behaviour never reads the player transform directly.', do:'Write a sight check using OverlapSphereNonAlloc on a target layer and a Linecast against the occluder layer, and store a hit in a knowledge component instead of a direct reference.', min:30 },
        { kind:'topic', ref:'ai-budgets-and-debugging', tab:'unity', why:'Thirty agents thinking every frame is a classic frame-rate killer, and a named ProfilerMarker is what lets you prove it.', do:'Wrap your agents’ decision code in a ProfilerMarker, slice them by Time.frameCount modulo N, and read the cost back with a ProfilerRecorder.', min:30 },
        { kind:'topic', ref:'craft-memory-and-gc', tab:'unity', why:'AI queries and spawns run every frame, and garbage made in Update is paid for later by the collector, at a time you do not choose.', do:'Read the Unity tab, then check the Profiler’s GC Alloc column for your AI system, replace one allocating physics query with its NonAlloc form, and pool spawned agents with UnityEngine.Pool.', min:30 }
      ],
      review:['mechanics-and-rules'],
      check:{
        recall:[
          { q:'How do you decide whether a decision is reactive or goal-directed?', a:'A reactive decision picks among options available right now and suits a state machine or behaviour tree. A goal-directed decision needs a sequence of actions towards a future state and suits a planner such as GOAP or HTN, while utility scoring weighs many competing considerations in a decision made now. The agent’s hardest decision decides which family fits.' },
          { q:'Why does storing a sighting in a knowledge component beat behaviour reading the player transform directly?', a:'A knowledge component stores only what the agent has sensed, so behaviour reading it stays fair and cannot see through walls or off screen. Reading the player’s transform directly gives the agent information no sense channel produced, which players experience as cheating.' },
          { q:'What does a ProfilerMarker give you that a stopwatch variable does not?', a:'A ProfilerMarker gives a timed block a name that shows up in the Profiler timeline alongside rendering, physics, and navigation costs, and can be read live at runtime with a ProfilerRecorder. A hand-rolled stopwatch variable has no visibility into what else is competing for the frame.' },
          { q:'Why does garbage made in Update cost you later, and what does Unity give you to avoid it?', a:'Managed objects sit on a heap swept by an incremental collector, so allocation is paid for in collection work at a time you do not choose; UnityEngine.Pool.ObjectPool and NonAlloc queries avoid the allocation.', ideas:['Managed objects sit on a heap swept by an incremental collector, so allocation is paid for in collection work at a time you do not choose', 'UnityEngine.Pool.ObjectPool and NonAlloc queries avoid the allocation'] }
        ],
        build:'Export the In-game AI Technique Chooser result, and attach your state runner, navigation, and profiling scripts as the worked example.',
        solution:{ outline:'Run the chooser for one agent and keep its answer. Attach three short scripts: a state runner with an explicit enter and exit per state, a navigation call that handles a path that does not exist, and the profiling markers around the AI update. Say which technique the chooser picked and why the scripts fit it. Add the perception rule of the agent and one profiler number for AI cost per frame.', selfcheck:['Does the chooser result match the technique you built?', 'Does each state clean up what it started when it exits?', 'What happens when no path exists?', 'Does the profiler capture show the AI cost, not a guess?'] },
        skip:['Can you justify picking a hand-rolled state machine over the Behavior package (or the reverse) for a specific enemy, out loud, in one sentence?','Have you already fixed an agent that never landed on the NavMesh?','Can you read your own transition table and say what state a given event leads to, without opening the code?','Can you read a ProfilerRecorder result and say which of your agents is too expensive, right now?','Does your AI system show zero GC Alloc per frame in the Profiler?']
      } },
    { id:'s5', t:'Test it, in Unity', level:'advanced',
      goal:'Turn the system you just built into a disposable prototype and a build that stays playable.', hours:3.25,
      steps:[
        { kind:'topic', ref:'prototyping', tab:'unity', why:'A Range field on a ScriptableObject tuning asset is what makes a feel or AI change testable in one sitting, and the values survive after you press Stop.', do:'Put the one number you are least sure about (a buffer, a technique’s tuning, an AI budget) into a ScriptableObject with a Range field, in its own throwaway scene.', min:30 },
        { kind:'topic', ref:'quality-and-build-health', tab:'unity', why:'A prototype that will not build cannot be played, and the Editor’s Mono runtime hides bugs that only appear under IL2CPP on device.', do:'Write one EditMode test with the Unity Test Framework asserting your budget scheduler never exceeds its slice count, and run it with -batchmode -runTests -testPlatform EditMode.', min:30 },
        { kind:'topic', ref:'craft-source-control-for-games', tab:'unity', why:'A tested build is only reproducible if the project in source control can rebuild it, and Unity projects break that through missing .meta files and binary scenes.', do:'Read the Unity tab, then set Force Text serialization, confirm every asset’s .meta file is committed and Library is ignored, and set UnityYAMLMerge as the merge tool for scenes and prefabs.', min:25 },
        { kind:'checklist', ref:'pre-prototype', why:'A prototype without a hypothesis and a scope cut is a demo with extra steps, however good the code underneath is.', do:'Run the pre-prototype checklist against the scene you just built and fix whatever it fails.', min:30 },
        { kind:'reflect', why:'Writing your own answer, not the guide’s, is what makes the sequence yours to repeat on the next system.', do:'In your own words, write which of the four categories (loop, feel, AI, build health) was weakest in what you just built, and the one change you would make first.', min:30 },
        { kind:'game', ref:'beat-saber', lens:'gameplay', why:'Beat Saber, built in Unity, lives or dies on notes arriving exactly on the beat, a clean case for testing a feel with numbers rather than by eye.', do:'Read the Beat Saber page’s gameplay lens, then write the three checks you would automate (note timing against the audio clock, cut direction, score per cut) and the one check only a headset can make.', min:15 },
        { kind:'game', ref:'deus-ex', lens:'gameplay', why:'Deus Ex gives each goal several routes opened by different systems, skills, tools, augmentations and fights, so it shows why a game built on combining systems needs tests that cover every route, not one scripted path.', do:'Read its gameplay lens, then pick one locked door in Deus Ex and list every way the game lets you past it and what each spends; then build a door in a fresh Unity scene with two routes past it (a key and a lockpick) and write one EditMode test per route.', min:35 }
      ],
      review:['game-feel-and-juice'],
      check:{
        recall:[
          { q:'Why does putting a tuning value in a Range field beat hardcoding it, even for a throwaway scene?', a:'A Range field on a ScriptableObject tuning asset lets you retune the one uncertain value live, and because it lives on an asset rather than a scene instance, the value you tuned during play survives after you press Stop, unlike a change made directly on a MonoBehaviour.', ideas:['A Range field on a ScriptableObject tuning asset lets you retune the one uncertain value live', 'because it lives on an asset rather than a scene instance, the value you tuned during play survives after you press Stop'] },
          { q:'What is the risk of only testing in the Editor’s Mono runtime and never on an IL2CPP build?', a:'The Editor runs Mono with a JIT and no managed stripping; the shipped player usually runs IL2CPP, compiled ahead of time and stripped. Reflection, dynamically built generics and runtime code generation can pass every Editor test and then fail on device, so a green Editor suite says nothing about the player build.' },
          { q:'What is the difference between a prototype and a demo?', a:'A prototype tests one named question with the cheapest possible build and a stated result that would kill the idea. A demo shows off a feature or a polished slice and answers no question, regardless of how much of the game it represents.' },
          { q:'Which Unity files must be committed and which are regenerated?', a:'Every asset’s .meta file, which carries its GUID, must be committed; Library is a regenerated cache and stays out. With Force Text, scenes and prefabs are YAML that UnityYAMLMerge can merge.' }
        ],
        build:'Export the pre-prototype checklist result and your EditMode test file as the artefact for this stage.',
        solution:{ outline:'Run the pre-prototype checklist on one idea and keep its result: the question the prototype answers, the cut list and the stop condition. Add one EditMode test file that covers a pure rule, such as damage or score, with the expected value worked out by hand rather than copied from the output. Keep it fast and free of scenes. Add a line on what the test leaves to playing, and a note on how the project is kept in source control.', selfcheck:['Does the prototype have one question and a stop condition?', 'Is the expected value worked out independently of the code?', 'Does the test run in EditMode without loading a scene?', 'Have you written down what the test leaves to playtesting?'] },
        skip:['Can you spin up a disposable Unity scene with a Range-tuned ScriptableObject in under ten minutes?','Have you already written and run an EditMode test against your own code?','Can you run the pre-prototype checklist from memory?','Do you know whether your current build even compiles under IL2CPP?','Is every .meta file in your repository, Library ignored, and scene merging set to UnityYAMLMerge?']
      } }
  ]
});

PATH('live-game-backend-engineer', {
  t:'Live-game backend engineer', tag:'Ship a Go service that survives crashes, lying clients, and players who never stop playing.',
  pick:'Build a backend that survives a live game',
  track:'engineering', level:'intermediate', hours:15.92,
  audience:'Backend or Go engineers moving into games, who already ship services (the exercises are in Go) and want the constraints unique to a live game: state that must survive a crash, a client that lies, and players who do not stop playing while you ship.',
  outcome:'You can design and defend a request path, a caching and migration strategy, and a live-ops rollout for a game backend, and verify what an AI assistant wrote for you before it ships.',
  prereq:[], next:['netcode-server-engineer','performance-engineer','senior-game-developer-ai-era','interview-prep-engineer','technical-lead'],
  stages:[
    { id:'s1', t:'Shape the service', level:'intermediate',
      goal:'Decide which way dependencies point, how one binary can boot as many roles, and which protocol fits your client, then build the skeleton that proves it.', hours:2.75,
      steps:[
        { kind:'topic', ref:'backend-layering', why:'The code that knows the game rules must not know which database or transport delivered them. Get this direction right before anything else compounds on top of it.', do:'Draw your planned service as three or four layers and mark every import. Circle any import that points outward instead of inward.', min:25 },
        { kind:'topic', ref:'backend-di-modes', why:'One binary that can boot as an API server, a worker, or an admin tool is cheaper to build and deploy than three binaries that drift apart.', do:'List the process roles your service needs (API, background worker, one-off job) and write the one flag or argument that would select each at boot.', min:25 },
        { kind:'topic', ref:'backend-api-protocol', why:'REST/JSON, protobuf over HTTP, and gRPC are three different bets about schema, tooling, and who your client is.', do:'Pick a protocol for your service and write the one sentence that justifies it against the other two, naming your actual client.', min:20 },
        { kind:'part', ref:'cs-go-game-backend/api/api-protocol', why:'A shipped backend answers the same protocol question with a header contract instead of just a schema choice.', do:'List which of those fields your own design is currently missing, based on how the header set (session, platform, client version) carries the protocol.', min:25 },
        { kind:'flow', ref:'cs-go-game-backend/request', why:'The life of a request shows what a handler gets for free: context, gates, and a response it never assembles by hand.', do:'Walk the request flow and write down the one step in it your own handler design does not yet have an answer for.', min:25 },
        { kind:'reflect', why:'A skeleton that compiles and answers one request is the cheapest proof that the layering, the mode flag and the protocol choice fit together.', do:'Build the service skeleton: three layers with inward imports, one binary that boots as API or worker from a flag, and one handler on your chosen protocol, and run it. If an AI assistant writes part of it, decide first what you will write yourself.', min:45 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Which direction should a dependency point, and what breaks when it points the other way?', a:'Dependencies should point inward, towards entities and use cases at the centre, with adapters like handlers and repositories outside. Pointed outward, the centre imports a database driver or transport directly, so a rule test needs real infrastructure and the game rules become tied to whatever stores them.' },
          { q:'What decides whether one binary can boot as more than one process role?', a:'One composition root that reads a mode flag at start-up and builds a different object graph per role (API server, worker, batch job), each taking only the dependencies it needs from one shared set of entities and interactors. The case study generates those graphs at build time, so a missing binding fails the build. Hand-written wiring works too, it just fails later.' },
          { q:'Name one field in a shipped backend’s header contract that a bare protocol choice would not carry.', a:'A protobuf-over-HTTP contract like the one in the case study carries session, platform, language, client version, master data version, and a state generation counter in its headers. A protocol missing the master data version cannot tell a client whether its cached configuration is stale.' }
        ],
        build:'Attach the running skeleton: the layer directories with inward imports, the mode flag that boots API or worker, one handler on your chosen protocol and its first successful request',
        solution:{ outline:'Show a small Go service you can run. Lay out layer directories (transport, service, data) where imports point inward only. Add a mode flag, read once in main, that boots either the API or the worker, with dependencies wired in one place. Add one handler on your chosen protocol with a typed request and response. Run it and attach the first successful request and its response. Name the one rule that stops a lower layer importing a higher one, and how you check it.', selfcheck:['Do imports point inward only, and is there a check for that?', 'Is the mode chosen once at start and dependencies wired in one place?', 'Does the handler use a typed request, not a loose map?', 'Is a real first request and response attached?'] },
        skip:['Can you draw your service’s layers and its import direction from memory, right now?','Do you already know which process roles one binary needs to boot as, for your own service?','Can you justify a protocol choice against the two you did not pick, out loud, in one sentence?','Have you already walked a real request end to end and found the gap in your own design?']
      } },
    { id:'s2', t:'Handle the request', level:'intermediate',
      goal:'Seed a request with context once, give errors a shape the client can act on, and keep a transaction from touching more than it should.', hours:3,
      steps:[
        { kind:'topic', ref:'backend-request-context', why:'One place seeding everything a request needs is what stops the same request from being applied twice.', do:'Write the middleware step that seeds your request context, and the one check inside it that would catch a duplicate submission.', min:25 },
        { kind:'topic', ref:'backend-errors', why:'An error is part of your API. A client that only gets a stack trace cannot act on anything.', do:'Design your error type: a numeric domain code, the HTTP status it maps to, and the one field the client can act on. Apply it to one error you already know you will hit.', min:25 },
        { kind:'part', ref:'cs-go-game-backend/api/api-errors', why:'A shipped backend stops duplicate submissions before the handler ever runs, not inside it.', do:'Say where yours would sit, based on where the shipped backend’s idempotency gate sits relative to the handler.', min:25 },
        { kind:'topic', ref:'backend-data-access', why:'Scoping a transaction to the request and sending the client only what changed are two separate disciplines that both prevent a whole class of bugs.', do:'Write the transaction boundary for one write operation in your service, and list only the fields it would send back to the client.', min:30 },
        { kind:'part', ref:'cs-go-game-backend/data/data-schemas-transactions', why:'A real service commits or rolls back several schemas as one decision. See what that looks like before you write your own.', do:'Write the one rule that decision follows, based on how the shipped backend opens and commits multiple schema transactions as a single decision.', min:25 },
        { kind:'prompt', ref:'implement', why:'Handing an AI assistant a clear implementation brief is a skill, and the brief itself is an artifact worth keeping.', do:'Use the implementation prompt template to brief an AI assistant on the error type and the transaction boundary you just designed, then compile and run what it produces with a test that submits the same request twice.', min:35 },
        { kind:'checklist', ref:'ai-verify', why:'What an AI assistant wrote for you is not verified until you have checked it against your own design.', do:'Run the AI output verification checklist against the code the assistant produced from your brief, and note what it changed that you did not ask for.', min:30 }
      ],
      review:['backend-layering'],
      check:{
        recall:[
          { q:'Where should an idempotency gate sit relative to the handler, and why?', a:'It sits in the middleware chain before the handler runs, typically as an add-if-absent cache key of player, method, and path with a short expiry, so a duplicate submission is rejected or replayed at the boundary instead of the handler executing the write twice.', ideas:['It sits in the middleware chain before the handler runs', 'typically as an add-if-absent cache key of player, method, and path with a short expiry', 'a duplicate submission is rejected or replayed at the boundary instead of the handler executing the write twice'] },
          { q:'What are the two disciplines that keep a transaction and a response both minimal?', a:'Scoping every transaction to the request, opened by the handler and committed or rolled back in one deferred place, and sending the client only the fields or tables a request changed rather than a full snapshot. Both keep a write or response from growing wider than the action that caused it.' },
          { q:'What must an AI output verification pass check, beyond whether the code compiles?', a:'Whether the code matches the actual design intent, not just that it builds: whether it introduced behaviour nobody asked for, whether error handling and transaction boundaries follow the agreed pattern, and whether it silently changed something the original brief never mentioned.', ideas:['Whether the code matches the actual design intent, not just that it builds', 'whether it introduced behaviour nobody asked for', 'whether error handling and transaction boundaries follow the agreed pattern', 'whether it silently changed something the original brief never mentioned'] }
        ],
        build:'Attach the request-context middleware, the error type and one transaction-scoped write handler, with a test that submits the same request twice and gets one write; the AI output verification result for the assistant’s code is supporting evidence.',
        solution:{ outline:'Add middleware that puts a deadline, a request id and the caller identity (set by the auth middleware) into the request context. Business inputs such as an item id stay function parameters. Define one error type that carries a code the client can act on and wraps the cause. Write one handler whose database writes sit inside a single transaction. Write the test: submit the same request twice with the same idempotency key and assert one row was written. Add the AI output verification result for the assistant code as support.', selfcheck:['Does every request carry a deadline from the caller context?', 'Does the error type keep the cause and give the client a stable code?', 'Do all writes of one action commit or roll back together?', 'Does the test prove the second submission changes nothing?'] },
        skip:['Can you write a request-context middleware step from memory?','Do you already give every error a code, a status and a client-actionable field, without being reminded?','Have you already caught an AI assistant changing something you did not ask for?','Can you scope a transaction to a single request without pulling in more than it needs, on the first try?']
      } },
    { id:'s5', t:'Idioms and tests', level:'intermediate',
      goal:'Write Go that stays readable at scale, keep the player’s progress safe across versions, and prove your service’s behaviour with tests whose expected values are not just pasted from a run.', hours:3,
      steps:[
        { kind:'topic', ref:'backend-go-idioms', why:'Context first, errors wrapped, goroutines owned, shutdown deliberate. These idioms are what keep a large Go service readable a year from now.', do:'Pick one function in your service that does not yet pass a context, wrap its errors, or own its goroutines, and rewrite its signature to fix it.', min:30 },
        { kind:'topic', ref:'backend-testing', why:'Three tiers answer three questions, and an expected value pasted from a run proves nothing was checked.', do:'Write one test where the expected value is derived independently of the code under test, not copied from its own output.', min:30 },
        { kind:'topic', ref:'craft-over-defensive-code', why:'Service code gathers nil checks and retries at every layer, and the topic’s test is the proof: remove a suspect guard, run the tests, and if nothing fails and the state cannot be produced, it only re-defended what a boundary already excluded.', do:'Read the overview, then pick one request path, mark each check as a boundary guard or a duplicate of an upstream one, and delete one duplicate with a test that still passes.', min:25 },
        { kind:'topic', ref:'craft-save-systems', why:'A live game owns the player’s progress, and the format’s version and the way it is written decide whether a patch or a crash costs them it.', do:'Read the overview, then add a version field to one saved record, write the migration from version 1 to 2 for a field you add, and a test that loads a version 1 record and gets a valid version 2 one.', min:30 },
        { kind:'tool', ref:'delegate', why:'Deciding what to hand an AI assistant and what to keep for yourself is itself a design decision worth planning.', do:'Run this stage’s two tasks (the idiom fix and the test) through the AI Delegation Planner and compare its split of AI-work versus your-work to what you did.', min:30 },
        { kind:'reflect', why:'Writing your own answer, not the guide’s, is what makes this workflow yours to repeat on the next service.', do:'In your own words, write the one habit from the path so far (layering direction, error wrapping, or AI verification) you are most likely to skip under deadline pressure, and the check that would catch you.', min:30 }
      ],
      review:['backend-data-access'],
      check:{
        recall:[
          { q:'What does wrapping an error preserve that a bare return does not?', a:'Wrapping keeps the original cause in a chain that errors.Is and errors.As can still walk, so code three layers up can still recognise it. Plain fmt.Errorf with %w adds context but no stack; the guide’s service error type also captures a stack at the wrap site, which tells on-call where the failure started.' },
          { q:'Why does a test with a pasted expected value prove nothing?', a:'An expected value copied from the code’s own output only proves the code still does what it did the moment the test was written, bugs included. It was never checked against the specification or master data, so it cannot catch a regression in the thing it claims to test.' },
          { q:'What does the AI Delegation Planner’s split decide?', a:'For each task it assigns an owner before work starts: Human, AI, both, or player evidence required for anything only a playtest can answer. It forces an explicit decision about who owns each task’s judgement instead of defaulting to whoever is available.' },
          { q:'Where does a defensive check belong in a layered service?', a:'At the boundary, where external input, deserialized data or an async re-entry arrives; behind it the code relies on that guarantee instead of re-checking it at every layer.', ideas:['At the boundary, where external input, deserialized data or an async re-entry arrives', 'behind it the code relies on that guarantee instead of re-checking it at every layer'] }
        ],
        build:'Attach the rewritten function with context first and wrapped errors, and a test whose expected value is derived independently, passing under go test -race; the Delegation Planner split is supporting evidence.',
        solution:{ outline:'Rewrite one function the Go way: context as the first argument, errors wrapped with %w and checked, no silently ignored errors (ignore one on purpose with `_ =` and a reason). Write a test whose expected value you derived by hand or by a separate method, not by running the function and copying. Run it with go test -race on a machine with a C compiler, and attach the clean result. Add the Delegation Planner split showing which part the assistant drafted and which part you wrote and checked yourself.', selfcheck:['Does the function take context first and pass it down?', 'Are all errors wrapped or handled, none dropped?', 'Is the expected value independent of the code under test?', 'Does the test pass under go test -race?'] },
        skip:['Can you spot a goroutine your own code does not own, on sight?','Do you already derive a test’s expected value independently, as a habit?','Can you decide what to delegate to AI and what to keep, before you start a task, not after?','Have you already named the habit you are most likely to skip under deadline pressure?','Can you point at the one boundary where each check in a request path belongs?']
      } },
    { id:'s3', t:'Cache, migrate, secure', level:'intermediate',
      goal:'Pick the right cache tier for the question being asked, ship schema changes separately from code, and keep secrets out of version control.', hours:3.25,
      steps:[
        { kind:'topic', ref:'backend-caching-redis', why:'Three cache tiers answer three different questions. Picking the wrong one means the cache is either wrong or pointless.', do:'For one hot read in your service, decide whether it belongs in a process-local cache, a distributed cache, or a per-request cache, say why the other two are wrong, and write the read through that tier with an expiry and a test that shows a hit and an invalidation.', min:35 },
        { kind:'part', ref:'cs-go-game-backend/data/data-caching-tiers', why:'A shipped backend keeps master data, mutable player state, and per-request reads in three different tiers on purpose.', do:'Place your own hot read from the previous step into the matching tier, based on how the three cache tiers are scoped.', min:25 },
        { kind:'topic', ref:'backend-migrations-config', why:'Schema changes ship separately from code, and secrets never ship at all. Mixing the two removes your option to roll back just one of them.', do:'Write the migration and its down migration for one schema change you have planned, apply both against a local database, and confirm the old code still runs between the two.', min:35 },
        { kind:'part', ref:'cs-go-game-backend/data/data-migrations-sharding', why:'A real system selects both a config block and a schema from one shard id, so the same code path serves every shard.', do:'Write what your own service would need to add to support more than one shard, based on how a shard id selects both configuration and schema.', min:25 },
        { kind:'topic', ref:'infra-secrets', why:'A credential in version control is public from the moment it is pushed. History is the boundary, not the commit.', do:'Grep your own repository history for one credential pattern (a key, a token, a connection string) and confirm what you would do if you found one.', min:25 },
        { kind:'part', ref:'cs-go-game-backend/platform/platform-secrets-lesson', why:'Database credentials and a plaintext API token sat in a committed config for a real project, reachable to anyone with read access, forever.', do:'List the three places the credentials leaked from. Check whether your own project has an equivalent of any of them, based on the secrets lesson.', min:25 },
        { kind:'flow', ref:'cs-go-game-backend/match-verification', why:'A client’s result is never trusted by itself. Seeing why shows what your own data layer has to be honest about.', do:'Walk the match verification flow and write the one comparison step your own service would need before it commits a client-submitted result.', min:25 }
      ],
      review:['backend-request-context'],
      check:{
        recall:[
          { q:'How do you decide which of the three cache tiers a given read belongs in?', a:'Ask what question the read is answering. Data almost immutable between releases belongs in a process-local cache, mutable state more than one instance must agree on belongs in a distributed cache, and a value read more than once inside one request belongs in a per-request memo cache.' },
          { q:'Why does a schema migration need to deploy and roll back independently of the code that reads it?', a:'Code and schema land at different moments during a rolling deploy, so for the minutes in between, the running code has to work against both the old and new schema. Shipping them together removes the ability to roll back one without also reverting the other.' },
          { q:'What makes history, not the current commit, the real boundary for a leaked secret?', a:'Deleting a committed credential from the current file does nothing about every clone, fork, and CI cache that already holds it in history. The value is compromised the moment it is pushed, so rotation, not deletion, is the only real remedy.' }
        ],
        build:'Attach the up and down migrations, the cached read with a test showing a hit and an invalidation, and the comparison step you would run before committing a client-submitted result',
        solution:{ outline:'Write up and down migrations for one schema change and run both. Add a cached read through Redis with a test showing a hit, then an invalidation after a write that makes the next read miss. State the key, the expiry and who invalidates. Write the comparison step you would run before committing a result the client submitted: recompute or check it on the server and reject a mismatch. Note where secrets for the cache and database come from.', selfcheck:['Does the down migration really undo the up one?', 'Does the test show a hit and then a miss after invalidation?', 'Is it clear which code owns invalidation?', 'Does the server recompute or check client results before saving?', 'Do secrets come from the environment, not the repository?'] },
        skip:['Can you place a new hot read into the right cache tier without hesitating?','Have you already written a migration that deploys and rolls back independently of its code?','Would you catch a credential in a diff before it is committed, not after?','Can you name the comparison a server must run before trusting a client-submitted result?']
      } },
    { id:'s4', t:'Observe and operate live', level:'advanced',
      goal:'Make the service explainable in an incident, alert on what players feel, and decide what working means before you ship.', hours:3.92,
      steps:[
        { kind:'topic', ref:'backend-observability', why:'Logs, traces, profiles, and an event stream answer four different questions. None of them substitutes for another.', do:'For your service, name which of the four you currently have, and write the incident question the missing ones would have answered.', min:25 },
        { kind:'part', ref:'cs-go-game-backend/platform/platform-observability', why:'A shipped backend runs eight or more named log streams and a swappable tracing abstraction, all from one config.', do:'Decide which two your own service would need first, based on how the named log streams are scoped.', min:25 },
        { kind:'topic', ref:'infra-monitoring', why:'Time to notice dominates time to recover. An alert on a symptom players feel beats an alert on a metric nobody understands.', do:'Write one alert you would add today, the exact symptom it watches for, and the runbook link it should carry.', min:25 },
        { kind:'topic', ref:'server-liveops', why:'The game keeps running while you change it. Gates, versions, and scheduled jobs are how you stay in control of that.', do:'Name one change you will need to ship while players are online, and the gate or version check that lets you roll it out safely.', min:25 },
        { kind:'topic', ref:'realtime-connection-tier-at-scale', why:'A live game keeps chat, presence and notifications on long-lived connections, and the restart of one gateway is a reconnect storm the operators must plan for.', do:'Write what your clients do in the minute after a gateway dies: the backoff with full jitter, the handshake limit, and whether they resume or log in again.', min:30 },
        { kind:'topic', ref:'metrics-and-success', why:'Decide what would count as working before you ship, or you will grade the launch on whatever numbers happen to be easy to pull.', do:'Write the one metric that would tell you your live-ops change from the previous step worked, and the number that would make you revert it.', min:25 },
        { kind:'topic', ref:'craft-performance', why:'Observability tells you a live service is slow; profiling against a budget tells you why, and which fix is worth shipping.', do:'Read the overview, then apply its method to one endpoint: set a latency budget, profile it under realistic load, and write the largest cost the profile shows and the before and after measurement you would keep with the fix.', min:25 },
        { kind:'flow', ref:'cs-go-game-backend/push', why:'What happens between a merged pull request and a running deploy is where migration order and seed drift show up.', do:'Walk the push-to-production flow and write the one step that would catch a migration ordering mistake before it reaches players.', min:25 },
        { kind:'checklist', ref:'ai-verify', why:'An AI-drafted runbook or alert rule needs the same verification as AI-drafted code.', do:'Run the AI output verification checklist against one AI-drafted alert rule or runbook step, and note what it got wrong.', min:30 }
      ],
      review:['backend-caching-redis','infra-secrets'],
      check:{
        recall:[
          { q:'Which of the four observability signals would answer “why did this fail” versus “how slow is this”?', a:'The four are logs, traces, profiles and the player action event stream. A trace answers how slow, showing where the request’s time went; a log, with its captured stack, answers why it failed. A profile says why the machine is busy, and the event stream records what players did, not why the service broke.' },
          { q:'Why should an alert watch a symptom players feel rather than a raw metric?', a:'Time to notice dominates time to recover, and a symptom like players failing to log in is what the team promised to prevent, while a raw metric like CPU usage can spike for reasons that never touch a single player. Alerting on causes trains the team to ignore pages that matter.' },
          { q:'What decides whether a live-ops change is safe to ship while players are online?', a:'Whether it can go through a version or maintenance gate that lets only the endpoints that must still respond keep working, and whether every intermediate state between the data, server, and client releases is one a live session can safely sit inside.', ideas:['Whether it can go through a version or maintenance gate that lets only the endpoints that must still respond keep working', 'whether every intermediate state between the data, server, and client releases is one a live session can safely sit inside'] },
          { q:'Why profile against a budget instead of optimising what looks slow?', a:'A budget says how much time the work may take and a profile says where it actually goes, so you fix the measured largest cost rather than a guess.', ideas:['A budget says how much time the work may take', 'a profile says where it actually goes', 'you fix the measured largest cost rather than a guess'] }
        ],
        build:'Attach the alert rule with its runbook link, your busiest endpoint’s latency budget with a profile taken under load, and the metric and revert threshold you wrote; the AI verification of the alert rule is supporting evidence.',
        solution:{ outline:'Write one alert rule that fires on a symptom players feel, with a link to a runbook of first steps. For your busiest endpoint, write a latency budget and attach a profile taken under load, showing where the time goes. Name one metric you will watch after a change and the threshold at which you revert. Add the AI verification of the alert rule: does it fire on the failure you meant, and stay quiet otherwise?', selfcheck:['Does the alert describe a player-visible symptom, not a machine detail?', 'Does it link to a runbook with a first action?', 'Was the profile taken under load, not idle?', 'Is the revert threshold a number written before the change?'] },
        skip:['Can you name your service’s weakest observability signal without checking?','Have you already written a runbook-linked alert on a symptom, not a raw metric?','Can you ship a change to a live game and name the gate that makes it safe?','Do you already know what number would make you revert your last live-ops change?','Do you have a latency budget for your busiest endpoint and a profile that shows where it is spent?']
      } }
  ]
});

PATH('netcode-server-engineer', {
  t:'Netcode / game-server engineer', tag:'Decide who is right, what bit-exact costs, and why a client’s result is never trusted alone.',
  pick:'Build real-time multiplayer servers that hold up',
  track:'engineering', level:'advanced', hours:18.33,
  audience:'Backend engineers specialising in real-time multiplayer, who already run a service in production and want to reason about latency, authority, and reconciliation with the same rigour as a request handler.',
  outcome:'You can choose an authority model and defend it, hide latency with prediction, reconciliation, interpolation and rollback, design a wire protocol and a fan-out layer, and explain why a client’s result is never trusted by itself.',
  prereq:['live-game-backend-engineer'], next:['realtime-at-scale-engineer','senior-game-developer-ai-era','interview-prep-engineer'],
  stages:[
    { id:'s1', t:'Authority and truth', level:'advanced',
      goal:'Decide who is right when two machines disagree, judge a shot fairly despite latency, and see what bit-for-bit costs to guarantee.', hours:3.25,
      steps:[
        { kind:'topic', ref:'server-authority', why:'Someone has to be right. The wait the player feels while the truth arrives is a design decision, not a bug, and lag compensation is how a server judges a shot fairly despite it.', do:'Name your authority model (client, server, or a hybrid) for one contested action and the exact wait or correction the player feels when the server disagrees. Then work the topic’s lag-compensation example with your own numbers: pick a shooter latency and an interpolation delay, and write the time the server rewinds the target to.', min:35 },
        { kind:'topic', ref:'server-determinism', why:'Two machines reaching the identical last bit, not merely an equivalent answer, is a much harder claim than it sounds.', do:'List the three sources of nondeterminism most likely to break a bit-exact replay in your simulation (RNG, floating point, iteration order), write the fix for each, then write a test that runs a small simulation twice from one seed and one input list and compares the state after every step.', min:45 },
        { kind:'part', ref:'cs-go-game-backend/simparity/simparity-determinism', why:'A shipped system ported its own random generator and math helpers by hand because an equivalent answer was not good enough.', do:'Check whether your own simulation shares any of the same risk, based on why a hand-ported RNG and FMA-free math were necessary here.', min:30 },
        { kind:'part', ref:'cs-go-game-backend/simparity/simparity-trace-gate', why:'A fixture set diffed byte-for-byte on every push is what turns “probably still deterministic” into a fact, checked automatically.', do:'Write what your own project’s equivalent gate would need to fixture, based on how the golden-trace test compares every recorded step rather than only the final score.', min:30 },
        { kind:'tool', ref:'sysmap', why:'Authority, determinism, and re-simulation are three systems that constrain each other. Mapping them exposes which one is load-bearing.', do:'Build a System Relationship Map connecting your authority model, your determinism guarantee, and your anti-cheat plan, and mark which one breaks the other two if it changes.', min:30 },
        { kind:'game', ref:'super-smash-bros', lens:'gameplay', why:'Super Smash Bros. Ultimate sold over 38 million copies while its online play was criticised for lag, a clear case where a frame-precise game’s feel depends on how two machines agree on who hit whom.', do:'Read its gameplay lens, then write which side decides a hit under lockstep for a frame-precise fighter, and how many frames of input delay you would accept at 60 fps on a 100 ms round trip, and why.', min:20 }
      ],
      review:[],
      check:{
        recall:[
          { q:'What is the difference between an equivalent answer and a bit-exact one, and why does replay verification need the second?', a:'An equivalent answer means two implementations agree on the final result or its distribution. A bit-exact one means they reach the identical last bit at every step. Replay verification needs the second because equivalent-only implementations still diverge step by step on real match data.' },
          { q:'Name two sources of nondeterminism that break a bit-exact simulation replay.', a:'A platform’s random number generator producing different bit sequences unless ported by hand, and floating point operations the compiler is free to fold into a fused multiply-add, changing the result depending on the build. Both need a bit-for-bit port and math helpers that forbid the fold.' },
          { q:'Why does a trace gate compare every recorded step instead of only the final score?', a:'Two different simulations can land on the same final score while disagreeing about every step that produced it, so comparing only the final result would let that exact class of bug through. Diffing every recorded step fails on the first divergent instruction instead of averaging it away.' },
          { q:'In lag compensation, to what time does the server rewind a target, and why?', a:'To the time the shooter’s screen showed: the server clock when the shot arrives, minus the shooter’s one-way latency, minus their interpolation delay. It restores the target’s stored hit boxes for that moment, casts the shot, and applies the result now, so the shooter is judged on what they actually saw.' }
        ],
        build:'Attach your authority table for one contested action, the lag-compensation rewind worked with your own numbers, and a test that replays one recorded input list twice and gets identical state at every step; the System Relationship Map with the load-bearing dependency marked is supporting evidence.',
        solution:{ outline:'Make a table for one contested action (a shot, a pickup or a trade): what the client may request, what only the server decides, and what each side sees. Work the lag-compensation rewind with your own numbers: shooter latency, the tick to rewind to, and where the target was then. Write a test that replays one recorded input list twice and compares state at every step. Mark the load-bearing dependency on the System Relationship Map.', selfcheck:['Does the table say the server decides the outcome?', 'Is the rewind worked through with concrete ticks and positions?', 'Does the test compare every step, not only the final state?', 'Is any source of nondeterminism, such as time or random, fixed or seeded?'] },
        skip:['Can you name your authority model and the exact correction a player feels when overruled, without checking?','Have you already found and fixed a source of nondeterminism in a real simulation?','Do you know why your project’s replay or trace test compares every step rather than the final score?','Can you draw the dependency between your authority model and your anti-cheat plan from memory?']
      } },
    { id:'s2', t:'Sync and protocol', level:'advanced',
      goal:'Choose what to send and how often, and give the wire format the same discipline as an API.', hours:2.58,
      steps:[
        { kind:'topic', ref:'server-state-sync', why:'Send what changed, at a rate someone chose on purpose. The alternative is a rate nobody chose, discovered during a postmortem.', do:'Write your tick rate and the one piece of state you delta-encode rather than resend in full, and the reason you picked that rate.', min:30 },
        { kind:'topic', ref:'server-bandwidth-and-interest-management', why:'Choosing what to send is a budget per client, filled by priority: once state sync is chosen, the bytes it may spend are the next decision.', do:'Write the bytes per second your worst supported connection allows at your tick rate, and which entities a client would hear about through interest management.', min:30 },
        { kind:'topic', ref:'server-realtime-protocol', why:'A length, an op code, a message id, a payload. Everything past that is a decision you should be able to defend.', do:'Define your message envelope as a struct with encode and decode functions, add one field beyond the minimum with a rule for unknown fields, and round-trip it in a test.', min:30 },
        { kind:'part', ref:'cs-go-game-backend/realtime/realtime-framing', why:'Two independent servers sharing one wire shape means chat and matched play decode the same envelope and dispatch on the same switch.', do:'Write whether your own protocol could support a second server the same way, based on how the framed envelope is shared across two servers with different jobs.', min:30 },
        { kind:'topic', ref:'backend-request-context', why:'A realtime message still needs the same idempotency discipline as an HTTP request, or a retried packet gets applied twice.', do:'Add the field your realtime envelope needs so a duplicate delivery can be detected and dropped, then write the test that delivers the same message twice and asserts it is applied once.', min:35 }
      ],
      review:['server-authority'],
      check:{
        recall:[
          { q:'Why does sending only what changed still need a tick rate someone chose on purpose?', a:'Bandwidth grows with what you send, how often you send it and how many players receive it, so a rate nobody chose is discovered during a postmortem. Delta-encoding cuts the size of each message, but the rate still sets how stale a client can be and how much the server pays.' },
          { q:'What is the minimum a message envelope needs, and what does adding a field beyond that cost you?', a:'A length, an op code, a message id, and a payload. Anything past that is a decision that has to be defended, because it grows every message and every parser reading it, and adding a field later needs a compatibility rule, such as a version or skipping unknown bytes, so older clients can still parse the message.' },
          { q:'What field lets a realtime message detect and drop a duplicate delivery?', a:'A client-generated intent or request id repeated on every retry of the same action, so the server can store the outcome against that id and replay it rather than applying the action a second time when a retried packet arrives.', ideas:['A client-generated intent or request id repeated on every retry of the same action', 'the server can store the outcome against that id and replay it rather than applying the action a second time when a retried packet arrives'] }
        ],
        build:'Attach your tick rate with the one field you delta-encode, the envelope definition with its encode and decode, the rule for unknown fields and the idempotency field, and the test that delivers one message twice and shows it applied once',
        solution:{ outline:'State your tick rate and why. Pick one field and delta-encode it against the last acknowledged state. Define the message envelope with a type, version and sequence, plus encode and decode functions. Say what the receiver does with an unknown field or type. Add an idempotency field so a repeated message is not applied twice. Write the test: deliver one message twice and show it applied once.', selfcheck:['Is the delta taken against a state the client has acknowledged?', 'Does the envelope carry a version and sequence?', 'Is the rule for unknown fields written down?', 'Does the duplicate-delivery test pass?'] },
        skip:['Can you state your tick rate and the field you delta-encode without checking?','Can you sketch your message envelope field by field, from memory?','Have you already added an idempotency field to a realtime protocol, not just an HTTP one?','Could you add a field to your envelope without breaking an older client?']
      } },
    { id:'s2b', t:'Hide the wait: prediction and rollback', level:'advanced',
      goal:'Choose how each machine covers the wait for the authority, then build prediction, reconciliation, interpolation and a rollback loop that survives a late input.', hours:1.85,
      steps:[
        { kind:'topic', ref:'server-state-sync', tab:'godot', alt:'unity', why:'Prediction hides the wait for the authority, and reconciliation and interpolation stop that hiding from looking like teleporting. You only feel the trade-offs once you have watched a correction happen.', do:'Read the Godot tab, then build a client and a server in one project over a simulated 100 ms link: predict the local player from input, keep the unacknowledged inputs, reconcile by replaying them when a server state arrives, and interpolate a remote player between two snapshots. Log the size of every correction. In Unity, use a delayed message queue for the link.', min:45 },
        { kind:'topic', ref:'server-rollback-netcode', tab:'godot', alt:'unity', why:'Rollback trades waiting for the remote input for guessing it and repairing the guess, and it only works on the deterministic simulation you proved in stage one.', do:'Read the Godot tab, then step a two-player toy simulation at a fixed tick with a ring of saved states, predict the remote input by repeating the last one, deliver a real input three frames late, and check the state after re-simulation equals a run with no lateness. In Unity, keep the state in a struct ring buffer.', min:45 },
        { kind:'game', ref:'counter-strike-2', lens:'ui', why:'Counter-Strike 2 keeps a 64-tick server but timestamps every input at the instant it was made, so the tick stops being a hidden rounding error in the feedback chain.', do:'Read its ui lens, then decide for your own protocol whether input messages carry a time within the tick, and write how the server would use it when it simulates that tick.', min:20 }
      ],
      review:['server-state-sync'],
      check:{
        recall:[
          { q:'Why predict the local player but interpolate remote players?', a:'Your own input is known now, so applying it at once hides the round trip. Other players’ inputs are not known, so guessing them is often wrong; showing them slightly in the past between two real snapshots is smoother and more honest.' },
          { q:'What does reconciliation do when the server disagrees with a prediction?', a:'It takes the server’s state for the last acknowledged input and replays the inputs the server has not yet acknowledged on top of it, so the client lands where the server agrees. Small differences are blended in over a few frames; large ones are snapped with a cue that says the server disagreed.' },
          { q:'How does rollback differ from lockstep in what latency costs?', a:'Lockstep waits for every player’s input each frame, so latency becomes input delay. Rollback runs on a guess, usually the last remote input, and when the real one differs it restores a saved state and re-simulates, so latency becomes occasional visible corrections, paid for by saving, loading and stepping the whole state many times per frame.' },
          { q:'What does timestamping inputs inside a tick change, and what does it keep, as Counter-Strike 2’s sub-tick does?', a:'It keeps a 64-tick server simulation but records each input’s exact time instead of snapping it to the next tick boundary, so timing within a tick is no longer rounded away.', ideas:['It keeps a 64-tick server simulation', 'records each input’s exact time instead of snapping it to the next tick boundary', 'timing within a tick is no longer rounded away'] }
        ],
        build:'Run your prediction, reconciliation and interpolation demo over a simulated 100 ms link and attach its correction log, plus a rollback test that feeds an input three frames late and shows the re-simulated state matching a run with no lateness',
        solution:{ outline:'Run the prediction, reconciliation and interpolation demo over a simulated 100 ms link and attach its correction log. Show that the client predicts its own input, snaps or blends when the server disagrees, and interpolates other players between snapshots. Add a rollback test: feed one input three frames late and show the re-simulated state equals a run where it arrived on time.', selfcheck:['Does the log show corrections when the server disagrees?', 'Are other players drawn from interpolated snapshots, not raw positions?', 'Does the rollback test compare against an on-time run?', 'Is the link delay set in the test, not assumed?'] },
        skip:['Can you state your tick rate and the field you delta-encode without checking?','Have you already written client-side prediction with reconciliation and watched a correction happen?','Can you say which state a rollback game must be able to save, load and step, and why it must be deterministic?','Do you know what breaks first if your tick rate changed tomorrow?','Could you explain how sub-tick input timing differs from raising the tick rate?']
      } },
    { id:'s3', t:'Sessions and matchmaking', level:'advanced',
      goal:'Turn a ticket into a room, fan a message out across instances, and decide what a disappearing player means.', hours:4.07,
      steps:[
        { kind:'topic', ref:'multiplayer-design', why:'Matching is a design problem before it is a server problem: a lopsided match is not fun for either side, so decide the fairness rule the ticket has to express first.', do:'Read the topic, then write your game’s roles, the counter to its strongest move and the fairness rule a match must satisfy (rating gap, longest wait), so the ticket in the next step has something to encode.', min:25 },
        { kind:'topic', ref:'server-matchmaking', why:'A ticket, a rule set, a room, and an explicit answer to what happens when someone disappears. Skipping the last one is the common failure.', do:'Write your matchmaking ticket as a struct, a function that pairs tickets whose rule predicates fit, and the explicit rule for what happens to a room when one player disconnects mid-match, with a test for that rule.', min:40 },
        { kind:'topic', ref:'server-stack-choices', why:'Matchmaking and rooms run on a hosting layer you either build or buy. Choose the session model first, then the three layers, and keep a seam so a vendor shutdown costs a folder, not the game.', do:'Write your session model in one paragraph, mark each of the three layers as not needed, build or buy, and name the interface that would sit between your game and one vendor.', min:19 },
        { kind:'topic', ref:'server-framework-landscape', why:'With the session model and the layers chosen, the frameworks can be compared by mechanism: who owns the state, what travels, how latency is hidden and what they bill.', do:'Fill the topic’s three-column sheet for two frameworks that could run your authority model, with the date beside each cell.', min:25 },
        { kind:'part', ref:'cs-go-game-backend/realtime/realtime-matchmaking', why:'A ticket carrying capacity and rule predicates is what lets a matchmaker scan the pool for a set that satisfies everyone at once.', do:'Check whether your own ticket design could express a three-way match, not only a pair, based on how tickets carry their own rule predicates.', min:30 },
        { kind:'game', ref:'world-of-warcraft', lens:'ui', why:'World of Warcraft’s cross-realm Dungeon Finder shows what a matchmaking queue buys and costs: groups at any hour, and the loss of the server community that finding a group used to build.', do:'Read its ui lens, then write the role queue your own matchmaker would run, name one social tie it removes, and what, if anything, would replace it.', min:20 },
        { kind:'part', ref:'cs-go-game-backend/realtime/realtime-fanout', why:'Chat and presence running on more than one instance means a publish on one process has to reach subscribers on every other one.', do:'Write the one message type in your own design that would need the same fan-out, based on how the fan-out layer sits between the dispatch loop and Redis.', min:30 },
        { kind:'topic', ref:'backend-caching-redis', why:'A room or a matchmaking pool is exactly the kind of shared, fast-changing state a distributed cache tier exists for.', do:'Decide which of the three cache tiers your matchmaking pool belongs in, and justify it against the other two.', min:25 },
        { kind:'flow', ref:'cs-unity-multiplatform-port/session', why:'A session id shared across two environments, and a phone that can be interrupted at any time, are two failure modes a diagram makes obvious.', do:'Walk the multiplayer session flow and write the one step your own server-side session handling does not yet cover.', min:30 }
      ],
      review:['server-realtime-protocol'],
      check:{
        recall:[
          { q:'What must a matchmaking ticket explicitly answer besides capacity and rules?', a:'What happens to the room when a matched player disconnects or their app is suspended: whether the seat is held and for how long, whether they can reconnect, or whether the match ends or is forfeited. Reconnection is a product decision with a real cost; it has to be decided, not discovered.' },
          { q:'Why does a multi-instance chat or presence system need a fan-out layer at all?', a:'A publish on one instance only reaches clients connected to that process. With chat or presence spread across instances, a fan-out layer hashes each channel to a Redis publish-subscribe shard and re-publishes through it, so every instance holding subscribers for that channel delivers the message.' },
          { q:'Which cache tier does fast-changing, shared room state belong in, and why?', a:'The distributed tier, because a room or matchmaking pool is shared, fast-changing state that more than one server instance must agree on. A process-local cache would let each instance disagree, and a per-request cache would not persist between requests at all.' },
          { q:'What does a cross-server matchmaking queue gain and lose, as World of Warcraft’s Dungeon Finder did?', a:'Players on quiet realms could find a group at any hour through one cross-realm role queue, but server-based socialising, recognising names, building a reputation, asking a guild for help, stopped being needed to progress.', ideas:['Players on quiet realms could find a group at any hour through one cross-realm role queue', 'server-based socialising, recognising names, building a reputation, asking a guild for help, stopped being needed to progress'] }
        ],
        build:'Attach the ticket struct, a function that matches three tickets against their rule predicates, and a test where one player disconnects mid-match and your disconnect rule fires',
        solution:{ outline:'Define a ticket struct with the player, rating, mode and time queued. Write a function that matches three tickets against their rule predicates, such as a rating spread and a region. Write a test where one player disconnects after matching but before the match starts, and show your disconnect rule firing: return the others to the queue or fill the slot. Say how the queue scales across more than one process.', selfcheck:['Does the ticket hold everything the rules need?', 'Does the match function return nothing when the rules fail?', 'Does the test cover a disconnect between match and start?', 'Is it clear where the queue state lives?'] },
        skip:['Can you write your disconnect rule for a mid-match room without checking?','Do you know which message type in your protocol would need Redis fan-out, if you ran on more than one instance?','Have you already found the gap between a real session flow and your own server-side handling?','Can you name what your matchmaking queue removes from the social game as well as what it adds?']
      } },
    { id:'s4', t:'Scale and cheat', level:'advanced',
      goal:'Scale the stateless parts by adding copies, and treat the client as the attacker everywhere it touches a result.', hours:3.08,
      steps:[
        { kind:'topic', ref:'server-scaling', why:'Stateless parts scale by adding copies. The stateful parts are the whole problem, and pretending otherwise is how an outage starts.', do:'Classify your server’s components as stateless or stateful, and write the one stateful component you would need to solve first before adding a second instance.', min:30 },
        { kind:'topic', ref:'server-load-testing-and-capacity', why:'Scaling by copies only helps if you know how many players one copy carries, and that number comes from a load test shaped like real players.', do:'Write the arrival rate an open-model load test would start at for your game, and the reading (p99 tick time against players per instance) that would show the knee.', min:30 },
        { kind:'topic', ref:'infra-data-stores', why:'The database is the one component you cannot restart your way out of. The shard key you choose early is the one you are stuck with.', do:'Write your chosen shard key and the one query pattern that would break if you chose a different one.', min:30 },
        { kind:'topic', ref:'craft-memory-and-gc', why:'A stateful match cannot be scaled by adding copies, so its own hot path has to stay cheap: a tracing collector such as Go’s frees garbage when it decides to run, at a cost you did not schedule, and the rule of allocating at load and reusing in the loop holds for a message handler as for a frame.', do:'Read the overview, then count the allocations your message handler makes per packet, and pool or reuse the buffer made most often.', min:25 },
        { kind:'topic', ref:'server-anticheat', why:'The client is the attacker. Detect, keep the evidence, and decide the response separately from the detection.', do:'Name one cheat your game is vulnerable to, write its detection as a function with a test that a tampered result fails, and write the evidence you would keep and the response as two separate decisions.', min:40 },
        { kind:'part', ref:'cs-go-game-backend/simparity/simparity-anticheat', why:'Because the server re-runs the same simulation, a mismatch between a client’s claim and the server’s own re-simulation becomes the anti-cheat signal for free.', do:'Write whether your own architecture could re-run a client’s claimed result the same way, based on how re-simulation doubles as anti-cheat.', min:30 }
      ],
      review:['server-matchmaking','backend-caching-redis'],
      check:{
        recall:[
          { q:'Why can stateless components scale by adding copies while stateful ones cannot?', a:'A stateless component holds nothing between requests, so adding another copy behind a load balancer works immediately. A stateful component such as a live match holds session state in one process’s memory, so a client has to find that specific instance, and killing it kills the match.' },
          { q:'What are the three separate decisions in an anti-cheat response, and why keep them separate?', a:'Detection, which flags a suspicious result; evidence, which retains the replay and inputs for a human to review; and response, a separate policy decision ranging from a rejection to a rate limit to a shadow ban. Keeping them separate stops a noisy detector from directly triggering an unreviewable ban.' },
          { q:'Why does re-simulation give you an anti-cheat signal for free?', a:'Because the server already re-runs the same simulation independently to confirm the result is correct, comparing its own computed outcome against what the client submitted costs nothing extra to implement and catches a client lying about the result, on top of the parity check it already needed.', ideas:['Because the server already re-runs the same simulation independently to confirm the result is correct', 'comparing its own computed outcome against what the client submitted costs nothing extra to implement', 'catches a client lying about the result'] },
          { q:'Which rule from the memory topic carries from a frame loop to a match server’s message handler, and why?', a:'Allocate at load and reuse in the hot path, pooling whatever is created at message rate. A tracing collector such as Go’s frees garbage when it decides to run, so per-message allocation spends time you did not schedule inside the process that holds the match.' }
        ],
        build:'Attach the detection function with the test that rejects a tampered client result, the three-part anti-cheat decision, and your stateless and stateful classification with the shard key',
        solution:{ outline:'Write the detection function and a test that rejects a tampered client result, for example a score above what the inputs could produce. Write the three-part anti-cheat decision: what you detect, what you do about it, and what you accept. Classify each service as stateless or stateful and give the shard key for the stateful one, with the reason that key spreads load and keeps one player\'s data together.', selfcheck:['Does the test feed a result that cannot be produced legitimately?', 'Does the decision cover detect, respond and accept?', 'Is each service labelled stateless or stateful?', 'Does the shard key avoid a hot spot?'] },
        skip:['Can you classify every component in your server as stateless or stateful without checking?','Have you already picked a shard key and lived with a query pattern it made worse?','Can you separate detection, evidence, and response for a cheat you already know about?','Do you know whether your own simulation could re-run a client’s claim to verify it?','Do you know how many allocations your server makes per packet?']
      } },
    { id:'s5', t:'Ops and the client’s other half', level:'advanced',
      goal:'Keep the game changeable while it is live, and understand the multiplayer failure modes that live on the client side of the wire.', hours:3.5,
      steps:[
        { kind:'topic', ref:'server-liveops', why:'The game keeps running while you change it. Gates, versions, and scheduled jobs are how the server stays in control of that.', do:'Name one server-side change you will need to ship while a match is in progress, and the version gate that protects players mid-match from it.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/mp/mp-netcode-layers', why:'A commercial transport underneath a hand-written protocol is a common shape. Seeing where the seam sits tells you which layer owns which failure.', do:'Write which layer would own a desync bug in your own stack, based on where the transport layer ends and the hand-written protocol begins.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/mp/mp-host-interp', why:'Host mode and interpolation are a client-side authority model in disguise, with the same wait-for-truth trade-off as your server’s.', do:'Compare its trade-off to the authority model you wrote in stage one, based on how host mode measures and hides latency through interpolation.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/mp/mp-no-reconnect', why:'Treating a suspended app as already dead is a decision, and it is usually the wrong default for a phone.', do:'Write whether your own server-side session timeout matches that choice or fights it, based on why the client tears a session down on suspend instead of waiting.', min:25 },
        { kind:'part', ref:'cs-unity-multiplatform-port/mp/mp-obf-conflict', why:'A tool that renames things by name-based convention will eventually collide with a netcode layer that also resolves members by name.', do:'Check whether any build step in your own pipeline resolves anything by name at runtime, based on how a renaming build step broke name-based network resolution.', min:25 },
        { kind:'flow', ref:'cs-go-game-backend/match-verification', why:'The result a player sees is never the result that counts on its own, because the client’s simulation is not trusted by itself.', do:'Walk the match verification flow again, now from the server-scaling and anti-cheat side, and write the one step that would fail first under load.', min:30 },
        { kind:'tool', ref:'sysmap', why:'This is the last addition to the map. Confirm every system you have covered in this path still connects to the one thing a player feels: the wait.', do:'Draw the System Relationship Map of your whole design, connecting every node back to the player-felt wait time. Then run your server with 200 ms of injected latency, 10 percent packet loss and one client suspended mid-match, and write which node in the map each failure landed on.', min:45 }
      ],
      review:['server-scaling','server-anticheat'],
      check:{
        recall:[
          { q:'Why is tearing down a suspended session on a phone a decision, not a default?', a:'A suspended phone session is ambiguous either way, it might come back or might not, and a loud, immediate failure was chosen over a silent one where a stale client or leftover server state could keep operating it. Accepting no reconnect grace period is a deliberate design call, not a technical default.' },
          { q:'What kind of bug does a name-based renaming pass risk breaking in a netcode layer?', a:'A netcode library that resolves some of its generated network members by name at runtime is structurally incompatible with any renaming or obfuscation pass, because renaming those members silently breaks remote registration or replication in a way that only appears in a protected build, never in the editor.', ideas:['A netcode library that resolves some of its generated network members by name at runtime is structurally incompatible with any renaming or obfuscation pass', 'renaming those members silently breaks remote registration or replication in a way that only appears in a protected build, never in the editor'] },
          { q:'Which step in match verification is likely to fail first under load, and how would you decide?', a:'A well-grounded answer names the actual bottleneck in the design, such as the step that re-simulates or looks up a stored result under peak concurrent load, and explains why that specific step, rather than authentication or scoring, is where contention would first appear.', ideas:['A well-grounded answer names the actual bottleneck in the design', 'explains why that specific step, rather than authentication or scoring, is where contention would first appear'] }
        ],
        build:'Attach the log of a run with 200 ms latency, 10 percent packet loss and a mid-match suspend, with each failure traced to a node in the finished System Relationship Map, and the map itself.',
        solution:{ outline:'Run the full system with 200 ms latency, 10 percent packet loss and a mid-match suspend, and attach the log. For each failure that appears, trace it to a node on the System Relationship Map and say which layer should have handled it. Attach the finished map. Compare against the netcode layers, host interpolation, reconnect and conflict pages, and note which of those your build lacks.', selfcheck:['Does the log show all three conditions applied?', 'Is every failure tied to a named node on the map?', 'Does the map show what depends on what, not just what exists?', 'Is any missing layer named as a gap?'] },
        skip:['Can you name a server-side change you would need a version gate to ship safely mid-match?','Do you know which layer, transport or hand-written protocol, would own a desync bug in your own stack?','Have you already found a build step in your own pipeline that resolves something by name at runtime?','Can you trace every system in your design back to the wait time a player feels?']
      } }
  ]
});

PATH('realtime-at-scale-engineer', {
  t:'Realtime at scale engineer', tag:'Spend every byte on purpose, cut the world where the crowd is, and know the number of players a server carries before launch day does.',
  pick:'Take multiplayer from one room to a launch-day crowd',
  track:'engineering', level:'advanced', hours:8.5,
  audience:'Engineers who already run an authoritative game server and now need it to carry thousands of players: bandwidth per client, many rooms and one world, hundreds of thousands of open connections, a framework choice they can defend, and a capacity number from a test.',
  outcome:'You can write a per-client bandwidth budget and fill packets by priority, choose and operate a partition of the world, run a gateway tier that survives its own restart, compare multiplayer frameworks by mechanism and cost, and state players per instance from a load test, with the knee and the headroom.',
  prereq:['netcode-server-engineer'], next:['senior-game-developer-ai-era','interview-prep-engineer'],
  stages:[
    { id:'s1', t:'Budget the bytes', level:'advanced',
      goal:'Choose a carrier for each kind of message, and write the bytes per client per second as a number every later decision is checked against.', hours:1.83,
      steps:[
        { kind:'topic', ref:'server-transport-and-relays', why:'A lost packet blocks everything behind it on a stream, so which carrier you choose decides whether one loss freezes the game or skips one tick. Most of this layer is a library choice, not code to write.', do:'Label every message in your protocol by what losing it costs: latest-wins state, input, or a one-off event. Choose the carrier and reliability for each, then write the wrap-around sequence comparison as one function with a test across the boundary from 65,535 to 0.', min:45 },
        { kind:'topic', ref:'server-bandwidth-and-interest-management', why:'Bandwidth is a budget per client, filled in priority order, not a hope that the state fits. Writing the number first turns every later field and update rate into arithmetic.', do:'Write the budget for the worst connection you support: subtract the headers at your tick rate, divide by the entities you show at once, and write the bytes each entity may cost. Then quantise one position field from your map size and the resolution you need.', min:45 },
        { kind:'game', ref:'counter-strike-2', lens:'ui', why:'Counter-Strike 2 times every action to the instant it happened instead of the tick it fell in, which means the input message carries more than the key that was pressed.', do:'Read its ui lens, then work out what an input message costs per second at your tick rate if it carries a time within the tick, and check it against the upstream half of the budget you wrote.', min:20 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why does one lost snapshot freeze a TCP client, but not a UDP one?', a:'TCP delivers bytes in order, so snapshots 4, 5 and 6 wait until 3 is resent, more than a round trip later, and then arrive in a burst of old data. Over UDP the game uses 4 when it arrives. Snapshot 3 is never resent, because 4 replaced it; only a reliable event rides again until it is acknowledged.' },
          { q:'How does a priority accumulator keep a packet inside its budget without starving anything?', a:'Each tick every entity adds its priority to its own accumulator. The sender sorts by that value and writes entities until the byte budget is spent, then resets only the ones that fit. The rest keep their accumulated value, so a low-priority door eventually outranks a grenade and is sent.' },
          { q:'What decides how many bits a position costs on the wire?', a:'The range and resolution you choose from the map and the rules. A 2 km axis at 5 cm is 40,000 steps, which is 16 bits, so a whole position can be 44 bits instead of 96. Write the range and resolution next to the field as constants, and reject a value outside the range when reading.' }
        ],
        build:'Attach your message table labelled by failure cost with the carrier for each kind, the budget sheet (worst connection, headers at your tick rate, bytes per entity), one quantised field with its range and resolution, and the sequence-comparison test across the wrap.',
        solution:{ outline:'List every message and label it latest-wins, input or one-off event; send the first unreliable, the second unreliable with the last few inputs repeated, the third reliable. Write the budget: worst connection in bytes per second, minus headers times the tick rate, divided by the entities on screen. Quantise one position from the map size and a resolution such as 5 cm. Test the sequence comparison at 65,535 and 0.', selfcheck:['Is every message labelled by what losing it costs?', 'Does the budget subtract headers at your actual tick rate?', 'Is the resolution of the quantised field written next to it?', 'Does the test cover numbers either side of the wrap?'] },
        skip:['Can you say which of your messages are latest-wins, inputs and one-off events, without checking?','Do you know your bytes per client per second at the busiest moment, from a measurement?','Have you already written a priority-ordered packet writer that resets only what it sent?','Could you quantise a position for your map in your head?']
      } },
    { id:'s2', t:'Many rooms, one world', level:'advanced',
      goal:'Pick the cut that spreads your population over processes, make ownership explicit, and move what every shard shares into services.', hours:2,
      steps:[
        { kind:'topic', ref:'server-world-partitioning', why:'Shards, instances, layers, zones and match servers each answer who sees whom and what crosses a seam. The one cost that more machines never fix is a single cell that is too busy.', do:'Do the arithmetic for your worst moment: players in one space, pairs per tick and bytes per second, against what one process held in your load test. Write the family of cut it leaves you, and what you will do when one cell is still too busy.', min:45 },
        { kind:'game', ref:'world-of-warcraft', lens:'ui', why:'World of Warcraft’s cross-realm Dungeon Finder took group-finding out of the realm, a shard boundary, and put it in a service every realm could reach. Its ui lens records what that cost socially.', do:'Read its ui lens, then sort your own features into those that live in the zone or shard process and those that sit behind a service keyed by player or guild id, reachable from any shard. Name one social tie a cross-shard service would remove.', min:20 },
        { kind:'topic', ref:'server-scaling', why:'Stateless parts scale by adding copies. Partitioning is how the stateful part scales, and it only works if you know which part is which.', do:'Mark which of your components move into a shared service when you add a second shard and which stay per shard, and write the one that would break first if two shards wrote it at once.', min:25 },
        { kind:'tool', ref:'sysmap', why:'Ownership that changes in two places is a duplication bug waiting for a crash in the middle of a handoff. A map shows where it changes.', do:'Build a System Relationship Map of the ownership table, the handoff, the zone processes and the shared services, and mark the single place where ownership of an entity changes.', min:30 }
      ],
      review:['server-bandwidth-and-interest-management'],
      check:{
        recall:[
          { q:'Why does adding machines not fix a single crowded cell?', a:'Its cost grows with the players inside one space, roughly with the pairs that must see each other each tick, and one zone process must simulate them together. Only splitting the region by load, capping it, slowing time or spilling players to a layer helps that cell.' },
          { q:'What are the three steps of a safe handoff between two zone processes?', a:'The old owner sends the entity and its state with a version, the new owner accepts and acknowledges, and only then does the old owner release it. If the acknowledgement never arrives, the old owner keeps the entity and tries again, so the entity is never owned by nobody or by both.' },
          { q:'Why split a hot region at the median of the crowd, and merge at a lower threshold?', a:'The median puts about half the entities on each side, so both halves get relief, which a split by area does not promise. A merge threshold well below the split threshold stops a crowd that drifts back and forth from splitting and merging the zone over and over.' }
        ],
        build:'Attach the worst-moment arithmetic and the cut it led to, the ownership table with the three-step handoff, the list of features behind cross-shard services, and the System Relationship Map with the single place ownership changes.',
        solution:{ outline:'Work the worst moment: players in the busiest space, pairs per tick, bytes per second, compared with one process’s measured limit. Choose the cut (match per process, shards with instances, or zones with a plan for the densest cell). Keep a table from region to owning process, changed only in one place, and hand off in three steps with a margin around each border. Put chat, trade and guilds in services keyed by player or guild id.', selfcheck:['Is the arithmetic for the busiest moment, not the average?', 'Does the handoff release the entity only after the acknowledgement?', 'Are the split and merge thresholds different?', 'Is every shared feature reachable from any shard?'] },
        skip:['Can you name the cut your game uses and the number that made you choose it?','Have you already written a handoff that survives a crash between send and acknowledge?','Do you know which of your features would need a cross-shard service tomorrow?','Can you say what you do when one cell is still too busy after a split?']
      } },
    { id:'s3', t:'Many connections', level:'advanced',
      goal:'Hold hundreds of thousands of long-lived connections, fan a message out without blocking on slow clients, and survive the restart of a gateway.', hours:1.58,
      steps:[
        { kind:'topic', ref:'realtime-connection-tier-at-scale', why:'Chat, presence and live events are many connections and few messages each, the opposite shape to a match server. The memory per connection and the reconnect after a restart decide whether it holds.', do:'Work out the memory for 100,000 idle connections in your stack: kernel socket buffers, the runtime’s state per connection and your session object. Then open as many idle connections as your machine allows against a test build and compare resident memory with the estimate.', min:50 },
        { kind:'part', ref:'cs-go-game-backend/realtime/realtime-fanout', why:'A shipped fan-out layer between a dispatch loop and Redis shows the first stage of fan-out in a real system, before a channel is large enough to need the second.', do:'Write whether that design publishes once per instance holding subscribers or once per subscriber, and what changes for a channel with a million people online, based on how it hashes each channel to a Redis publish-subscribe shard.', min:25 },
        { kind:'topic', ref:'server-realtime-protocol', why:'A client that resumes instead of logging in again needs the envelope to carry a sequence number and a token. The resume is a protocol feature before it is a server one.', do:'Add a resume token and the last sequence number received to your envelope, and write the test in which a client reconnects after missing five messages and receives exactly those five.', min:20 }
      ],
      review:['server-world-partitioning'],
      check:{
        recall:[
          { q:'Why split the gateway tier from the logic tier?', a:'The gateway only holds sockets: it accepts, authenticates once, keeps the map of subscriptions and writes frames, so it scales on connection count. The logic tier owns channels and decides who hears what, so it scales on CPU and memory. Deploying them separately means a rules change does not drop every connection.' },
          { q:'What should a connection’s send queue do when it fills?', a:'It is bounded and never blocks the publisher. For state that the next message replaces, such as presence or positions, keep only the latest and drop the rest. For events that matter, such as a purchase or a match result, disconnect the slow client and let it resume from its last sequence number.' },
          { q:'Why does a gateway restart need full jitter and a handshake limit?', a:'Without jitter every client retries at the same backoff times, so the whole population reaches the login tier in waves. Full jitter spreads each retry randomly between zero and the cap, and a handshake limit answers the excess with try later (WebSocket close code 1013), keeping the rate at one that was tested.' }
        ],
        build:'Attach the estimate and the measured resident memory for your idle-connection test, the send-queue policy for each message type, the resume test that delivers exactly the missed messages, and your reconnect backoff with full jitter.',
        solution:{ outline:'Estimate memory per connection from socket buffers, runtime state and the session object, multiply by your target, then measure it with idle connections against a test build. Bound each send queue: latest-wins messages overwrite, important events disconnect the slow client so it resumes by sequence number. Add a resume token and last sequence to the envelope and test a resume after five missed messages. Retry with exponential backoff and full jitter, and limit handshakes per second.', selfcheck:['Was the memory per connection measured, not only estimated?', 'Does no send path ever block the publisher?', 'Does the resume test check that exactly the missed messages arrive?', 'Is the jitter random between zero and the cap?'] },
        skip:['Do you know the resident memory of 100,000 idle connections in your stack, from a test?','Have you already bounded a per-connection send queue and chosen what it drops?','Can you describe what your clients do in the minute after a gateway dies?']
      } },
    { id:'s4', t:'Pick a framework', level:'advanced',
      goal:'Compare multiplayer frameworks by mechanism and by what they bill or limit, and prove the choice with a vertical slice you measured.', hours:1.58,
      steps:[
        { kind:'topic', ref:'server-framework-landscape', why:'Every framework answers the same five questions: who owns the state, what travels, how latency is hidden, where it runs and what it costs. Reading them that way turns a marketing page into a comparison.', do:'Write your session model on one line and your authority model in one word. Then fill a three-column sheet for three candidates from their official pages (how latency is hidden, the unit billed or limited, the number at which it stops being free) with the date beside each cell.', min:45 },
        { kind:'topic', ref:'server-stack-choices', why:'The framework sits inside a hosting layer and behind a seam you own. The cost of leaving it is the authority and prediction code you would rewrite, not the calls you would re-link.', do:'Write the small interface your rule code would call (spawn, set state, send input, receive a snapshot), and for each candidate the code you would have to rewrite rather than re-link if you left it.', min:25 },
        { kind:'tool', ref:'hypothesis', why:'A framework choice is a claim about cost and feel that a two-player slice can refute in a week. Writing the result that would make you drop it keeps the test honest.', do:'Write the vertical slice as a hypothesis: the framework holds your planned players per session at a stated server CPU, bytes per second per player and correction rate on a 100 ms, 2% loss link, and the measurement that would make you drop it.', min:25 }
      ],
      review:['realtime-connection-tier-at-scale'],
      check:{
        recall:[
          { q:'Which five questions does every multiplayer framework answer?', a:'Who owns the state: a server, a host, each client for its own objects, or nobody under determinism. What travels: snapshots, remote calls or input. How latency is hidden. Where it runs: a dedicated process, a player’s machine or a cloud room. What it costs or limits: a licence, a price per concurrent user, or the size of the box.' },
          { q:'Which family suits a fighting game, and which suits a co-op social room?', a:'A fighting game or a real-time strategy game wants deterministic input-only rollback: only inputs travel and every machine runs the same simulation. A co-op, social or casual room can take shared authority, where each client owns its own objects, because there is little to gain by cheating it.' },
          { q:'Why measure a two-player slice instead of comparing feature lists?', a:'The limits that decide the choice, such as server CPU per session, bytes per second per player and the correction rate on a bad link, only appear when the framework runs your tick rate and player count. A feature list says what exists, not what it costs you.' }
        ],
        build:'Attach your session model and authority word, the dated three-column sheet for three candidates, the interface your rule code calls with the rewrite cost per candidate, and the hypothesis card with the slice’s measured numbers or the plan to measure them.',
        solution:{ outline:'One line of session model (players, sessions at peak, length, persistence) and one word of authority. A sheet per candidate with latency hiding, billing unit and free limit, each cell dated from the official page. An interface for spawn, set state, send input and snapshots that keeps vendor types out of rule code. A hypothesis card naming the numbers the slice must reach on a 100 ms, 2% loss link and the result that rejects the framework.', selfcheck:['Is every cell of the sheet dated and from an official page?', 'Does the interface hide ownership, prediction and interest management?', 'Does the hypothesis say what result would make you drop the framework?'] },
        skip:['Can you name your authority model in one word and the frameworks that cannot run it?','Do you know what your current framework bills by and where it stops being free?','Have you already measured a framework on a lossy link before choosing it?']
      } },
    { id:'s5', t:'Prove it under load', level:'advanced',
      goal:'Find the knee with an open-model load test, set capacity left of it, and show the server sheds load instead of collapsing.', hours:1.5,
      steps:[
        { kind:'topic', ref:'server-load-testing-and-capacity', why:'The number of players a server carries is a measurement, and its overload behaviour is part of the product. Both come from a load test shaped like real players.', do:'Write a bot as a protocol client that connects, joins a room and sends inputs at the real rate, driven by an open-model generator at a chosen arrival rate. Ramp by doubling and plot p99 tick time against players per instance until it bends.', min:50 },
        { kind:'topic', ref:'infra-monitoring', why:'A capacity number stays true only while the readings that produced it are watched in production, where the real crowd arrives.', do:'Choose the four or five readings from your load test to alert on in production (p99 tick time, memory per room, connections, error rate) and write the threshold for each, below the capacity you measured.', min:25 },
        { kind:'reflect', why:'A capacity number without the conditions it was measured under is a guess, and the launch review will act on it.', do:'Write the paragraph your launch review reads: players per instance, where the knee was, the headroom kept, cost per concurrent user per hour, the recovery time after overload, and what you do at twice the expected peak.', min:15 }
      ],
      review:['server-bandwidth-and-interest-management','realtime-connection-tier-at-scale'],
      check:{
        recall:[
          { q:'Why does a closed-loop load generator hide a collapse?', a:'Each simulated client waits for its answer before sending the next request, so when the server slows down the generator slows with it and the chart stays calm. An open model sends at a chosen arrival rate, as real players do, so the growing queue and the timeouts show.' },
          { q:'Where do you set the capacity number, and why not at the knee?', a:'Comfortably left of where p99 tick time bends, commonly where it reaches 60 to 70% of the tick budget, so a busy moment, a lost zone or a slow dependency still fits. At the knee any extra load builds a queue and useful work starts to fall.' },
          { q:'What is goodput, and what keeps it flat under overload?', a:'Goodput is the work that finishes in time to be useful. Past the knee, queued requests time out and clients retry, so the server stays busy while goodput falls. Capping sessions, bounding every queue and refusing the excess early with a retry-after hint keeps goodput at capacity.' }
        ],
        build:'Attach the generator scripts and pass thresholds checked into the repo, the plot of p99 tick time against players per instance with the knee and the capacity marked, the capacity model (players per core, cost per concurrent user per hour) and the overload run at twice capacity showing shedding and the recovery time.',
        solution:{ outline:'Drive bots that speak your protocol from an open-model generator, doubling the arrival rate each passing run. Record p50, p99 and max tick time, memory per room, connections and error rate. Plot p99 tick time against players per instance, mark the knee and set capacity where p99 is about 60 to 70% of the tick budget. Turn it into players per core and cost per concurrent user per hour, then run at twice capacity and time the recovery.', selfcheck:['Is the generator open-model, sending at a chosen rate?', 'Is capacity set left of the knee, with the reason written?', 'Does the overload run show refused requests rather than a collapse?', 'Is the recovery time after the load drops recorded?'] },
        skip:['Do you know your players per instance from a load test, and where the knee was?','Have you already run a spike or breakpoint test and timed the recovery?','Can you say whether your load generator is open or closed model?']
      } }
  ]
});

PATH('performance-engineer', {
  t:'Performance engineer', tag:'Measure on the device that matters, then make the CPU, the GPU, memory, the backend and the web page each fit a written budget.',
  pick:'Make games and services fast on the hardware players own',
  track:'engineering', level:'intermediate', hours:9.67,
  audience:'Gameplay or backend engineers who can ship a feature and now own the frame time, the memory, the load time or the p99: they want the method behind each kind of slowness and the official tools that find it.',
  outcome:'You can capture before you change, decide whether the CPU or the GPU sets the frame time, lay data out for the cache, cut draws and overdraw, keep a phone out of thermal throttling, stream a world inside a memory budget, cut a backend’s tail latency and pass a web page’s Core Web Vitals, each with a before and after.',
  prereq:[], prereqAny:['gameplay-engineer-godot','gameplay-engineer-unity','live-game-backend-engineer'], next:['senior-game-developer-ai-era'],
  stages:[
    { id:'s1', t:'Measure first', level:'intermediate',
      goal:'Set a budget, capture the worst case on the target device, and state each optimisation as a claim you will re-measure.', hours:1.33,
      steps:[
        { kind:'topic', ref:'craft-performance', why:'Every later stage starts from a capture on the target device and a budget per system. Optimising before that is guessing where the time goes.', do:'Write your frame budget split by system, then profile a development build of your worst scene on the lowest target device and write frame time percentiles and the top three costs, with whether the CPU or the GPU sets the frame time.', min:40 },
        { kind:'game', ref:'cities-skylines', lens:'gameplay', why:'Cities: Skylines simulates every citizen as a traceable individual, a design decision that sets its CPU cost, and its lineage lens records the studio warning that the sequel’s performance might disappoint at launch.', do:'Read its gameplay and lineage lenses, then write the design decision in your own game that sets its CPU cost per frame, and the measured number that would tell you it has gone over budget.', min:20 },
        { kind:'tool', ref:'hypothesis', why:'An optimisation is a claim: this change will cut this cost by this much. Written as a hypothesis, it gets re-measured instead of assumed.', do:'Write your first optimisation as a hypothesis: the cost you measured, the change, the number you expect afterwards, and the capture that will confirm or refute it.', min:20 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why record frame time percentiles rather than an average?', a:'Players feel the slow frames, not the mean. A game that averages 14 ms with a 40 ms frame every second stutters. Percentiles over a capture of the worst scene show the hitches that an average smooths away.' },
          { q:'What do you do before changing code to make it faster?', a:'Set the budget, capture a development build of the worst scene on the target device, find the top costs and whether the CPU or the GPU sets the frame time, and write the gain you expect. Then change one thing and re-capture the same scene with the same settings.' }
        ],
        build:'Attach the frame budget split by system, the capture of your worst scene on the lowest target device with percentiles and the top three costs, and the hypothesis card for your first optimisation.',
        solution:{ outline:'Write the target hardware, the frame rate and a split per system (gameplay, physics, animation, rendering, UI). Profile a development build of the worst scene on the lowest target device, record frame time percentiles and the top three costs, and say whether the CPU or the GPU is the bottleneck. Write the first optimisation as a hypothesis with the expected number and the capture that will check it.', selfcheck:['Was the capture taken on the target device, not the editor?', 'Are percentiles recorded, not one frame?', 'Does the hypothesis name a number to re-measure?'] },
        skip:['Do you know your frame budget per system, written down?','Have you profiled your worst scene on the lowest target device this month?','Can you say whether your game is CPU or GPU bound, and how you know?']
      } },
    { id:'s2', t:'The CPU and its data', level:'intermediate',
      goal:'Make hot loops read fewer cache lines, shrink the work before laying it out, and stop allocating in the frame.', hours:1.58,
      steps:[
        { kind:'topic', ref:'craft-cpu-cache-and-data-layout', why:'A loop is limited by how many cache lines it drags in, not by how many additions it does. The fix is arithmetic you can do before you touch the code.', do:'For your hottest loop write elements per frame, bytes per element and bytes it reads per element. Split the hot fields into packed arrays and the cold ones elsewhere, then re-capture and keep the before and after.', min:50 },
        { kind:'topic', ref:'craft-memory-and-gc', why:'An allocation in the frame loop is a cost the collector charges later, at a moment you did not choose.', do:'Count the allocations per frame in your hot loop with the engine profiler, and pool or reuse the one made most often.', min:25 },
        { kind:'topic', ref:'craft-entities-and-scenes', why:'The engine’s entity model decides where your data lives: on objects in a tree, or in arrays an entity system packs for you.', do:'Write where the data of your hottest loop lives in your engine’s entity model, and whether a packed array of your own or the engine’s entity system should hold it.', min:20 }
      ],
      review:['craft-performance'],
      check:{
        recall:[
          { q:'Why is a loop over objects often limited by cache lines, not arithmetic?', a:'Memory moves in 64-byte lines, and a miss to RAM costs hundreds of cycles against a few for a level 1 hit. A loop that reads 16 bytes of a 128-byte struct drags in a whole line per element and uses at most a quarter of it, so the fetches set its time, not the additions.' },
          { q:'What does splitting hot from cold change for a loop over 5,000 enemies?', a:'Position and velocity move into packed arrays, so the loop reads 80,000 bytes in 1,250 lines instead of striding over 640,000 bytes and 5,000 to 10,000 lines. Every fetched byte is used, and the hardware prefetcher can follow one dense stream.' },
          { q:'Why fix an O(n squared) loop before the data layout?', a:'No layout beats a smaller n. Testing 10,000 units against each other is about 50 million tests a frame, 50 ms even at a nanosecond each. A uniform grid with cells as wide as the query radius tests only the 3 by 3 neighbouring cells.' }
        ],
        build:'Attach the byte count for your hottest loop, the before and after captures of the hot and cold split, and the allocation count per frame before and after pooling.',
        solution:{ outline:'For the hottest loop, write elements per frame, bytes per element and bytes read per element, and the cache lines that implies. Move the fields the loop reads into packed arrays indexed by id and leave the rest elsewhere. Remove any pairwise test with a uniform grid first if there is one. Count allocations per frame and pool the most frequent. Re-capture the same scene and keep both captures.', selfcheck:['Is the cache-line count worked out before the change?', 'Do the before and after captures use the same scene and settings?', 'Is the allocation count per frame lower afterwards?'] },
        skip:['Can you say how many bytes your hottest loop reads per element, and how many it fetches?','Have you already split hot and cold data and measured the result?','Do you know how many allocations your game makes per frame?']
      } },
    { id:'s3', t:'The GPU, desktop and phone', level:'advanced',
      goal:'Read a frame pass by pass, cut draws, overdraw and shader cost, and keep a phone out of thermal throttling.', hours:1.92,
      steps:[
        { kind:'topic', ref:'craft-gpu-rendering-cost', why:'The CPU records the frame and the GPU executes it, in parallel, and the slower one sets the frame time. A graphics debugger shows which pass is the expensive one.', do:'Decide whether you are CPU or GPU bound with the engine’s timers and a render scale of 0.5. Capture one frame with a graphics debugger and write the draws and milliseconds of each pass, then cut the tallest.', min:50 },
        { kind:'topic', ref:'craft-mobile-gpu-and-thermals', why:'A phone GPU shades the screen tile by tile in on-chip memory, so bandwidth to main memory is what costs heat. A phone that has warmed up runs slower than it did at minute one.', do:'Play your heaviest scene on the lowest phone you support for 15 minutes and log frame time and thermal status. Then audit one render pass: what each attachment loads and stores, and which stores nothing reads again.', min:45 },
        { kind:'reflect', why:'A render budget for the lowest device after ten minutes of play turns every new effect into a number to check, not a debate after it ships.', do:'Write the render budget for your lowest supported device from its minute-15 measurement: draws, on-screen triangles, overdraw factor, shadow-casting lights, texture memory and milliseconds per pass.', min:20 }
      ],
      review:['craft-cpu-cache-and-data-layout'],
      check:{
        recall:[
          { q:'How do you tell whether a frame is CPU or GPU bound before optimising?', a:'Compare the game and render threads and the GPU time against the frame time (Unreal’s stat unit, Unity’s Profiler, Godot’s Visual Profiler); the one close to the frame time is the bottleneck. Then drop the render scale to 0.5: a large fall in frame time means the frame is bound by pixels or bandwidth.' },
          { q:'Why does overdraw from transparent layers cost more than opaque overdraw?', a:'Opaque objects drawn front to back let the depth test skip hidden pixels before they are shaded. Transparent layers are drawn back to front and every layer is shaded and blended, so where smoke, glass and glow overlap one pixel can be shaded five times.' },
          { q:'Why is storing a depth buffer that nothing reads again expensive on a tile-based phone GPU?', a:'The GPU keeps colour and depth on chip while it shades a tile. Writing out a buffer nobody reads adds main-memory traffic to every tile of every frame, and that traffic costs far more energy than on-chip memory, so the phone heats and throttles sooner.' },
          { q:'Why measure a phone after fifteen minutes of play and not at launch?', a:'A phone without a fan runs at peak clocks only until it heats up, then lowers them, so its sustained speed is below its peak. The frame rate at minute 15 against minute 1 is the throttling cost players actually meet.' }
        ],
        build:'Attach the frame capture with draws and milliseconds per pass and the change to the tallest pass, the 15-minute warm log of frame time and thermal status on your lowest phone, and the load and store audit of one render pass.',
        solution:{ outline:'Show the CPU or GPU verdict with the engine timers and the render-scale test. Attach a frame capture listing each pass with its draws and milliseconds, and the change that cut the tallest pass with its new time. Log frame time and thermal status every few seconds for 15 minutes on the lowest phone and compare minute 1 with minute 15. List each attachment of one pass with its load and store action and remove stores nothing reads.', selfcheck:['Is the verdict backed by the render-scale test?', 'Is the cut pass re-captured on the same camera and device?', 'Does the warm log cover 15 minutes on the lowest phone?', 'Is each removed store one that no later pass reads?'] },
        skip:['Can you name the most expensive pass in your frame and its milliseconds?','Do you know your frame rate at minute 15 on the lowest phone you support?','Have you audited the load and store actions of your render passes?']
      } },
    { id:'s4', t:'Memory and loading', level:'advanced',
      goal:'Keep every device inside a written memory budget, and get each streamed area in before the player arrives.', hours:1.92,
      steps:[
        { kind:'topic', ref:'craft-memory-loading-and-streaming', why:'Memory budgets, load time and streaming each have a standard fix, and streaming is arithmetic you can do on paper: bytes, throughput, distance and speed.', do:'Write the memory budget for each supported device with a 10 to 15% margin. Then do the deadline arithmetic for one streamed area: margin over top speed against bytes over the throughput of your slowest load stage, and name the seam that buys time if it does not fit.', min:50 },
        { kind:'topic', ref:'infra-cdn-assets', why:'What the player downloads, and when, is the outer half of loading: the first install, background packs and the size of each update.', do:'Decide what goes into the first install and what arrives as background packs, and group your bundles by how often their contents change so an update does not re-download unchanged art.', min:20 },
        { kind:'game', ref:'microsoft-flight-simulator', lens:'business', why:'Microsoft Flight Simulator streams its scenery from the cloud, which its business lens says made the console version possible without the whole world on disk.', do:'Read its business and lineage lenses, then write which of your assets could stream after install, and what the game shows while they have not arrived.', min:20 },
        { kind:'part', ref:'cs-unity-multiplatform-port/runtime/runtime-budgets', why:'A shipped port sets its memory budget from the device’s measured memory tier, not from which platform it is, with separate figures for steady state, the spike of a scene load and the loading stage.', do:'Compare your budget sheet with its three numbers per tier, and add the load-spike and loading-stage figures if your sheet has only one.', min:25 }
      ],
      review:['craft-mobile-gpu-and-thermals'],
      check:{
        recall:[
          { q:'How do you work out whether a streamed area arrives in time?', a:'The deadline is the margin distance divided by the player’s top speed. The load time is the bytes divided by the effective throughput, which is the slowest stage you measured. If the load takes more than half the deadline, shrink the area or its assets, slow the player there, or add a seam.' },
          { q:'What is a seam, and why does it work?', a:'A lift, slow door, crawl space or airlock where the design controls the player’s speed and the camera, so it guarantees a number of seconds in which the next area can load. Write down those seconds and the data that must be in memory when the seam ends.' },
          { q:'Why can one stray handle keep a whole asset bundle in memory?', a:'Addressables counts references per asset and per bundle, and unloads a bundle only when its count reaches zero. One load never paired with a release holds everything in that bundle, so pair every load with a release and log the live handle counts in development builds.' }
        ],
        build:'Attach the memory budget sheet per device, the deadline arithmetic for one streamed area with its seam, the first-install and background-pack split, and a memory snapshot of your worst scene on the lowest device.',
        solution:{ outline:'List each device’s usable memory and split it into textures, audio, meshes, animation, scripts and engine, UI and a margin of 10 to 15%. Snapshot the worst scene on the lowest device and fix the top items. For one streamed area, compute margin over speed and bytes over the slowest measured stage, and design a seam with its guaranteed seconds if it does not fit. Keep the first install to the first hour and group bundles by how often they change.', selfcheck:['Is usable memory measured on the device, not taken from a spec sheet?', 'Does the throughput come from your slowest measured load stage?', 'Does the seam state its guaranteed seconds?', 'Are bundles grouped by how often they change?'] },
        skip:['Do you have a memory budget per device in the repo?','Can you work out the loading deadline of one of your areas in your head?','Do you know which load stage is slowest on your slowest drive?']
      } },
    { id:'s5', t:'Services and queries', level:'advanced',
      goal:'Measure a backend’s latency as a distribution, carry one deadline down the call chain, and fix the queries that cause most of the tail.', hours:1.5,
      steps:[
        { kind:'topic', ref:'backend-latency-and-query-optimisation', why:'Players meet the tail, and a screen that makes many calls is as slow as its slowest. The fixes that cause most real wins are a short, known list.', do:'Record the latency of one route as a histogram and report p99 and p99.9. Turn on the SQL log for one request and count its statements, then run EXPLAIN on the slowest statement against production-shaped data.', min:50 },
        { kind:'topic', ref:'backend-observability', why:'A trace shows where one slow request spent its time, call by call, which an average across all requests never will.', do:'Add a span around the slowest downstream call of your route, and read one slow request end to end to find the call or the wait that took the time.', min:20 },
        { kind:'topic', ref:'backend-data-access', why:'N+1 queries and OFFSET paging are the two data-access patterns that turn a fast query slow as the data grows.', do:'Replace one OFFSET page with keyset paging on the last row’s sort key and id, and compare the query plans before and after.', min:20 }
      ],
      review:['craft-memory-and-gc'],
      check:{
        recall:[
          { q:'Why does a screen that makes 100 calls meet the slow tail far more often than one call does?', a:'The screen is as slow as its slowest call. If 1 call in 100 is slow, the chance that a screen making 100 calls contains at least one slow call is 1 - 0.99 to the power of 100, about 63%, so the rare tail of one call becomes the usual case for the screen.' },
          { q:'What does a deadline carried down the call chain prevent?', a:'Work that cannot finish in time. Each call subtracts the time already spent and refuses to start if nothing is left, so a request past its deadline is dropped early instead of reaching the database. With a retry budget it also stops three layers that each retry three times from becoming 27 attempts.' },
          { q:'How do you spot an N+1 query?', a:'Log the SQL for one request and count the statements. If the count grows with the length of a list, each item is fetching its own rows. Replace the loop with one query using IN or ANY, a join, or a batch load keyed by id.' }
        ],
        build:'Attach the latency histogram for one route with p99 and p99.9 before and after, the statement count for one request and the plan of the slowest statement, the trace of one slow request, and the keyset paging change with both query plans.',
        solution:{ outline:'Record one route as a histogram with fixed buckets and report p99 and p99.9. Write the budget for the route and split it between its calls, with one deadline created at the edge and passed down. Count SQL statements for one request and remove any N+1 with a single query. Run EXPLAIN on the slowest statement, add or reshape the index it needs, replace OFFSET paging with keyset paging, and show p99 before and after on the same load.', selfcheck:['Are p99 and p99.9 reported, not a mean?', 'Does one deadline travel from the edge to every call?', 'Is the statement count independent of the list length afterwards?', 'Are before and after measured on the same load?'] },
        skip:['Do you know the p99 and p99.9 of your slowest route?','Have you already found and removed an N+1 query?','Does your service carry one deadline from the edge to the database?']
      } },
    { id:'s6', t:'The web, and the budget sheet', level:'advanced',
      goal:'Pass a web page’s Core Web Vitals on the device you test, then write the performance budget the rest of the team works inside.', hours:1.42,
      steps:[
        { kind:'topic', ref:'web-performance-basics', why:'A web page has two problems: bytes arriving, and one main thread answering input. Core Web Vitals turn both into three numbers judged on real page loads.', do:'Split the Largest Contentful Paint of your page into its four parts in the DevTools Performance panel and fix the largest. Then find one task over 50 ms and break it into chunks that yield between them.', min:45 },
        { kind:'topic', ref:'soft-launch-and-playable-ads', why:'A playable ad is the strictest web budget there is: the network sets a size cap and rejects anything over it.', do:'Write the size cap of the ad network you would target, and add a size check to your build that fails when the output goes over it.', min:20 },
        { kind:'reflect', why:'A performance engineer’s main output is a budget other people build inside. Written down, it turns a slowdown into a failed check instead of an argument.', do:'Write the performance budget sheet for your game: frame time per system or pass, memory per device, the loading deadline, p99 per route, and LCP and INP if you ship on the web. Mark each number that comes from a measurement and each that is still a guess.', min:20 }
      ],
      review:['backend-latency-and-query-optimisation'],
      check:{
        recall:[
          { q:'What are the three Core Web Vitals thresholds, and at what percentile are they judged?', a:'Largest Contentful Paint is good at 2.5 s or less. Interaction to Next Paint is good at 200 ms or less. Cumulative Layout Shift is good at 0.1 or less. All three are judged at the 75th percentile of real page loads.' },
          { q:'Why does a 300 ms script task make a tap feel slow, and what fixes it?', a:'One main thread runs scripts and input handlers, so a tap during the task waits for the task to end. Splitting the work into chunks of about 50 ms and yielding between them, with scheduler.yield and a setTimeout fallback, lets the tap run at the next yield.' },
          { q:'Why should the main image be in the HTML rather than added by a script?', a:'The browser’s preload scanner finds resources in the HTML and starts their download at once. An image a script adds is found only after the script runs, which adds delay to Largest Contentful Paint. Mark it fetchpriority="high" and never lazy-load it.' }
        ],
        build:'Attach the LCP breakdown before and after your fix, the long task before and after splitting it, the size check failing on an oversized build, and the performance budget sheet with measured and guessed numbers marked.',
        solution:{ outline:'In the Performance panel, split LCP into time to first byte, load delay, load duration and render delay, and fix the largest part, for example by putting the image in the HTML with fetchpriority high. Break one long task into chunks of about 50 ms that yield. Add a build step that fails when the output exceeds the network’s cap. Write one budget sheet covering frame time, memory, loading, p99 and the web vitals, marking measured numbers.', selfcheck:['Is LCP split into its four parts?', 'Does the split task yield at least every 50 ms of work?', 'Does the size check actually fail the build when exceeded?', 'Does the budget sheet mark which numbers are measured?'] },
        skip:['Do you know your page’s LCP and INP at the 75th percentile of real loads?','Have you already broken a long task into chunks that yield?','Does your team have a written performance budget that a build can fail?']
      } }
  ]
});

PATH('build-and-release-engineer', {
  t:'Build and release engineer', tag:'Make a release boring on purpose: one entry point, one provenance stamp, one rhythm.',
  pick:'Make builds and releases boring by design',
  track:'engineering', level:'intermediate', hours:15.5,
  audience:'Engineers responsible for CI/CD, build pipelines, and the release process for a game team, who have a project to build (the hands-on steps use a Unity project) and want a release that is boring by design rather than a fire drill every time.',
  outcome:'You can define and run a release checklist, build a player from a single parameterised entry point, and identify a pipeline smell before it costs a release.',
  prereq:[], next:['senior-game-developer-ai-era','technical-lead'],
  stages:[
    { id:'s1', t:'Pin the environment', level:'intermediate',
      goal:'Make the dev stack and the CI stack the same description, and replace near-identical pipeline jobs with one table.', hours:2.5,
      steps:[
        { kind:'topic', ref:'infra-containers', why:'Pin the toolchain in an image and the “works on my machine” class of bug disappears, because the dev stack and the CI stack are now the same description.', do:'Find the one tool version your local machine and your CI agent disagree on, pin it in an image or lockfile, and run your build inside that image.', min:25 },
        { kind:'topic', ref:'infra-ci-pipelines', why:'The pipeline turns a push into a verdict. Gate stages on the event, retry only the network, and check the verdict two ways.', do:'List your pipeline’s stages and mark which ones should gate on the event type (pull request versus push) rather than always running.', min:25 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/ci/ci-pipeline-table', why:'One declarative pipeline replacing eight near-identical trigger jobs is what a job-name table buys you, and a test that feeds it a corrupted table proves the check can fail.', do:'Count how many near-identical jobs your own pipeline could collapse the same way, based on how the job-name table replaced eight jobs.', min:25 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/ci/ci-agents-retries', why:'Selecting agents by label instead of by name, and retrying only the network calls, is what keeps a flaky checkout from failing an otherwise-good build.', do:'Write which flaky step in your own pipeline is missing a retry, based on which calls get retried (checkout, CDN upload) and which do not.', min:25 },
        { kind:'tool', ref:'sysmap', why:'A pipeline is a system with real dependencies between its stages. Map it before you try to collapse or reorder anything.', do:'Build a System Relationship Map of your pipeline’s stages and mark the one stage every other stage depends on.', min:20 },
        { kind:'engine', ref:'blender', why:'Art assets are build inputs too: pinning one Blender build and exporting from a script makes the art pipeline part of the environment you pin, not a manual step.', do:'Read the guide’s pipeline stage, then write a bpy script that exports one collection to glTF and run it headless with blender --background file.blend --python-exit-code 1 --python export.py; note the Blender version it ran on.', min:30 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why does pinning the toolchain in an image remove a whole class of bug, not just reduce it?', a:'Pinning the toolchain, database, and OS packages in an image means every laptop and every build agent run identical versions, so a whole category of failure, a query that works locally and fails in CI on a different collation or default, cannot occur rather than merely occurring less often.', ideas:['Pinning the toolchain, database, and OS packages in an image means every laptop and every build agent run identical versions', 'a whole category of failure, a query that works locally and fails in CI on a different collation or default, cannot occur rather than merely occurring less often'] },
          { q:'What does a job-name table let you collapse that eight near-identical jobs could not?', a:'A table keyed on job name, holding the handful of values that differed between eight near-identical jobs, lets one declarative pipeline with stages guarded by that name replace eight separate job definitions that had drifted apart under years of manual edits.', ideas:['A table keyed on job name, holding the handful of values that differed between eight near-identical jobs', 'lets one declarative pipeline with stages guarded by that name replace eight separate job definitions that had drifted apart under years of manual edits'] },
          { q:'Why should a checkout or upload retry, but a broken build not?', a:'Checkout and uploads fail for reasons unrelated to the code, such as network flakiness, so retrying them with backoff is honest. Retrying a broken build or a failing test destroys the evidence that something is wrong and trains the team to re-run until green instead of fixing the cause.' }
        ],
        build:'Attach the image or lockfile that pins your toolchain with the output of a build run inside it, and your pipeline’s near-identical jobs collapsed into one table; the System Relationship Map with the load-bearing stage marked is supporting evidence.',
        solution:{ outline:'Pin the toolchain in an image or lockfile with exact versions. Attach the output of a real build run inside it, showing the same result as on a clean machine. List your pipeline jobs and collapse the near-identical ones into one table with parameters. Mark the load-bearing stage on the System Relationship Map: the one whose failure blocks everything after it.', selfcheck:['Are versions pinned exactly, not left as latest?', 'Did the build run inside the pinned environment?', 'Does the table replace copied jobs with parameters?', 'Is the blocking stage marked, with a reason?'] },
        skip:['Can you name the one tool-version mismatch between your machine and CI, right now?','Have you already collapsed near-identical pipeline jobs into one table-driven job?','Do you know which of your pipeline’s external calls are missing a retry?','Can you draw your pipeline’s stage dependencies from memory?']
      } },
    { id:'s2', t:'Prove what shipped', level:'intermediate',
      goal:'Stamp provenance into the build at build time, keep secrets out of version control, and know within minutes when a pipeline fails.', hours:2.5,
      steps:[
        { kind:'topic', ref:'infra-artifacts-provenance', why:'The first question in any incident is which build this is. Stamp the answer in at build time, because you cannot add it later.', do:'Add the missing stamp (commit, branch or build number) to your build script and print all the stamped fields from a built artefact.', min:35 },
        { kind:'topic', ref:'ai-generative-assets', why:'Steam has required developers to disclose AI-generated content since January 2024. A provenance record kept at import answers that the way a build stamp answers which build this is.', do:'Pick one folder of shipped art or audio and write whether you could say, for every file, where it came from and who approved it.', min:25 },
        { kind:'topic', ref:'infra-secrets', why:'A credential in version control is public from the moment it is pushed. History is the boundary, not the commit.', do:'Scan your repository history with a secret scanner such as gitleaks, and write what you would do if it found a credential.', min:25 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/build/build-signing-artefacts', why:'A generated release note carrying job, repository, branch, and commit provenance is what makes “which build is this” answerable in seconds during an incident.', do:'Write whether your own build produces an equivalent artefact today, based on what the generated release note carries.', min:25 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/ci/ci-failure-notify', why:'Grading a failure from two independent signals is what stops a silent hang from being mistaken for a pass.', do:'Write which single signal your own pipeline currently relies on alone, based on the two signals used to detect a graded failure.', min:25 },
        { kind:'checklist', ref:'scope-sanity', why:'A release process that has quietly grown scope needs the same monthly sanity check as a feature list does.', do:'Run the scope sanity checklist against your current release process and write the one step that has crept in since you last reviewed it.', min:20 }
      ],
      review:['infra-ci-pipelines'],
      check:{
        recall:[
          { q:'Why can provenance not be added after the fact?', a:'The version, commit hash, build date, and toolchain version have to be captured at the moment the artefact is produced, because the exact commit under test and the toolchain state are gone once the job ends. There is no later point where that information can be reconstructed.' },
          { q:'What makes history, not the current commit, the real boundary for a leaked secret?', a:'A credential is compromised the instant it is pushed, because every clone, fork, and CI cache made since then keeps a plaintext copy indefinitely, regardless of the latest commit. Deleting it from the current file leaves it fully reachable in history, so rotation is the actual fix.' },
          { q:'Why does grading a failure need two independent signals instead of one?', a:'Either signal alone had already been wrong: a build tool can print a fatal error and still exit zero, and it can also exit non-zero after producing a usable artefact. Requiring agreement between a curated fatal-log-pattern check and the exit code catches what either one alone would miss.' }
        ],
        build:'Attach the build script change that stamps commit, branch and build number, an artefact that prints them, and the secret-scan output for your history; the scope sanity checklist result for your release process is supporting evidence.',
        solution:{ outline:'Change the build script to stamp commit, branch and build number into the artefact. Build it and show the artefact printing them. Run a secret scan over your history and attach its output, with any finding rotated and not just deleted. Run the scope sanity checklist on your release process and attach the result. Add a line saying how a signing key reaches the build without being committed.', selfcheck:['Does the built artefact print its commit and build number?', 'Does the secret scan cover history, not just the latest commit?', 'Was any found secret rotated?', 'Do signing keys come from the CI secret store?'] },
        skip:['Can you name every field your build artefact stamps, without checking?','Would you catch a credential in history, not just in the current diff?','Do you know whether your pipeline’s failure detection relies on one signal or two?','Have you already run a scope sanity pass on your release process this quarter?']
      } },
    { id:'s3', t:'Build the player', level:'intermediate',
      goal:'Drive every build target from one parameterised entry point, and know exactly what a build excludes and why.', hours:4,
      steps:[
        { kind:'topic', ref:'quality-and-build-health', why:'A game that cannot be played cannot be tested. A regular playable build is what keeps the whole evidence loop running.', do:'Write the last time your team had a build that would not run, what caused it, and the one gate that would have caught it earlier.', min:30 },
        { kind:'topic', ref:'craft-source-control-for-games', why:'A player build is only reproducible from what source control holds, and game repositories mix mergeable text with binaries that need locking and caches that must never be committed.', do:'Read the overview, then list what your repository commits, locks and ignores, and check that a fresh clone plus the build command reproduces the player build.', min:25 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/build/build-cli-entry', why:'One CLI-parameterised entry point building every target beats ten separate scripts that quietly drift apart.', do:'Count how many separate build scripts your own project could replace with one, based on the command-line flags one entry point uses to build every target.', min:30 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/build/build-two-pass', why:'A documented two-pass build working around a timing wart is a workaround worth naming on purpose, not hiding.', do:'Write one workaround in your own pipeline that deserves the same explicit documentation, based on why the build runs twice on purpose.', min:30 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/build/build-exclusion-lists', why:'A declarative exclusion list mirrored into source control means excluded content never even reaches the build agent.', do:'Write what your own build currently does with content that should not ship, based on how the exclusion list is mirrored as a sparse-checkout exclude.', min:30 },
        { kind:'flow', ref:'cs-unity-mobile-client-ci/player-build', why:'Walking a real player build end to end shows every place a target-specific decision gets made.', do:'Walk the player build flow and mark the one decision point your own build script does not yet make explicitly.', min:30 },
        { kind:'tool', ref:'sysmap', why:'The build entry point, the exclusion lists, and the signing step all depend on each other in a fixed order. Map that order before you change any of it.', do:'Add the build pipeline to your System Relationship Map from stage one, and mark which step blocks every step after it.', min:30 },
        { kind:'engine', ref:'unity', why:'One entry point that builds every target is the clearest fix for drifting build scripts, and Unity’s command line is a small, real place to write it.', do:'Read the guide’s pipeline stage, then write a static BuildScript.Build method that reads the target and output path from command-line arguments, and run it twice with -batchmode -quit -executeMethod for two different -buildTarget values, saving both logs. With another engine, use its command-line build.', min:40 }
      ],
      review:['infra-artifacts-provenance'],
      check:{
        recall:[
          { q:'What does a single parameterised entry point buy you over ten separate build scripts?', a:'The difference between build targets becomes data, a set of command-line flags read by one entry point, instead of ten separate scripts that duplicate setup and teardown and quietly drift apart from each other as each is edited independently.', ideas:['The difference between build targets becomes data, a set of command-line flags read by one entry point', 'instead of ten separate scripts that duplicate setup and teardown and quietly drift apart from each other as each is edited independently'] },
          { q:'Why document a workaround explicitly instead of just leaving the code as it is?', a:'An undocumented workaround looks exactly like a mistake to the next person reading the pipeline, and without an explanation they are likely to remove it, reintroducing the timing bug it was written to avoid. A comment at the call site preserves the reason past the person who wrote it.' },
          { q:'Why does an exclusion list need to be mirrored into the checkout step, not just the build step?', a:'If content is only excluded at the build step, it still reaches the build agent’s disk and can be picked up by accident. Mirroring the same list as a sparse-checkout exclude means the content never arrives on the agent at all, a stronger guarantee than trusting every build step to skip it.' },
          { q:'What does game source control do differently from ordinary Git use?', a:'It keeps Git for text, locks binaries that cannot merge, and never commits what the engine can rebuild, such as import caches.', ideas:['It keeps Git for text', 'locks binaries that cannot merge', 'never commits what the engine can rebuild, such as import caches'] }
        ],
        build:'Attach the entry script, the logs of building two targets with it from the command line, and your exclusion list for content that must not ship; the System Relationship Map of the build pipeline with its blocking step marked is supporting evidence.',
        solution:{ outline:'Write the entry script that a person or CI calls from the command line with a target argument. Attach the logs from building two targets with it. Write the exclusion list of content that must not ship, such as test scenes and debug tools, and show it taking effect. Draw the pipeline on the System Relationship Map and mark the step that blocks the rest.', selfcheck:['Does the same script run locally and in CI?', 'Do the two logs show different targets built?', 'Is something on the exclusion list proven absent from the build?', 'Is the blocking step marked?'] },
        skip:['Could you collapse your own build scripts into one parameterised entry point today?','Have you already documented a build workaround explicitly, instead of leaving a comment nobody reads?','Do you know what your build currently does with content that should not ship?','Can you name the one step in your build pipeline that blocks every step after it?','Does a fresh clone of your repository rebuild the player build with no manual step?']
      } },
    { id:'s4', t:'Deploy and deliver content', level:'intermediate',
      goal:'Pick a deploy model by what the workload holds, and ship content updates without shipping a new client.', hours:3.5,
      steps:[
        { kind:'topic', ref:'infra-deploy-models', why:'Processes on a VM, containers on a scheduler, functions per request, jobs on a clock. Pick by what the workload holds, not by what is fashionable.', do:'Name your service’s deploy model and the one property of its workload (state, duration, frequency) that justifies the choice.', min:30 },
        { kind:'topic', ref:'infra-cdn-assets', why:'Content shipping after the client ships means the hash in the path and the version in the manifest are the only things standing between a player and a stale asset.', do:'Publish two versions of one asset to a static bucket or a local file server with the content hash in the path, and confirm the first version’s URL still serves after the second is up.', min:40 },
        { kind:'part', ref:'cs-unity-multiplatform-port/cicd/cicd-ten-pipelines', why:'Ten build paths behind one entry point, documented in a table with time estimates, is what keeps a team from guessing which pipeline to run.', do:'Write whether your own team has an equivalent reference or relies on someone remembering, based on the table of ten named pipelines.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/cicd/cicd-declarative', why:'Three declarative pipelines sharing one stage shape is what keeps three build types from drifting into three different processes.', do:'Write which two pipelines in your own project could share a shape but currently do not, based on how the three pipelines share one stage shape.', min:30 },
        { kind:'tool', ref:'sysmap', why:'The deploy model and the CDN path scheme both depend on how content and code ship separately. Confirm the map shows that split.', do:'Add your deploy model and CDN scheme to the System Relationship Map, and mark whether code and content can currently ship independently.', min:30 },
        { kind:'engine', ref:'unreal', why:'Unreal is the clearest case of a scripted build pipeline: the Unreal Automation Tool’s BuildCookRun and BuildGraph show every stage from compile to package as a repeatable command.', do:'Read the guide’s pipeline and deploy stages, then write the BuildCookRun command line for a development build of one project for one platform, and sketch the BuildGraph nodes a CI job would add for a second.', min:25 },
        { kind:'platform', ref:'itch', why:'itch.io’s butler pushes each platform as a channel and patches players automatically, the smallest delivery pipeline a CI job can drive.', do:'Walk the release stage’s deploy walkthrough, then push a build to an itch.io channel with butler and a --userversion from a script, and note the CI secret it would need.', min:30 }
      ],
      review:['quality-and-build-health'],
      check:{
        recall:[
          { q:'What property of a workload should decide its deploy model?', a:'Whether the workload holds state, how long it runs, and how often it is invoked. A stateless request should scale by adding copies, a long-lived connection needs a supervised or scheduled process, and a periodic job belongs on a clock, so the work’s shape decides the model rather than fashion.' },
          { q:'Why does a CDN path need a content hash rather than a stable filename?', a:'A content hash in the path guarantees a changed file gets a new URL by construction, so it can never collide with a stale cached copy at any layer. A stable filename relies on every cache and CDN edge correctly noticing the file changed, which some intermediaries simply ignore.' },
          { q:'What does sharing one stage shape across pipelines prevent?', a:'It prevents the platform pipelines from drifting into different processes over time, because a change to how setup validates parameters or how a failure is graded is one edit applied everywhere those pipelines share a stage, rather than several edits that can fall out of sync with each other.', ideas:['It prevents the platform pipelines from drifting into different processes over time', 'a change to how setup validates parameters or how a failure is graded is one edit applied everywhere those pipelines share a stage'] },
          { q:'How does a CI job deliver a build to itch.io?', a:'With butler: BUTLER_API_KEY as a runner secret, then butler push per platform channel with a --userversion; later pushes to a channel patch players automatically.', ideas:['With butler: BUTLER_API_KEY as a runner secret', 'then butler push per platform channel with a --userversion', 'later pushes to a channel patch players automatically'] }
        ],
        build:'Attach the test that publishes two hashed versions of an asset and shows both URLs serving, the butler push you ran, and your deploy-model justification; the System Relationship Map showing whether code and content ship independently is supporting evidence.',
        solution:{ outline:'Write a test that publishes two hashed versions of an asset and shows both URLs serving, so older clients keep working. Attach the butler push you ran, with its output. Write your deploy model choice (replace in place, blue-green or staged) and justify it. On the System Relationship Map, show whether code and content ship independently.', selfcheck:['Does the hash in the file name change when the content changes?', 'Do both versions stay reachable after the second publish?', 'Is the deploy model justified against your rollback need?', 'Does the map show if content can ship without a code release?'] },
        skip:['Can you justify your service’s deploy model by its workload, not by habit?','Do you know whether your CDN path scheme hashes content or trusts a filename?','Have you already found two pipelines in your own project that could share one stage shape?','Can you ship a content update today without also shipping a new client build?','Could you push a build to an itch.io channel with butler from a script?']
      } },
    { id:'s5', t:'Release on a rhythm', level:'intermediate',
      goal:'Give the release a fixed departure time, trace a failure back to the phase that caused it, and validate and restore around every build.', hours:3,
      steps:[
        { kind:'topic', ref:'pm-qa-release', why:'A release train has a fixed departure time. Whatever is ready and green goes, whatever is not waits for the next one.', do:'Write your team’s current release cadence, and whether it is a fixed train or a deadline chasing whatever is not yet ready.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/cicd/cicd-phase-trace', why:'A two-hour log triaged by reading one line, because every phase re-prefixes a failure with its own name, is what a phase trace buys you.', do:'Write whether your own build logs let you triage a failure in one line or force a full scroll, based on how a failure gets re-prefixed with its phase name.', min:30 },
        { kind:'part', ref:'cs-unity-multiplatform-port/cicd/cicd-discipline', why:'Validating, grading, and restoring around every build is what stops a flaky result from being reported as a clean pass.', do:'Write the one step your own pipeline currently skips, based on what gets validated and restored around every build.', min:30 },
        { kind:'flow', ref:'cs-unity-multiplatform-port/release-build', why:'Walking a real desktop release build end to end shows every gate a release has to clear before it reaches a player.', do:'Walk the desktop release build flow and mark the one gate your own release process does not yet have.', min:30 },
        { kind:'platform', ref:'epic', why:'The Epic Games Store takes builds through BuildPatchTool into a Dev sandbox for testing, then Stage for review, then Live, a release rhythm with its own gates.', do:'Walk the release stage’s deploy walkthrough, then write the BuildPatchTool UploadBinary command for your build and the Dev-to-Stage steps you would run before submitting.', min:20 },
        { kind:'checklist', ref:'scope-sanity', why:'A release cadence, like a feature list, needs a monthly check that it has not quietly grown scope of its own.', do:'Run the scope sanity checklist against your release cadence one more time, now that you have added the gate from the previous step, and write what changed.', min:30 },
        { kind:'game', ref:'hearthstone', lens:'replay', why:'Hearthstone ships a new card set about every four months and retires old ones from Standard each year, a release rhythm players can plan around because its dates and rules are fixed in advance.', do:'Read its replay lens, then write which parts of your own release are fixed like a train and which part rotates out, and what you keep working for players who miss a release.', min:15 }
      ],
      review:['infra-deploy-models','infra-cdn-assets'],
      check:{
        recall:[
          { q:'What is the difference between a fixed release train and a deadline-driven release?', a:'A fixed release train has a departure time set in advance; whatever is ready and green ships and whatever is not waits for the next train. A deadline-driven release instead bends the calendar around whatever is unfinished, concentrating the riskiest changes at the moment closest to shipping.' },
          { q:'Why does re-prefixing a failure with its phase name matter for a two-hour log?', a:'When every stage tags a failure with the name of the phase that produced it, a two-hour build log can be triaged by reading that single re-prefixed line instead of scrolling through the entire log to find where things went wrong.', ideas:['When every stage tags a failure with the name of the phase that produced it', 'a two-hour build log can be triaged by reading that single re-prefixed line instead of scrolling through the entire log'] },
          { q:'What does validating and restoring around every build prevent?', a:'Validating parameters in a cheap setup stage before an expensive build starts catches a bad input in the first minute instead of after hours of work, and restoring the working tree before each run stops a build that mutates or deletes files from leaving broken state for the next run.', ideas:['Validating parameters in a cheap setup stage before an expensive build starts catches a bad input in the first minute instead of after hours of work', 'restoring the working tree before each run stops a build that mutates or deletes files from leaving broken state for the next run'] },
          { q:'How does a build reach the Epic Games Store?', a:'BuildPatchTool uploads it with the product’s BPT credentials and artifact ID; you set it active, test it in Dev through the launcher, push to Stage and submit for review.', ideas:['BuildPatchTool uploads it with the product’s BPT credentials', 'you set it active', 'test it in Dev through the launcher', 'push to Stage and submit for review'] }
        ],
        build:'Attach your release cadence written as a fixed train with its gates, a log sample or phase prefix change that lets a failure be triaged from one line, and the second scope sanity result showing what the added gate changed.',
        solution:{ outline:'Write the release cadence as a fixed train: dates, gates and who signs each gate. Add a log sample or a phase prefix change so a failure can be triaged from one line, with the phase named. Run the scope sanity checklist a second time after adding the gate and show what it changed. Say what happens to a change that misses the train.', selfcheck:['Does the train have fixed dates and named gates?', 'Can a failure be placed in a phase from one log line?', 'Does the second checklist run differ from the first?', 'Is the late-change rule written down?'] },
        skip:['Can you say whether your release cadence is a fixed train or a moving deadline, without checking?','Could you triage a failure in your own build logs from one line, or would you have to scroll?','Do you know the one validation or restore step your own pipeline currently skips?','Have you already added a release gate you previously did not have?','Could you upload a build with BuildPatchTool and move it to Stage?']
      } }
  ]
});

PATH('game-ai-programmer', {
  t:'Program game AI players can read', tag:'Build agents, allies and directors that read as intent, stay affordable, and use the cheapest mechanism that works.',
  pick:'Build readable, fair, affordable game AI',
  track:'engineering', level:'intermediate', hours:10.05,
  audience:'Programmers who can already build a gameplay loop in Godot or Unity and now own enemies, companions or a pacing system, and want to judge AI by what the player reads rather than by how clever it is.',
  outcome:'You can write an agent’s job and tells before choosing a technique, pick the cheapest mechanism that reads right, make it perceive and telegraph fairly, keep allies and directors in support of the player, and put a budget, a debug view and a fallback around anything smarter.',
  prereq:[], prereqAny:['gameplay-engineer-godot','gameplay-engineer-unity'], next:['senior-game-developer-ai-era','interview-prep-engineer','technical-lead'],
  stages:[
    { id:'s1', t:'What the AI is for', level:'intermediate',
      goal:'Write one agent’s job and its tells, then name the cheapest mechanism that produces the behaviour a player would read.', hours:2.15,
      steps:[
        { kind:'engine', ref:'godot', alt:'unity', why:'You already know your engine from the gameplay path, so this is a refresher on where an agent lives: in Godot a scene and in Unity a GameObject with components. Knowing where the scene tree or the player loop runs your code tells you where the behaviour will go.', do:'Read your engine’s guide, architecture stage, and write which scene and nodes (Godot) or which components and callback (Unity) your first agent will use.', min:14 },
        { kind:'topic', ref:'ingame-ai-purpose', tab:'overview', why:'Players experience behaviour, not architecture, so the job of the agent has to be fixed before any technique is picked.', do:'Write one agent’s job in one sentence tied to the fantasy and the loop, then write the player-facing tell for each important state: wind-up, patrol, flee, flank.', min:20 },
        { kind:'game', ref:'pac-man', lens:'gameplay', why:'Pac-Man’s four ghosts share one steering rule and differ only in their target, so a coordinated pack comes out of almost no code.', do:'Read the Pac-Man gameplay lens, then write each ghost’s target as a one-line rule and note where a player breaks the trap by turning early.', min:20 },
        { kind:'topic', ref:'scripted-vs-simulated', tab:'overview', why:'Simulation is a permanent cost in performance, balance and debugging, so the cheapest mechanism that reads right is the default.', do:'Pick three behaviours from your game, label each authored, faked or emergent, and write the cheapest mechanism that would produce the readable moment.', min:20 },
        { kind:'tool', ref:'gameai', why:'The chooser turns which technique into an answer with trade-offs, checked against the behaviours you just labelled.', do:'Run one of those agents through the In-game AI Technique Chooser and compare its answer to the mechanism you named.', min:20 },
        { kind:'topic', ref:'scripted-vs-simulated', tab:'godot', alt:'unity', why:'The cheap rung is a trigger and an authored animation, and building it once shows how little runtime decision-making a memorable beat needs.', do:'Build a one-shot trigger with Area3D.body_entered connected with CONNECT_ONE_SHOT that plays an AnimationPlayer beat. In Unity, do the same with a trigger collider and a Timeline played by a PlayableDirector.', min:25 },
      ],
      review:[],
      check:{
        recall:[
          { q:'What is in-game AI for, and what is the test that it works?', a:'Its job is to create a legible, fair, interesting situation and keep the fantasy alive, not to be smart. The test is that players narrate the agent’s intent, for example that it was trying to flank them.' },
          { q:'How can agents feel like a team without communicating, as Pac-Man’s ghosts do?', a:'All four use one steering rule, turn towards a target tile at each junction, and each has a different target. The pincer comes from four different goals, with no communication between them.' },
          { q:'What is the order of escalation in scripted vs simulated, and why default to the cheap end?', a:'Script it, fake it, constrain it, then simulate it, in ascending order of cost, risk and emergence. Simulation is a permanent cost in performance, balance surface, debug time and exploits, so escalate only with a testable reason the cheap version fails.' }
        ],
        build:'Export the In-game AI Technique Chooser result for one agent, and attach the one-sentence job, the tell list and the one-shot trigger scene.',
        solution:{ outline:'Run the chooser for one agent. Write its one-sentence job, such as keep distance and flank. List its tells, the signals that let the player read what it will do. Build the one-shot trigger scene: an area that fires once when the player enters, then never again. Attach all three. Say which technique the chooser returned and whether the job could be done by something simpler.', selfcheck:['Is the job one sentence with one verb phrase?', 'Does each action have a visible or audible tell?', 'Does the trigger fire only once?', 'Did you test whether a simpler technique does the job?'] },
        skip:['Can you state an agent’s job in one sentence tied to the fantasy, without naming a technique?','Can you list the tell for every important state of an enemy you have already shipped?','Have you already replaced a simulated behaviour with a script or a timer because it read the same?','Can you say which of your behaviours are authored, faked and emergent, right now?']
      } },
    { id:'s2', t:'Readable, fair and aware', level:'intermediate',
      goal:'Give an agent senses, memory and tells so every loss can be explained, and choose a technique by the decision it has to make.', hours:2.25,
      steps:[
        { kind:'topic', ref:'readable-and-fair-ai', tab:'overview', why:'Fairness is explainability: a hard fight is fair if the player can say why they lost and what they would do differently.', do:'List every place your AI breaks the player’s rules, such as knowing the hidden player or seeing off-screen, and decide for each whether to remove it, reveal it or compensate for it.', min:20 },
        { kind:'game', ref:'metal-gear-solid', lens:'gameplay', why:'Metal Gear Solid makes being seen a phase of play with a visible exit, so a mistake changes the situation instead of ending it.', do:'Read the gameplay lens, then write your stealth agent as infiltration, alert and evasion states with an evasion timer, and decide what the player’s map shows and when the game withholds it.', min:20 },
        { kind:'topic', ref:'perception-and-awareness', tab:'overview', why:'Perception is where fairness is decided: an agent that knows too much feels omniscient and one that knows too little feels deaf.', do:'Define your agent’s senses and parameters, then write how it loses the player: a last-known position with decay and a search behaviour that uses it.', min:20 },
        { kind:'topic', ref:'choosing-ai-technique', tab:'overview', why:'The technique decides what is easy and impossible later, and it is picked by the shape of the decision, the authoring cost and how easily it is debugged.', do:'For the agent from stage one, name whether a finite state machine, a behaviour tree, utility scoring or a planner fits its decision, and write one sentence on authoring cost and one on debugging.', min:25 },
        { kind:'topic', ref:'readable-and-fair-ai', tab:'godot', alt:'unity', why:'When the wind-up is an animation, its length is the reaction window, so tuning fairness means editing a clip rather than a damage number.', do:'Make an attack’s wind-up an AnimationPlayer clip, keep the hitbox Area3D off until the sequence opens it with set_deferred, and tune the reaction window by changing the clip length. In Unity, drive the same window from an Animator state and your own timing.', min:25 },
        { kind:'checklist', ref:'design-review', why:'A design review forces every question about the behaviour to get an answer before you tune it further.', do:'Run the design review checklist against your agent’s most important behaviour and write down what each group answered.', min:25 }
      ],
      review:['ingame-ai-purpose'],
      check:{
        recall:[
          { q:'What makes an AI loss fair, and what is a readability failure?', a:'Fairness is explainability: the player can say why they lost and what to do differently. It comes from telegraphing, committing to actions, showing tells and revealing or removing rule-breaking cheats. If testers answer that they are not sure why they lost, that is a readability failure.' },
          { q:'Why should sensing write to memory and behaviour read the memory, instead of reading the world?', a:'Separating them keeps what the agent knows explicit: it can lose the player, remember a last-known position and search, and testers can be asked what it should have known. An agent reading the world directly is omniscient and reads as unfair.' },
          { q:'How can being detected become a recoverable phase, and at what cost, as in Metal Gear Solid?', a:'A three-state machine with a timer: a guard’s sight starts alert mode, hiding starts evasion, and when its counter reaches zero the game returns to infiltration. The cost is that a forgiving alert can take away the fear of being seen.' },
          { q:'Which three things decide the technique for an agent?', a:'The shape of decision it expresses well, how cheap it is to author and change, and how easy it is to debug when the agent does something stupid.', ideas:['The shape of decision it expresses well', 'how cheap it is to author and change', 'how easy it is to debug when the agent does something stupid'] }
        ],
        build:'Export the design review results for one agent behaviour, and attach its state list, its senses and memory rules, and one wind-up timing.',
        solution:{ outline:'Fill in the design review for one agent behaviour. List its states and the transitions between them. List its senses (sight, hearing) and its memory rules: how long it remembers the player and how it forgets. Give one wind-up timing in frames or seconds and why it is long enough for a player to react. Attach all four.', selfcheck:['Does every state have an exit?', 'Does memory expire?', 'Is the wind-up long enough to dodge at a typical reaction time?', 'Do the senses match what the player can tell the agent can perceive?'] },
        skip:['Can you name the places your AI breaks the player’s rules and what you decided for each?','Have you already modelled losing the player, with a last-known position and a search?','Can you justify a state machine or a tree for an agent in one sentence, out loud?','Can you change an attack’s reaction window without touching its damage?','Have you asked testers why they lost and treated not sure as a defect?']
      } },
    { id:'s3', t:'Directors, allies and squads', level:'intermediate',
      goal:'Add a pacing director or a companion that supports the player without taking the win, and keep it from getting stuck.', hours:2.75,
      steps:[
        { kind:'topic', ref:'adaptive-and-director-ai', tab:'overview', why:'A director decides pacing where the designer cannot foresee every player’s tempo, and it only multiplies an encounter system that already works.', do:'Write the rhythm you want in tension and relief, choose the one or two least noisy signals such as deaths per encounter, and write the indirect response: frequency, composition or support rather than hidden power.', min:25 },
        { kind:'game', ref:'halo', lens:'gameplay', why:'Halo’s Covenant squads react to the player and to each other, a small case to test before a director sits on top, since a director is a multiplier on pacing that must already work.', do:'Read the Halo signature (mechanism, fair and prototype) and the gameplay lens, then write the rules for a shielded leader and three followers (when they flee, when they take cover, what happens when the leader dies) and prototype them in a grey-box arena you can run ten times; change only the terrain or the weapon on the floor and see whether the fight feels new.', min:40 },
        { kind:'topic', ref:'allies-and-companions', tab:'overview', why:'An ally’s hard part is restraint: useful, legible and never stuck, without taking the agency or the moment that belongs to the player.', do:'Write the ally’s contribution as a fraction of the player’s agency: what it may do and what it must leave to the player, such as the kill or the decision.', min:25 },
        { kind:'topic', ref:'allies-and-companions', tab:'godot', alt:'unity', why:'A companion that paths to a slot beside the player and has a leash and a recovery is one that stays out of the way.', do:'Give a CharacterBody3D companion a NavigationAgent3D that targets a slot behind the player, gate its barks with a Timer, and recover with NavigationServer3D.map_get_closest_point() when it is left behind. In Unity, use a NavMeshAgent chasing a slot transform with Warp as the recovery.', min:30 },
        { kind:'topic', ref:'navigation-and-pathfinding', tab:'overview', why:'A perfect decision is worthless if the agent gets stuck on a doorframe, and players read pathing failures as stupidity.', do:'Add stuck detection with a recovery order: sidestep, repath, then teleport as a last resort, and log every stuck event in a playtest.', min:25 },
        { kind:'tool', ref:'hypothesis', why:'A change to a director or an ally is a claim about how sessions feel, and it is not a fact until you name the signal that would show it.', do:'Write a hypothesis for one director response or one ally change, naming the signal and the kill criterion, and include a test with a skilled player and a struggling one.', min:25 }
      ],
      review:['perception-and-awareness'],
      check:{
        recall:[
          { q:'Why should a director respond by changing frequency, composition or support instead of hidden power?', a:'Indirect responses are readable and hard to catch. Strong hidden adjustments get noticed by experts and produce complaints that the game let them win or cheated them.' },
          { q:'What is the risk of building a director before the encounters are validated?', a:'A director is a multiplier on a system that must already work. Built first, it thrashes on noisy signals and hides whether the base pacing is any good.' },
          { q:'What are the two failure modes of an ally, and how do you tune against them?', a:'Over-effective allies make the player a passenger and under-effective ones are babysitting chores. Tune against a solo baseline and measure the player’s felt contribution, not the ally’s damage, with a never-stuck and never-blocking follow behaviour.' },
          { q:'What does a stuck-recovery order look like, and why teleport last?', a:'Sidestep, then repath, then teleport as a last resort. Teleporting avoids stuck states but breaks immersion, while strict pathing preserves immersion but fails on awkward geometry.' }
        ],
        build:'Export the hypothesis for your director or ally change, and attach the follow-and-recovery script or the director’s signal list.',
        solution:{ outline:'Write the hypothesis for your director or ally change: what behaviour should change and what you will measure. Attach either the ally follow-and-recovery script (keeps a distance, repaths when blocked, catches up when left behind) or the director\'s list of signals (player health, time since last fight, pace) with what each one changes. Say what result would make you remove it.', selfcheck:['Does the hypothesis name a measure?', 'Does the ally recover from being stuck or left behind?', 'Does the director read signals, not scripted time?', 'Is a removal condition stated?'] },
        skip:['Can you name the signals your director reads and the response it gives, without opening the code?','Have you already made an ally that never blocks a doorway and never gets left behind?','Do you know how often your agents get stuck in a playtest, from a log?','Can you test your director with a very skilled player and a struggling one?','Can you say what your ally is not allowed to do for the player?']
      } },
    { id:'s4', t:'Budgets, learning and shipping', level:'advanced',
      goal:'Put a frame budget, a debug view and a fallback around your AI, and decide where a learned or generative component may sit.', hours:2.9,
      steps:[
        { kind:'topic', ref:'ai-budgets-and-debugging', tab:'overview', why:'AI that is unaffordable or unexplainable does not ship, so the budget and the debug view come before the smarts.', do:'Set a per-frame AI budget and a worst-case agent count, then list the debug view’s contents: current state, decision reason, target and last-known positions.', min:25 },
        { kind:'topic', ref:'ai-budgets-and-debugging', tab:'godot', alt:'unity', why:'A named timeline marker and a read-back at runtime turn the AI cost into a number instead of a suspicion.', do:'Wrap the AI work in a ProfilerMarker, read it back with a ProfilerRecorder, and slice your agents by frame index so thirty of them never think on the same frame. In Godot, use Engine.get_physics_frames() modulo a slice count and Performance.add_custom_monitor.', min:30 },
        { kind:'topic', ref:'learning-based-ai', tab:'overview', why:'Learning is strongest off the player-facing path, and shipping a learned opponent is a different job from training one.', do:'Write which of your agents would be a learned policy, mark each as on or off the shipping path, and write the fairness envelope and non-learned fallback for any on it.', min:25 },
        { kind:'checklist', ref:'pre-prototype', why:'A learned bot or a sweep is a prototype, and it needs a hypothesis and a scope cut before it costs weeks.', do:'Run the pre-prototype checklist against your learned-bot idea and fix whatever it fails, or write down that the authored version is enough.', min:25 },
        { kind:'topic', ref:'learning-based-ai', tab:'godot', alt:'unity', why:'In Godot the honest place for learning is a headless training or sweep environment, and what ships is the tuned table the sweep produced.', do:'Sketch a headless run with godot --headless -s that runs the game as an environment with a seeded RandomNumberGenerator and quits with an exit code, and write what tuned table it would hand back. In Unity, the same job is ML-Agents against a built player.', min:30 },
        { kind:'topic', ref:'generative-characters', tab:'overview', why:'A language model can voice a character, but the game still decides what it may do, how long a reply may take and what happens when it fails.', do:'Write the action list and reply format for one character, then the authored line it falls back to on a timeout or an illegal action.', min:20 },
        { kind:'reflect', why:'Choosing the cheapest rung across the whole system is the judgement every earlier stage was practising.', do:'For your game’s AI as a whole, write which behaviour you would cut or downgrade to a cheaper mechanism, and the one player-read moment you would protect.', min:20 }
      ],
      review:['adaptive-and-director-ai','scripted-vs-simulated'],
      check:{
        recall:[
          { q:'Why set an AI budget and build the debug view first?', a:'Cost and balance grow with agents and capability, so a budget and worst-case agent count keep the design affordable, and a debug view of state, target and decision reason turns the AI is dumb into a specific, fixable cause.', ideas:['Cost and balance grow with agents and capability, so a budget and worst-case agent count keep the design affordable', 'a debug view of state, target and decision reason turns the AI is dumb into a specific, fixable cause'] },
          { q:'Where does learned AI fit today, and what must surround it when it is player-facing?', a:'It is strongest off the shipping path: testing bots, balance sweeps and animation or control. On the shipping path it needs a fairness envelope, determinism and replay plans, and a non-learned fallback.' },
          { q:'What does a generative character’s game code have to check?', a:'It parses every reply, checks the action against a fixed list, checks length and banned terms, moderates player-visible text, and falls back to an authored line on timeout or failure. The model proposes and the game decides.' }
        ],
        build:'Attach your AI budget and debug-view list, your pre-prototype checklist result, and the fairness envelope and fallback for any learned or generative component.',
        solution:{ outline:'Write the AI budget: milliseconds per frame and agents at full detail. List the debug views you will build, such as paths, vision cones and current state. Attach the pre-prototype checklist result. For any learned or generative part, state the fairness envelope, the range it may act in, and the fallback when it fails or is slow.', selfcheck:['Is the budget a number you can measure?', 'Can you see an agent\'s state and target in the game?', 'Does the learned part stay inside a stated range?', 'Does the fallback work if the model is unavailable?'] },
        skip:['Can you say your game’s per-frame AI budget and worst-case agent count from memory?','Can a bug report of your AI be replayed from a logged seed and inputs?','Have you already put a fallback under a learned or generative component?','Can you say why your best AI moment is the cheapest mechanism that produces it?']
      } }
  ]
});

PATH('interview-prep-engineer', {
  t:'Interview prep, engineering', tag:'Turn layering, authority, and build health into answers with a real trade-off in them.',
  pick:'Answer engineering interview questions with examples',
  track:'interview', level:'intermediate', hours:12.5,
  audience:'Anyone preparing for an engineering interview across gameplay, backend, server, infrastructure, game AI, or production roles, who has built in at least one of those areas and wants the app’s own frameworks as the backing for their answers, plus practice on the coding, gameplay-math and system-design parts.',
  outcome:'You can answer a structured interview question in any of these tracks with a real example, solve a timed data-structure, gameplay-math and system-design problem out loud, verify what an AI drafted for you, and tell your own project’s story instead of reciting a definition.',
  prereq:[], prereqAny:['gameplay-engineer-godot','gameplay-engineer-unity','live-game-backend-engineer','netcode-server-engineer'], next:[],
  stages:[
    { id:'s1', t:'Backend and server craft', level:'intermediate',
      goal:'Turn layering and authority from vocabulary into an answer with a real trade-off in it.', hours:2.5,
      steps:[
        { kind:'topic', ref:'backend-layering', tab:'interview', why:'An interviewer asking about layering wants to hear the trade-off you hit, not the definition of dependency inversion.', do:'Write your own two-sentence answer to the hardest one, using a real decision you made, based on the interview questions for layering.', min:25 },
        { kind:'topic', ref:'server-authority', tab:'interview', why:'Authority questions test whether you have felt the wait a player feels when the server overrules them.', do:'Write the one follow-up question you would ask back if you were the interviewer, based on the interview questions for authority models.', min:25 },
        { kind:'topic', ref:'craft-memory-and-gc', tab:'interview', why:'Allocation and garbage collection come up in engine and server interviews alike, and answers that name a measurement stand out.', do:'Answer the interview tab’s questions out loud, one from each level, and for each name the trade-off in your answer, such as pooling against reset bugs or structs against copies, and how you would measure it.', min:25 },
        { kind:'part', ref:'cs-go-game-backend/process/process-red-first', why:'“Tell me about your process” answers land better with a specific, named rule than with “we write tests”.', do:'Write the one sentence you would use to describe it if an interviewer asked how your team enforces test discipline, based on the red-first rule.', min:25 },
        { kind:'checklist', ref:'ai-verify', why:'“How do you use AI in your work” is now a standard question, and “I verify it” needs a real checklist behind it to sound credible.', do:'Pick the two items you would name if asked how you check AI-generated code, based on the AI output verification checklist.', min:25 },
        { kind:'reflect', why:'Writing your own answer, not the guide’s, is what makes it sound like your story instead of a memorised one.', do:'In your own words, write a sixty-second answer to “tell me about a backend decision you would make differently now,” using the layering or authority answer you just wrote.', min:20 }
      ],
      review:[],
      check:{
        recall:[
          { q:'What makes a layering answer sound like an interview cliché versus a real trade-off?', a:'An interviewer wants the actual trade-off a candidate hit while enforcing layering, such as a specific import-direction violation and what it cost to fix, not a textbook recitation of dependency inversion or the names of the rings.' },
          { q:'What follow-up question would you ask a candidate who gives a textbook authority-model answer?', a:'Ask for a concrete case that tests whether they built it: what happens when the model disagrees with the client, what a cheating client could get away with in the gap, or what the player literally sees during a correction.', ideas:['what happens when the model disagrees with the client', 'what a cheating client could get away with in the gap', 'what the player literally sees during a correction'] },
          { q:'What is the difference between “we write tests” and naming a specific rule your team enforces?', a:'We write tests is a general claim nobody can verify, while naming a specific enforced rule, such as requiring a failing test shown red before the fix that makes it pass, gives the interviewer something concrete to probe and shows the practice is followed.' },
          { q:'How do you answer a garbage collection question well?', a:'Explain where allocation happens, when the collector pays for it and how you would measure it, then name one fix such as pooling and the trade-off it brings, such as reset bugs in reused objects.', ideas:['Explain where allocation happens, when the collector pays for it and how you would measure it', 'then name one fix such as pooling and the trade-off it brings, such as reset bugs in reused objects'] }
        ],
        build:'Write out your sixty-second answer to “tell me about a backend decision you would make differently now,” and time yourself saying it out loud.',
        solution:{ outline:'Write your sixty-second answer and say it aloud with a timer. Pick one real backend decision. Use a short order: the situation, the choice, what happened, what you would change, and the lesson. Name one layer or authority rule from the stage. Cut anything that is not needed to land the lesson. Record your time.', selfcheck:['Did it fit in sixty seconds when spoken?', 'Does it name the decision, the result and the change?', 'Is there one concrete number or event?', 'Does it end on the lesson, not on a trailing detail?'] },
        skip:['Can you answer a layering question with a real trade-off, not a definition, right now?','Do you already have a follow-up question ready for an authority-model answer?','Can you name a specific process rule your team enforces, not just “we write tests”?','Have you already rehearsed your sixty-second decision story out loud?','Can you answer the memory and garbage collection interview questions with a measurement for each?']
      } },
    { id:'s2', t:'Infra, testing, and reliability', level:'intermediate',
      goal:'Back a monitoring or testing answer with a specific signal or rule, not a general principle.', hours:2.5,
      steps:[
        { kind:'topic', ref:'infra-monitoring', tab:'interview', why:'A monitoring answer that names an alert and a runbook beats one that says “we watch our dashboards”.', do:'Write the one incident story you would tell, naming the actual symptom that paged someone, based on the interview questions for monitoring.', min:25 },
        { kind:'topic', ref:'backend-testing', tab:'interview', why:'“What tiers of tests do you write” wants to hear how you keep an expected value honest, not a list of test framework names.', do:'Write your answer to the one about a test that passed but should not have, based on the interview questions for testing.', min:25 },
        { kind:'topic', ref:'craft-performance', tab:'interview', why:'Performance questions test whether you profile before you optimise and hold work to a budget.', do:'Answer the interview tab’s questions out loud, and for each say what you would profile first and which budget you would hold it to.', min:25 },
        { kind:'part', ref:'cs-go-game-backend/process/process-e2e-integrity', why:'A rule about what an end-to-end expected value is allowed to be is a sharper answer than “we have end-to-end tests”.', do:'Write the one sentence you would use to explain why an end-to-end test is the easiest place to accidentally test nothing, based on the end-to-end integrity rule.', min:25 },
        { kind:'tool', ref:'delegate', why:'“How do you decide what to hand to AI” is a real interview question now, and the planner gives you a concrete answer instead of a vibe.', do:'Run one task from your own recent work through the AI Delegation Planner, and write the one sentence that explains its split as your interview answer.', min:25 },
        { kind:'reflect', why:'Saying the story out loud once is what catches the parts that only sound good on paper.', do:'In your own words, write a sixty-second answer to “tell me about a monitoring or testing gap you found and closed,” using the incident or test story you just wrote.', min:20 },
      ],
      review:['backend-layering'],
      check:{
        recall:[
          { q:'What makes a monitoring answer specific instead of generic?', a:'A specific answer names the actual alert, the symptom it watches, such as players failing to log in, and the runbook that tells someone what to do at three in the morning. A generic answer only says the team watches dashboards, naming no decision and no action.' },
          { q:'Why is “a test that passed but should not have” a sharper story than “we have good test coverage”?', a:'We have good test coverage is unverifiable and often means little more than a high percentage. Describing a specific test whose expected value was pasted from the code’s own output shows the candidate understands that a green suite can still prove nothing was checked.' },
          { q:'What would you say if asked how you decide what to delegate to AI?', a:'State the categories explicitly: this task is Human because it needs judgement, this one is AI because it is repetitive and checkable, this one is player evidence required because only a playtest can answer it. Naming the split for a real recent task beats a vague comfort level with tools.' },
          { q:'What do interviewers listen for in a performance answer?', a:'Profiling before optimising, a stated budget such as frame time or latency, and a fix chosen by the measured largest cost.', ideas:['Profiling before optimising', 'a stated budget such as frame time or latency', 'a fix chosen by the measured largest cost'] }
        ],
        build:'Write and time your sixty-second answer to the monitoring or testing gap question.',
        solution:{ outline:'Write the answer for the monitoring or testing gap question and time it. Choose one real gap. Say what it cost or nearly cost, how you found it, the check or alert you added and how you know it works. Mention the red-first or end-to-end habit if you used it. Keep it to sixty seconds, and say it aloud once before you decide it is done.', selfcheck:['Does it name a real gap and what it cost?', 'Does it say how you now know it works?', 'Is it free of blame?', 'Does it fit in sixty seconds?'] },
        skip:['Do you already have a real incident story with a named symptom ready to tell?','Can you describe a test that passed but should not have, from your own experience?','Could you explain your AI delegation split in one sentence, on the spot?','Have you rehearsed this stage’s sixty-second answer out loud?','Can you answer the performance interview questions starting from a profile and a budget?']
      } },
    { id:'s3', t:'Game AI and production craft', level:'intermediate',
      goal:'Defend a technique choice and a prototyping decision the way a senior candidate would, with the alternative named.', hours:2.5,
      steps:[
        { kind:'topic', ref:'choosing-ai-technique', tab:'interview', why:'“Why a state machine and not a behaviour tree” only sounds confident if you can name what the other one would have cost you.', do:'Write your answer for one enemy or system, naming the technique you did not pick and why, based on the interview questions for choosing a technique.', min:25 },
        { kind:'topic', ref:'prototyping', tab:'interview', why:'“Tell me about a prototype that failed” is really asking whether you know the difference between a prototype and a demo.', do:'Write the one prototype of yours that answered no question, and what you would do differently now, based on the interview questions for prototyping.', min:25 },
        { kind:'topic', ref:'models-what-makes-agents-capable', tab:'interview', why:'Agent questions test whether you credit results to the whole system, model, context, tools, instructions, feedback and evals, and name the alternative to upgrading the model when an agent fails.', do:'Answer the interview tab’s questions out loud, and for each name the lever you would change instead of the model, with one example from your own use of coding agents.', min:25 },
        { kind:'part', ref:'cs-unity-mobile-client-ci/conv/conv-pr-review', why:'A fixed review checklist and a bilingual PR template is a concrete answer to “how does your team review code”, better than “we do code review”.', do:'Write the one item you would borrow for your own team’s review process, based on what the PR template requires a reviewer to verify.', min:25 },
        { kind:'tool', ref:'gameai', why:'Running your own answer through the same chooser an interviewer might expect you to reason with is a fast way to check it still holds up.', do:'Run the enemy or system from step one through the In-game AI Technique Chooser and check whether it agrees with the technique you defended.', min:25 },
        { kind:'reflect', why:'Saying the story out loud once is what catches the parts that only sound good on paper.', do:'In your own words, write a sixty-second answer to “walk me through choosing a technique for a real enemy,” using the technique and the chooser result from this stage.', min:20 },
        { kind:'game', ref:'metal-gear-solid', lens:'gameplay', why:'Metal Gear Solid shows guard perception as a view cone on a corner radar and backs it with a three-state alert, a clear case of stealth AI that players can read and recover from.', do:'Read its gameplay lens, then play the opening dock of Metal Gear Solid and get spotted once on purpose; then write down, as a state machine, the guard states and what moves the game from alert to evasion to infiltration.', min:20 }
      ],
      review:['infra-monitoring'],
      check:{
        recall:[
          { q:'Why does naming the technique you did not pick make an answer stronger?', a:'It shows the candidate weighed the alternative’s cost rather than reaching for the only technique they know. Explaining why a behaviour tree would have been harder to debug, or a planner too expensive to author, demonstrates the trade-off was real, not assumed.' },
          { q:'What is the difference between a prototype that failed and a prototype that answered no question?', a:'A prototype that failed tested a real hypothesis and the result said no, which is a useful outcome. One that answered no question was never built with a kill criterion or a signal to measure, so nothing was learned regardless of how it turned out.' },
          { q:'What does a fixed review checklist give an interview answer that “we do code review” does not?', a:'A fixed checklist names the exact evidence a reviewer must verify every time, such as confirming zero warnings or that a soft reset runs clean, so the answer points at something specific a general review reliably misses. We do code review names no particular check at all.' },
          { q:'What should an answer about AI coding agents cover?', a:'That results come from the whole system, model, context, tools, instructions, feedback and evals, so you attribute a failure before upgrading the model and back any claim with your own eval rather than a leaderboard, with an example from your own work.', ideas:['That results come from the whole system, model, context, tools, instructions, feedback and evals', 'you attribute a failure before upgrading the model', 'back any claim with your own eval rather than a leaderboard, with an example from your own work'] }
        ],
        build:'Write and time your sixty-second technique-choice answer, checked against the chooser tool’s result.',
        solution:{ outline:'Write the technique-choice answer and time it. State the problem, two options you weighed, the one you chose and the cost you accepted. Check it against the chooser result and say if they agree. Mention how you verified the choice by prototyping. Keep it to sixty seconds, and say it aloud once before you decide it is done.', selfcheck:['Did you compare at least two options?', 'Is the accepted cost named?', 'Does it agree with the chooser, or say why not?', 'Does it fit in sixty seconds?'] },
        skip:['Can you name the technique you did not pick for a real system, and why, on the spot?','Do you have a real prototype-that-failed story ready, not a hypothetical one?','Can you name one concrete thing your team’s code review process checks?','Have you rehearsed this stage’s sixty-second answer out loud?','Can you explain what makes a coding agent capable, with an example from your own use?']
      } },
    { id:'code', t:'Code, gameplay math and system design', level:'intermediate',
      goal:'Practise the parts of a game engineering loop that no story can cover: a timed problem, a gameplay-math check, a fixed timestep and a whiteboard design.', hours:2.75,
      steps:[
        { kind:'topic', ref:'careers-game-coding-interviews', why:'Game loops mix familiar data-structure questions, gameplay math and one larger system to design, and each needs practice on its own, out loud, without an engine to lean on.', do:'Read the topic, then write your plan for the next week: which data-structure problems, which gameplay-math problems and which system design you will do, in which language.', min:30 },
        { kind:'topic', ref:'craft-gameplay-math', tab:'interview', why:'Vectors, dot and cross products and interpolation come up in almost every gameplay loop, and the answers that land say what the number means before the formula.', do:'Answer ten gameplay-math questions aloud from the interview tab and the topic, and for the dot product one say what it tells you before you write it.', min:25 },
        { kind:'topic', ref:'craft-game-loop-timestep', tab:'interview', why:'“Why does physics run at a fixed rate” is a standard engine question with a short, checkable answer.', do:'Answer the interview tab’s questions out loud, then explain the accumulator and the clamp on a huge hitch in under a minute.', min:20 },
        { kind:'reflect', why:'A problem you solve under a clock, aloud, shows what you know; one you solve at leisure shows what you can look up.', do:'Set a 45-minute timer and solve three problems with nothing to look up, in your interview language: find the closest enemy to the player, find a path across a grid (BFS or A*), and build an object pool. Say the complexity of each aloud.', min:45 },
        { kind:'tool', ref:'sysmap', why:'A system-design question is a drawing exercise with a clock: services, state, and where it fails, said aloud while you draw.', do:'Whiteboard “design matchmaking for a 5v5 game” in the System Relationship Map in 30 minutes: the services, where state lives, the tick or ticket rate and the first failure you would test, then present it aloud in five.', min:40 }
      ],
      review:['craft-performance'],
      check:{
        recall:[
          { q:'Why is the dot product the usual answer to “is the enemy in front of me”?', a:'For unit vectors it is 1 straight ahead, 0 at right angles and -1 behind, so comparing it with the cosine of half the view angle answers the question without an angle or a square root. Say what the number means, then the formula.' },
          { q:'How do you explain a fixed timestep with an accumulator?', a:'Add the real elapsed time to a bucket, run the simulation in equal steps while the bucket holds a whole step, clamp a huge hitch so it cannot spiral, and draw with a blend between the previous and current state using the leftover time.', ideas:['Add the real elapsed time to a bucket', 'run the simulation in equal steps while the bucket holds a whole step', 'clamp a huge hitch so it cannot spiral', 'draw with a blend between the previous and current state using the leftover time'] },
          { q:'What do you do first in a game system-design question?', a:'Ask for the numbers that shape it (players, tick rate, latency budget), say who is authoritative, draw the smallest design that meets them, and name the first failure you would test, instead of listing technologies.', ideas:['Ask for the numbers that shape it (players, tick rate, latency budget)', 'say who is authoritative', 'draw the smallest design that meets them', 'name the first failure you would test'] }
        ],
        build:'Solve the timed set (closest enemy, grid path, object pool) in 45 minutes in your interview language and whiteboard the matchmaking design in 30, then attach both with the complexity you stated aloud and the failure you named first.',
        solution:{ outline:'Solve the closest-enemy search, a grid path and an object pool in your interview language within 45 minutes, then whiteboard a matchmaking design in 30. For each, state time and space complexity aloud. For the design, name the first failure you expect, such as a queue stall or a split party, and what you do about it. Attach code and sketch.', selfcheck:['Did each solution run on a small example?', 'Is the complexity stated for each?', 'Does the pool avoid allocating in the hot path?', 'Does the design name its first failure before it is asked?'] },
        skip:['Can you solve a data-structure problem in your interview language in twenty minutes without looking anything up?','Can you write a view-cone check with a dot product from memory and say what the number means?','Can you explain a fixed timestep with an accumulator in under a minute?','Have you already whiteboarded a game system design aloud against a clock?']
      } },
    { id:'s4', t:'Studio, ship discipline, and your story', level:'intermediate',
      goal:'Turn build health and success metrics into a story with a number in it, and close with the habit you would change.', hours:2.25,
      steps:[
        { kind:'topic', ref:'quality-and-build-health', tab:'interview', why:'“How do you keep a build healthy” wants a triage rule, not “we fix bugs quickly”.', do:'Write your answer to the one about triaging a bug that blocks the core loop versus a cosmetic one, based on the interview questions for build health.', min:25 },
        { kind:'topic', ref:'metrics-and-success', tab:'interview', why:'“How did you know it worked” is answered with a number and a threshold, not a feeling.', do:'Write the one metric and revert threshold from your own recent work that answers this cleanly, based on the interview questions for metrics.', min:25 },
        { kind:'part', ref:'cs-unity-multiplatform-port/process/process-compile-gate-ladder', why:'A written escalation ladder, from a compile check to a device build, is a concrete answer to “how do you decide how much to verify”.', do:'Write the one rung you would add to your own team’s verification process, based on the compile-gate ladder.', min:25 },
        { kind:'checklist', ref:'design-review', why:'Closing an interview answer with “and here is the checklist I ran” is a stronger ending than a general claim.', do:'Run the design review checklist against the last feature you shipped, and pick the one answer you would quote in an interview.', min:25 },
        { kind:'checklist', ref:'submit-pc', why:'“What breaks certification” and “how do you know a build is ready” are asked in engineering loops, and a named checklist item is something an interviewer can probe and you can defend.', do:'Run the PC submission checklist against the last build you shipped, pick the item that would have failed you, and write it as a thirty-second answer.', min:20 },
        { kind:'reflect', why:'This is the last reflect step in the path. Use it to name the one habit across all four stages you are least confident defending.', do:'In your own words, write the one habit from this whole path (a layering answer, a delegation split, a technique defence, or a metric) you are least confident defending under follow-up questions, and the one thing you will do this week to fix that.', min:20 }
      ],
      review:['choosing-ai-technique','server-authority'],
      check:{
        recall:[
          { q:'What is the difference between triaging a bug that blocks the core loop and a cosmetic one?', a:'A bug that blocks the core loop or a specific test goal stops the evidence loop entirely and gets fixed first regardless of how minor it looks. A cosmetic bug, however visible, waits behind it. The distinction is whether the bug stops learning something, not how it looks on screen.' },
          { q:'Why does “a number and a threshold” beat “it felt right” as an answer to “how did you know it worked”?', a:'A number and a revert threshold, decided before the change shipped, can be checked by anyone and force the team to state in advance what would count as failure. It felt right is an unfalsifiable impression that cannot be attributed to the change or challenged afterwards.' },
          { q:'What does a written verification ladder give you that “we test a lot” does not?', a:'A written ladder orders checks from cheapest to most expensive, states which rung a given change is expected to need, and can be checked afterwards against what was used. We test a lot names no order, no cost, and gives nobody a way to verify the claim was followed.' },
          { q:'Why answer a release-readiness question with a named checklist item?', a:'A named item, such as a build launched from a clean install with the crash reporter firing, is something the interviewer can probe and you can defend. “We tested it well” names nothing. Pick the item that once failed for you.' }
        ],
        build:'Write and time your final sixty-second answer combining the build-health or metrics story with the one habit you named as least confident.',
        solution:{ outline:'Write the final sixty-second answer that joins a build-health or metrics story with the one habit you named as least confident. Say the story, the number, and the practice you are building. Time it aloud. Check it against the design review and the compile gate pages for the terms you use, and cut any term you cannot define in one sentence.', selfcheck:['Does the story include a number?', 'Is the weak habit named honestly?', 'Does it fit in sixty seconds?', 'Are terms used as the pages define them?'] },
        skip:['Can you state your own core-loop-blocking triage rule on the spot?','Do you have a real metric and revert threshold ready from your own work?','Can you name the one rung you would add to your team’s verification ladder?','Have you named the habit you are least confident defending, and a concrete fix for it?','Can you name the submission checklist item that would have failed your last release?']
      } }
  ]
});

PATH('senior-game-developer-ai-era', {
  t:'Senior game developer in the AI era', tag:'Own the architecture, the checks and the team’s growth when agents write much of the code, and measure whether it helps.',
  pick:'Own architecture, checks and team when agents write code',
  track:'engineering', level:'advanced', hours:23.5,
  audience:'Working developers with shipped work, who have led features and whose role is shifting as AI takes over much of the typing: less writing modules, more owning boundaries, specifications, checks, review and other engineers’ growth.',
  outcome:'You can hold an architecture together under frame and memory budgets, turn a feature into a spec and an eval suite an agent or a colleague can be checked against, review AI-written changes for correctness, security and performance, budget the cost and latency of an AI feature, and plan a local measurement of whether AI helps your team. The evidence does not promise a speedup, so the path teaches you to measure it on your own code and to keep juniors learning.',
  prereq:[], prereqAny:['gameplay-engineer-godot','gameplay-engineer-unity','live-game-backend-engineer','netcode-server-engineer','build-and-release-engineer','game-ai-programmer'], next:['technical-lead','studio-practice-ai-era','interview-prep-engineer'],
  stages:[
    { id:'s1', t:'Architecture and boundaries', level:'advanced',
      goal:'Keep a codebase reviewable when changes arrive fast, by owning the module map, the data and the budgets.', hours:4,
      steps:[
        { kind:'topic', ref:'craft-engineer-in-the-ai-era', why:'One analysis of AI-assisted repositories found a large but short-lived jump in lines added and a lasting rise in warnings and complexity, which is why the module map is now the senior’s job.', do:'Draw the module map of a system you know, mark who may depend on whom, and write the three files an agent must never edit without you.', min:45 },
        { kind:'topic', ref:'craft-design-patterns', why:'Patterns are the shared names that let a reviewer see in seconds whether a fast change fits the structure or bends it.', do:'Pick two patterns your codebase uses and write for each the mistake a generated change is most likely to make against it.', min:30 },
        { kind:'topic', ref:'craft-entities-and-scenes', why:'Where data lives and who owns it decides whether many quick changes tangle or stay local.', do:'Write who owns the data for one entity type, and which systems may read or write it.', min:30 },
        { kind:'topic', ref:'craft-performance', why:'A frame and memory budget is a check that a plausible-looking change cannot talk its way past.', do:'Write the frame budget and memory budget for your target device and the measured cost of the most expensive system against them.', min:45 },
        { kind:'topic', ref:'lead-conventions', why:'Short rules stamped with their date and origin, kept next to the work, are what a reader, human or agent, meets before making the wrong call.', do:'Write three short rules for your repository in the imperative, each with the date and the incident behind it, and mark which of them a machine could check instead.', min:40 },
        { kind:'reflect', why:'A boundary you cannot state in a page is not one that an agent or a new hire can keep.', do:'Write an architecture decision record for one system (save or entity, say) against your frame and memory budgets, with the rejected option, the measured cost and the files an agent may touch. Solo: use your own project.', min:50 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why does the module map matter more when AI writes the code?', a:'Changes arrive faster than a person can read them, so structure is the only check that scales. One study of AI-assisted repositories found a short lived speed gain and a lasting rise in complexity and warnings.' },
          { q:'What goes in a decision record for a boundary?', a:'The choice, the rejected option and why, the measured cost against the frame and memory budget, and the date to revisit. It also names which files an agent may touch.' },
          { q:'Why state a frame and memory budget before reviewing a change?', a:'A budget turns "seems fine" into a number. A change that passes review by reading can still blow the budget, and only a capture on the target device shows it.' }
        ],
        build:'Write an architecture decision record for one system (a save or entity system, for example) against a frame budget and a memory budget: the rejected option, the measured cost, and the files an agent may touch. Solo: use your own project.',
        solution:{ outline:'Write an architecture decision record for one system. Give the context, the frame budget in milliseconds and memory budget in megabytes, the options considered, the one chosen, and the one rejected with its measured cost. List the files an agent may touch and those it may not. State the review condition that would reopen the decision.', selfcheck:['Are both budgets numbers?', 'Is the rejected option measured, not dismissed?', 'Are agent boundaries listed by file or folder?', 'Is there a trigger to revisit?'] },
        skip:['Can you draw your module map and say who may depend on whom?','Do you have a written frame and memory budget for your target device?','Do you keep decision records with the rejected option in them?','Can you name the files an agent may not edit without review?']
      } },
    { id:'s2', t:'Specify and verify', level:'advanced',
      goal:'Turn a feature into a spec an agent or a colleague can build, and prove the result with checks you wrote first.', hours:5,
      steps:[
        { kind:'topic', ref:'ai-agentic-implementation', why:'An agent edits files and runs commands until a check passes, so the unit of work is a task with a scope and a command that proves it done, and a green build alone proves little.', do:'Take one feature and write its task brief: goal, files in scope, acceptance command, and what the agent must not touch.', min:45 },
        { kind:'topic', ref:'craft-verification-as-the-job', why:'Generation is cheap and checking is human-paced, and the survey data on "almost right" code and debugging time points to verification as where the cost lands.', do:'List the checks that would fail a wrong version of your feature, and mark which run in seconds and which only in review.', min:45 },
        { kind:'topic', ref:'craft-tools-that-work-with-ai', why:'An agent can only use checks it can run, so fast tests and readable failures are part of the tooling.', do:'Time your test loop, and cut or split the slowest check an agent would have to wait for.', min:30 },
        { kind:'prompt', ref:'verify', why:'The pass puts a fixed set of questions to the model about its own output (assumptions, sources, what would prove it wrong); it exposes claims to check, and the checks you run in the other steps still do the proving.', do:'Run the pass on one AI-written change and write which step caught the first problem.', min:20 },
        { kind:'topic', ref:'ai-evals', why:'An eval is a fixed set of your own cases with a pass rule, so a change to a model or a prompt shows up as a number instead of a feeling.', do:'Write a starter set of ten cases for one model-backed feature, five expected and five hostile, with a pass rule, and decide which run on every change (the topic advises 50 to 200 inputs for a real set).', min:60 },
        { kind:'checklist', ref:'agent-rules-file', why:'The rules file is where the boundaries from the last stage become something an agent reads every time.', do:'Write the rules file for one repository, and cut every line you cannot check in a review.', min:20 },
        { kind:'topic', ref:'craft-teaching-agents', why:'Each repeated mistake is a rule or a test you have not written yet.', do:'Take the last three mistakes an agent made in your code and turn each into a rule or a failing test.', min:30 },
        { kind:'topic', ref:'craft-game-loop-timestep', why:'A fixed timestep with a seed makes gameplay replayable, which turns "it felt wrong" into a check an agent can run.', do:'Record a short input replay with a fixed seed and assert the end state, so a refactor that changes behaviour fails.', min:50 }
      ],
      review:['craft-engineer-in-the-ai-era'],
      check:{
        recall:[
          { q:'What must an agent-ready spec contain?', a:'The goal, the files in scope, an acceptance command that fails on a wrong result, and what must not change. Without the command, the agent and the reviewer disagree about done.' },
          { q:'Why write the failing tests before asking an agent to build?', a:'They define done in a way the agent cannot argue with, and they catch a change that edits the test to pass. Reviewers must also watch for deleted tests and loosened thresholds.' },
          { q:'What can a benchmark score not tell you?', a:'Whether the tool works on your code. Benchmarks have been found flawed (OpenAI reported flawed tests in a large share of audited SWE-bench Verified problems), so an eval built from your own cases is the check that counts.' },
          { q:'How does a replayable seed help verification?', a:'A fixed timestep and seed give the same run every time, so a behaviour change becomes a failing assertion instead of a feeling.', ideas:['A fixed timestep and seed give the same run every time', 'a behaviour change becomes a failing assertion instead of a feeling'] }
        ],
        build:'Write an agent-ready spec and an eval suite for one game feature: failing tests first, a property check with a replayable seed, and a golden set if the feature uses a model. Run it against an agent (or a colleague) and record what it got wrong. Solo: use a recorded agent session on your own project.',
        solution:{ outline:'Write the spec and eval suite for one feature. Put failing tests first. Add a property check with a seed that replays any failure. If a model is involved, add a golden set of inputs with accepted outputs. Run an agent or colleague against it and record what they got wrong. For each miss, note whether the spec, the tests or the agent was at fault.', selfcheck:['Do the tests fail before the work starts?', 'Can a failing property run be replayed from its seed?', 'Is there a golden set if a model is used?', 'Does the record say where each miss came from?'] },
        skip:['Do your tasks name an acceptance command before the work starts?','Can you replay a run from a seed and assert the end state?','Do you have a written list of cases for the feature that touches a model?','Do you check that tests were not changed to pass?','Do you convert repeated agent mistakes into rules or tests?']
      } },
    { id:'s3', t:'Review and security', level:'advanced',
      goal:'Review an AI-written change for correctness, security and performance, and say what you would block.', hours:4,
      steps:[
        { kind:'topic', ref:'lead-code-review', why:'Reviews that read only the new code miss deletions, changed tests and moved thresholds, which is where an AI change hides its problems.', do:'Review a recent change from the bottom up: tests and thresholds first, then deletions, then the new code.', min:40 },
        { kind:'topic', ref:'craft-what-matters-now', why:'If typing is cheap, reading and judging are where a senior’s time should go, and this topic names what to still care about.', do:'Write the five things you would check first in an unfamiliar AI-written module, in order.', min:25 },
        { kind:'topic', ref:'craft-security-review-of-generated-code', why:'In a controlled study, participants with an assistant wrote less secure code and were more confident in it, and vendor scans find a large share of generated samples with a flaw.', do:'List every place your game takes untrusted input (save, mod, network, model output) and review one generated handler for it.', min:60 },
        { kind:'topic', ref:'models-security-and-operations', why:'Model output that reaches a tool or a player is untrusted input, and prompt injection is the way it gets in.', do:'Trace one path from model output to an action in your project and write the check that sits between them.', min:40 },
        { kind:'topic', ref:'craft-over-defensive-code', why:'Generated code tends to guard everything, which hides real failures and costs every later reader time.', do:'Find one broad try-catch or null guard in generated code that would hide a real bug, and replace it with a fail-fast check.', min:20 },
        { kind:'topic', ref:'craft-save-systems', why:'A save file is untrusted input that outlives the build, so it is where a security and a compatibility review meet.', do:'Review a save loader for bounds, version handling and what happens on a corrupt file, and write one failing test.', min:35 },
        { kind:'checklist', ref:'ai-verify', why:'The checklist tests the claims around an AI change (sources, whether it solves the problem you stated, what would prove it wrong, who owns the decisions) in a fixed order, next to the code checks above.', do:'Run it on the AI-written change or its description that you reviewed, and note the first claim it flags that you could not check.', min:20 }
      ],
      review:['ai-evals'],
      check:{
        recall:[
          { q:'Why review tests and deletions before new code in an AI change?', a:'A model can make a check pass by editing it, loosening a threshold or deleting the failing case. The new code often looks fine while the safety net has moved.' },
          { q:'What does the evidence say about the security of AI-written code?', a:'In a controlled study, participants with an assistant wrote less secure code and were more confident. Scans of generated samples found a large share with flaws, and results come from older models, so treat the finding as a direction, not a rate.' },
          { q:'Which inputs to a game are untrusted?', a:'Saves, mods, network messages, user content and model output. Each needs bounds, versioning and a rule for corrupt input, with the server never trusting the client.' },
          { q:'Why check performance in a review?', a:'Plausible code can allocate every frame or scan a list per entity. Only a capture on the target device against the budget shows it.' }
        ],
        build:'Write a review of an AI-written change (yours or a public repository’s) with a security checklist covering untrusted input, save or mod loading and server trust, and a performance check on a device capture. State what you would block and what test would unblock it. Solo: review a public pull request.',
        solution:{ outline:'Review an AI-written change. Include a checklist covering untrusted input, save and mod loading, and server trust. Add a performance check against a device capture. State what you would block and which test would unblock it. List what you could not check. Keep comments about behaviour, not style.', selfcheck:['Does the review cover input from outside the process?', 'Is there a measured performance point?', 'Is each blocker paired with a test that clears it?', 'Are the limits of the review stated?'] },
        skip:['Do you read tests and thresholds before the new code in a diff?','Can you list your game’s untrusted inputs?','Do you capture on the target device before approving a hot-path change?','Do you fail fast instead of guarding everything?','Can you say what you would block and why?']
      } },
    { id:'s4', t:'Measure, budget and choose', level:'advanced',
      goal:'Decide from your own measurements where AI helps, and work out what an AI feature costs and how slow it can be.', hours:4.5,
      steps:[
        { kind:'topic', ref:'craft-measuring-ai-uplift', why:'A randomised trial (16 experienced developers, early-2025 tools) found tasks 19% slower while they believed they were 20% faster; METR’s 2026 update is inconclusive, its intervals cross zero, and other studies found gains, so only your own comparison answers for your team.', do:'Write a paired-task plan: task types, how tasks are assigned, the baseline, and metrics that include review time and stability.', min:60 },
        { kind:'topic', ref:'models-reasoning-and-scaling', why:'Vendor and benchmark claims move quickly, so a senior needs to know what a benchmark number can and cannot say.', do:'Take one benchmark claim from a tool you use and write what it does not show about your work: is the benchmark saturated, public long enough to be contaminated, or a mismatch with your task?', min:30 },
        { kind:'topic', ref:'models-prompt-caching', why:'Caching is often the largest cost lever on the input side, and it changes what a prompt should look like.', do:'Take one prompt with a large fixed prefix, write it in the order the topic gives with everything dynamic below the cache point, and work out the saving using the cache-read and cache-write multipliers from your vendor’s pricing page (note its date).', min:25 },
        { kind:'topic', ref:'craft-ai-cost-latency-budget', why:'A feature that works in a demo can lose money per player or miss a frame budget at p95, so the budget comes before the build.', do:'Work out cost per request, per player and per day for one AI feature, and the slowest response you will accept.', min:60 },
        { kind:'topic', ref:'craft-cpu-cache-and-data-layout', why:'A budget is only as good as the measurement behind it: the same capture-first method that prices a model call prices a frame, and data layout is usually the cheapest large fix it finds.', do:'Take the hottest loop in a game you know, write its bytes read per element and the cache lines it pulls in, and the change a capture would have to confirm.', min:30 },
        { kind:'topic', ref:'models-open-and-closed', why:'Routing and self-hosting trade cost against quality, licence terms and control, so the choice needs a measured eval, not a guess.', do:'Say which of your requests could go to a cheaper model and what eval would prove it.', min:25 },
        { kind:'checklist', ref:'ai-architecture-boundary', why:'The boundary checklist keeps the model from becoming a dependency the game cannot run without.', do:'Run it on one AI feature and write the fallback for when the model is slow or off.', min:20 },
        { kind:'topic', ref:'ai-budgets-and-debugging', why:'In-game AI (perception, pathfinding, decisions) has a per-frame cost that scales with agent count and has to fit the same budgets as everything else; the topic covers game AI, not model calls.', do:'Set a per-frame time cap and a worst-case agent count for one AI system in your game (pathfinding, perception or a model-driven NPC) and write the worst-case test at that count.', min:20 }
      ],
      review:['craft-verification-as-the-job'],
      check:{
        recall:[
          { q:'Why not rely on a published study to decide whether AI helps your team?', a:'The studies disagree: one randomised trial found a slowdown on mature code, others found gains, and each covers narrow tasks and older tools. Developers also misjudge their own speed, so only a local comparison answers.' },
          { q:'What should an uplift measurement count besides task time?', a:'Review time, defects and stability after release. An early jump in lines or throughput can fade once complexity and instability show up.' },
          { q:'What goes into a cost and latency budget for an AI feature?', a:'Cost per request, per player and per day, caching and batch effects, a cap per player, the p95 latency you will accept, a fallback, and a date to re-check because prices and models change.', ideas:['Cost per request, per player and per day, caching and batch effects', 'a cap per player, the p95 latency you will accept', 'a fallback', 'a date to re-check because prices and models change'] }
        ],
        build:'Write (a) a paired-task plan to measure AI uplift for your team, with a baseline and metrics that include review time and stability, and (b) a per-player cost and p95 latency budget for one AI-assisted feature, with caps and a re-check date. Solo: plan the comparison on your own tasks over a month.',
        solution:{ outline:'Write two things. First, a paired-task plan for AI uplift: the same tasks done with and without help, a baseline, and metrics including review time and defects after release. Second, a per-player cost and p95 latency budget for one AI-assisted feature, with caps and a date to re-check. Say how you avoid counting speed that only moves the work to review.', selfcheck:['Is there a baseline before the change?', 'Does a metric count review time?', 'Are cost and latency set per player with a cap?', 'Is there a re-check date?'] },
        skip:['Have you ever measured AI uplift on your own tasks against a baseline?','Do you count review time and stability, not only speed?','Can you state cost per player per day for an AI feature you run?','Do you have a fallback when the model is slow or off?','Do you re-check prices and limits on a date?']
      } },
    { id:'s5', t:'Grow the team', level:'advanced',
      goal:'Keep juniors learning while the team ships faster, so skills still form.', hours:3,
      steps:[
        { kind:'topic', ref:'lead-junior-skill-formation-with-ai', why:'In one experiment, learners who delegated the whole task to an assistant scored lower on a later quiz, and the groups were small, so treat it as a warning to design for, not a rate.', do:'Write which tasks a junior does with the assistant on, which with it off, and how you check they can explain the result.', min:55 },
        { kind:'topic', ref:'lead-onboarding', why:'Onboarding is where a new hire’s map of the system forms, and the topic builds it with a real first change and pairing, not a talk.', do:'Write a first-week path for a new engineer that includes a real first change, pairing on the first review, and reading one system unaided and explaining it back.', min:25 },
        { kind:'topic', ref:'lead-one-on-ones', why:'The 1:1 is the recurring place to ask, with feedback tied to a recent event both people remember.', do:'Write three 1:1 questions that reveal understanding rather than output.', min:30 },
        { kind:'topic', ref:'lead-conflict-growth', why:'Delegating well means giving work that stretches, and disagreements about AI use need a way to be settled.', do:'Write how you would decide a disagreement over whether a junior may use an agent for a task.', min:30 },
        { kind:'topic', ref:'craft-clean-code-ai-era', why:'Code that names one concept one way and states its contract can be read by a reviewer, an agent and a junior alike, and generated code often does not.', do:'Take a generated function and rewrite it for a maintainer using the topic’s rules: one distinctive name per concept, a contract comment, and a comment for the why.', min:25 },
        { kind:'reflect', why:'A plan for a junior is only credible if it names what you will observe.', do:'Write the milestone that would show a junior has skill, not output, and what you will do if it does not appear.', min:15 }
      ],
      review:['craft-security-review-of-generated-code'],
      check:{
        recall:[
          { q:'What did the skill-formation experiment suggest?', a:'Learners who delegated the whole task to the assistant scored lower on a later quiz than those who asked it for explanations. The groups were small, so it is a warning that the usage pattern matters, not a measured rate.' },
          { q:'How do you check a junior’s skill rather than their output?', a:'Ask for a cold explanation without the tool, assign some tasks with the assistant off, and review by asking why. Output alone can be produced without understanding.' },
          { q:'Why keep no-assistant practice at all?', a:'The risk seems to lie in the mode that skips understanding, and unaided work keeps a baseline and gives you something to check. The payback is plausible but unproven, since it rests on one small study, and you still need people who can debug and review what the agent writes.' }
        ],
        build:'Write a mentoring plan for one junior: explain-first assistant use, no-assistant reps, a review by cold explanation, and a milestone that shows skill, not output. Solo: write it for yourself learning a new area.',
        solution:{ outline:'Write a mentoring plan for one junior. Include explain-first use of the assistant, sessions without it, a review where they explain a change cold, and a milestone that shows skill rather than output. Say how you will notice skills that are not forming. For a solo reader, write it for yourself.', selfcheck:['Does the plan include work without the assistant?', 'Does the review test understanding, not output?', 'Is the milestone a skill someone could observe?', 'Is there a way to notice a gap early?'] },
        skip:['Do juniors on your team have tasks with the assistant off?','Do you review by asking them to explain?','Can you name the milestone that shows a junior can work unaided?','Do you know which tasks you would never delegate to the tool?']
      } },
    { id:'s6', t:'Incidents and technical direction', level:'advanced',
      goal:'Run the bad day when an AI-assisted change breaks a live build, and argue trade-offs with design and production.', hours:3,
      steps:[
        { kind:'topic', ref:'lead-incidents', why:'An incident needs roles, a rollback and a blameless review, and the review can ask whether an AI-assisted change contributed and whether the rollback had been rehearsed.', do:'Write the incident plan for a bad build: who decides, the rollback step, and the first message to players.', min:40 },
        { kind:'topic', ref:'pm-postmortems', why:'A postmortem turns one failure into a rule, and only if it finds a cause you can change.', do:'Write a postmortem for a past bug: timeline, cause, and one check that would have caught it.', min:30 },
        { kind:'topic', ref:'quality-and-build-health', why:'A regular playable build, blocker triage and regressions traced to a change are the early signals that a fast stream of changes is breaking the project.', do:'List three build-health signals you would watch weekly and the threshold that triggers a stop.', min:30 },
        { kind:'topic', ref:'lead-saying-no', why:'A senior is asked for expensive things, and a reasoned no with options is a part of the job. The designer path uses this topic from the other side, as the one making the request.', do:'Write your reply to a design request from your own codebase’s point of view: the engineering cost, the risk to the build, two cheaper options and what you would cut.', min:30 },
        { kind:'topic', ref:'pm-cross-discipline', why:'Cost has to be stated in units that design and production can compare. The designer path uses this topic from the other side, as the one receiving the estimate.', do:'Restate the engineering cost of that request in engineer-weeks, art-days and QA cases with a range, and what each discipline would drop to fit.', min:30 },
        { kind:'reflect', why:'A short note forces a technical direction to be stated, not implied.', do:'Write a one-page technical direction note for a design request that is expensive to build: cost, options, the cut, and the rollback plan if an AI-assisted change breaks a live build.', min:20 }
      ],
      review:['craft-measuring-ai-uplift'],
      check:{
        recall:[
          { q:'What should an incident plan settle before an incident?', a:'Who decides, the rollback step, who talks to players, and how the review will be blameless. Deciding those during the incident costs time you do not have.' },
          { q:'What makes a postmortem useful?', a:'A cause you can change and a check that would have caught it. A list of what went wrong without a rule changes nothing.' },
          { q:'How do you make a technical no fair to design?', a:'State the cost in units they can compare, offer options including a cut, and say what you would need to say yes.', ideas:['State the cost in units they can compare', 'offer options including a cut', 'say what you would need to say yes'] }
        ],
        build:'Write a one-page technical direction note for a design request that is expensive to build: the cost, the options, the cut, and the rollback plan if an AI-assisted change breaks a live build. Solo: use a feature you have wanted to add to your own project.',
        solution:{ outline:'Write a one-page technical direction note for an expensive design request. State the request, the cost in time and risk, two or three options, the cut you recommend and why. Add the rollback plan if an AI-assisted change breaks a live build: who decides, the step, and the first message to players. Point to the incident and no-saying pages.', selfcheck:['Does the note put the cost in numbers or ranges?', 'Is a cut recommended, not only options?', 'Does the rollback name an owner?', 'Is the player message written?'] },
        skip:['Do you have a written rollback for your live build?','Can you say who decides during an incident?','Do you turn postmortems into checks?','Do you state costs in units other disciplines can compare?']
      } }
  ]
});

PATH('studio-practice-ai-era', {
  t:'Run a game team in the AI era', tag:'Who owns what, what code is worth now, how models behave, and how to plan and ship when building is cheap.',
  pick:'Run a game team when AI writes much of the code',
  track:'leadership', level:'advanced', hours:13,
  audience:'Leads, producers and senior developers (or solo developers, since every team step has a solo variant) whose team now works with AI tools and who have to decide what the humans own, what standard the code is held to, and how the plan changes.',
  outcome:'You can split ownership between people and AI on purpose, hold agent-written work to a review standard, explain what a model does with its context and where it runs, and plan, cut, polish and submit a game on evidence.',
  prereq:[], next:['technical-lead','ship-it'],
  stages:[
    { id:'s1', t:'Who owns what', level:'advanced',
      goal:'Decide, before the work starts, which tasks belong to a person, which to the AI and which to both, and brief the AI so the split holds.', hours:2.25,
      steps:[
        { kind:'topic', ref:'bottleneck-shift', why:'Everything else in this path follows from one change: production got cheap, so judgment is now the scarce thing your team has to protect.', do:'Write where your team spent its time last week as a split between producing and judging or testing, and say whether the ratio has flipped yet. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'ai-roles', why:'Asking for a role instead of for ideas gives you a stance you can check the output against, and keeps the AI out of the decider seat.', do:'Pick one task your team gives an AI today and name the role it should have been cast in, and the role you should have kept away from it. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'responsibility-matrix', why:'Without an owner named in advance, whoever produces the artifact owns the decision by default, and that is usually the AI.', do:'List five recurring tasks on your team and mark each human, AI or shared, and note any where you cannot say who owns it. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'tool', ref:'delegate', why:'The Delegation Planner forces the ownership call for your own tasks instead of leaving it as a feeling.', do:'Run three of your five tasks through the planner and change the owner of any one where its answer differs from yours.', min:25 },
        { kind:'topic', ref:'prompting-framework', why:'Framing is the human’s most valuable contribution, and a brief that states context, evidence and the decision is how a delegated task stays yours.', do:'Rewrite one vague request you gave an AI recently so it states context, intent, constraints, evidence, role, task, output format and a critique step.', min:20 },
        { kind:'tool', ref:'prompt', why:'Filling in the generator shows which of the eight parts you usually leave blank.', do:'Build that same rewritten request in the generator and write down which part you had left out before.', min:20 },
        { kind:'reflect', why:'Naming the judgment you refuse to hand over is what turns the matrix from a table into a rule.', do:'Write the one decision on your team that no AI output should be able to settle, and how a reviewer would notice it had. Solo: use your own project and the people or AI tools you work with in place of a team.', min:15 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why does a task with no named owner usually end up with the AI?', a:'Whoever produces the artifact owns the decision by default, and the AI produces most of the artifacts. Naming the owner in advance is what makes AI should not decide this a rule instead of a feeling.' },
          { q:'What does casting the AI in a role give you?', a:'A stance, an output shape and something to check the output against. An unrolled request gets the average of all stances, and none of the nine roles is decider.' },
          { q:'What has moved from production to judgment as the bottleneck?', a:'Taste, framing, prioritisation, understanding players, recognising fun, separating signal from noise, trade-offs and knowing what not to build.' }
        ],
        build:'Write a one-page ownership table for your team’s five recurring tasks, with the role the AI plays in each and the brief it is given.',
        solution:{ outline:'Make a table of five recurring team tasks. For each, name the owner, the role AI plays and the brief it is given: the input, the output format and the check. Mark where a person must decide. Use the responsibility matrix pattern so no task has two owners or none. Keep each brief short enough that a new teammate could follow it.', selfcheck:['Does each task have exactly one human owner?', 'Does each AI role come with a written brief?', 'Is every brief checked by something?', 'Are the decisions that stay with people marked?'] },
        skip:['Can you say who owns each recurring task on your team, human or AI, without checking?','Do your requests to an AI name a role and a decision?','Can you name the last thing you decided that an AI could not have?','Do you know which parts of the prompting framework you usually leave out?']
      } },
    { id:'s2', t:'Working with AI, and how it fails', level:'advanced',
      goal:'Use AI where it saves the most time, spot its characteristic failures early, and keep player evidence between an AI output and a commitment.', hours:2.33,
      steps:[
        { kind:'topic', ref:'ai-failure-modes', why:'The failures are systematic, so a team that knows the symptoms catches them at the cadence of a playtest instead of at a milestone.', do:'Pick three failure modes from the list and write the symptom each would show in your current project.', min:20 },
        { kind:'topic', ref:'ai-for-implementation', why:'This is where the evidence for AI saving time is best (bounded, greenfield work), and it pays only if the prototype is instrumented, treated as disposable and the saving is measured.', do:'Write a brief for one prototype that states the question it answers, what it must log, what tuning values stay live and what it leaves out.', min:20 },
        { kind:'prompt', ref:'verify', why:'A fixed verification pass turns is this right into a list of assumptions, sources and kill criteria you can check.', do:'Run the verification prompt on the last AI output your team acted on, and mark which assumptions were invented. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'ai-for-playtest-analysis', why:'AI is fast and consistent at coding evidence and lacks the context that interpretation needs, so the split of labour matters.', do:'List what context you would add to an AI summary of your last playtest, and the pattern in it that rests on only two testers.', min:20 },
        { kind:'checklist', ref:'playtest-prep', why:'Analysis is only as good as the evidence given to it, and this checklist fixes the session before the players arrive.', do:'Run the playtest preparation checklist on your next session and write the hypothesis you will give the AI with the notes.', min:20 },
        { kind:'topic', ref:'ai-loop', why:'The loop puts player evidence between exploration and commitment, which is the discipline that prevents most AI-era failures.', do:'Mark which of the twelve steps your team is on, which step it skipped to get there, and when a player last touched the build. Solo: use your own project and the people or AI tools you work with in place of a team.', min:25 },
        { kind:'reflect', why:'The failure you can name in your own team is the one you can set a detector for.', do:'Write the failure mode most likely on your team now, and the cadence or check that would catch it. Solo: use your own project and the people or AI tools you work with in place of a team.', min:15 }
      ],
      review:['responsibility-matrix'],
      check:{
        recall:[
          { q:'Why are AI failure modes systematic rather than random?', a:'They follow from AI’s strengths (fluency, volume, plausibility) meeting human weaknesses (deference, impatience, fear of deciding), so each has a symptom, a cause, a detector and a correction.' },
          { q:'What makes AI-written prototype code worth having?', a:'Precise briefs on what to build, what to expose and what to log, instrumentation, and treating the prototype as disposable.', ideas:['Precise briefs on what to build, what to expose and what to log', 'instrumentation', 'treating the prototype as disposable'] },
          { q:'Where in the AI-era loop does player evidence sit?', a:'Between exploration and commitment: prototype, play, measure and interpret come before decide and implement, and polish is the setup for the next hypothesis.', ideas:['Between exploration and commitment', 'prototype, play, measure and interpret come before decide and implement', 'polish is the setup for the next hypothesis'] }
        ],
        build:'Take one AI-produced artifact from your project and run the verification prompt on it, then write the decision you made from the result.',
        solution:{ outline:'Take one AI-produced artifact from your project and run the verification prompt on it. Record what it flagged, what you checked yourself, and the decision: accept, change or reject. Name the failure mode you looked for, such as invented detail or flattering agreement. Write the decision and its reason in two sentences.', selfcheck:['Was the artifact checked against a source, not only by asking the model?', 'Is a failure mode named?', 'Is the decision one of accept, change or reject?', 'Is the reason written?'] },
        skip:['Can you name three AI failure modes and the symptom each would show on your team?','Do your prototype briefs say what the build must log?','Do you give an AI analysis the hypothesis and the context it lacks?','Do you know how many iterations your team has run without player contact?']
      } },
    { id:'s3', t:'Craft that survives cheap code', level:'advanced',
      goal:'Say which engineering values still hold when a model writes the code, and turn them into review rules for people and agents.', hours:2.25,
      steps:[
        { kind:'topic', ref:'craft-core-values-that-last', why:'A value that only held while code was slow is a habit, and testing each against cheap code shows what to keep.', do:'Write your team’s top five engineering values and mark each as still matters, matters more, or was only a habit. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'craft-what-matters-now', why:'Understanding, verification and simplicity are the scarce things once output is abundant.', do:'Take the last change your team merged and write whether anyone could explain it and what check would have shown it failing. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'craft-best-practice-now', why:'Reading and verifying are the bottleneck now, so small diffs, honest names and tests beside the code became the way review still works.', do:'Find your largest recent diff, and write how it could have been split into changes reviewable in one sitting.', min:20 },
        { kind:'checklist', ref:'ai-verify', why:'A checklist that must be ticked before acting makes the verification habit something a reviewer can ask for.', do:'Run this checklist on one AI-written change from your project and note which box you could not tick.', min:20 },
        { kind:'topic', ref:'craft-clean-code-ai-era', why:'The next reader is often an agent with a context budget and a grep, which sharpens some rules and exposes others as taste.', do:'Pick five names in your codebase and check whether each is distinctive enough to be found in one search.', min:20 },
        { kind:'topic', ref:'craft-ai-orchestrates-tools-compute', why:'Splitting the pipeline into what the model guesses and what code computes tells you where verification has to go.', do:'Draw one numeric question your team asks an AI as a pipeline and mark which steps are deterministic and which are sampled. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'reflect', why:'A rule you can state in one line is one you can put in a review comment or an agent instruction.', do:'Write one review rule for agent-written changes on your team in a single sentence, with the check that enforces it. Solo: use your own project and the people or AI tools you work with in place of a team.', min:15 }
      ],
      review:['ai-failure-modes'],
      check:{
        recall:[
          { q:'What changed about correctness when models write the code?', a:'Its value is unchanged and its method changed: correctness is now shown by checks, not by the author’s care.' },
          { q:'Why do small diffs matter more than before?', a:'Typing got cheap so a large diff costs nothing to produce, but reviewing it costs as much as ever, and a reviewer’s attention runs out before the diff does.', ideas:['Typing got cheap so a large diff costs nothing to produce', 'reviewing it costs as much as ever', 'a reviewer’s attention runs out before the diff does'] },
          { q:'Which parts of a pipeline that uses a model are deterministic?', a:'Only the computation and the rendering. Interpretation, tool choice and arguments are sampled guesses that can be checked but not assumed.' },
          { q:'Why do distinctive names help an agent?', a:'An agent navigates by searching names, so a distinctive consistent name is found in one search and a generic or inconsistent one is missed.', ideas:['An agent navigates by searching names', 'a distinctive consistent name is found in one search and a generic or inconsistent one is missed'] }
        ],
        build:'Write the short list of review rules your team holds agent-written changes to, each with the check that enforces it.',
        solution:{ outline:'Write the short list of review rules for agent-written changes. Beside each rule, name the check that enforces it, such as a test, a lint rule or a required sign-off. Cut any rule with no check. Add one rule about what stays out of scope for agents, and say who may change the list.', selfcheck:['Does every rule have an enforcing check?', 'Are rules short enough to remember?', 'Is there a boundary on what agents may change?', 'Did you remove rules nobody can check?'] },
        skip:['Can you explain every line of the last change you merged?','Are your typical diffs small enough to review in one sitting?','Do your key names survive a single search?','Do you know which steps of your AI pipelines are deterministic?','Have you put your review rules in a formatter, a test or an agent instruction rather than a conversation?']
      } },
    { id:'s4', t:'What the model is doing', level:'advanced',
      goal:'Explain what a model does with its context, how it was made and where it runs, so tool and architecture choices rest on more than a leaderboard.', hours:2.25,
      steps:[
        { kind:'topic', ref:'models-attention-long-context', why:'A large window is a capacity, not a promise, and an agent deep in a session is working in the degraded zone.', do:'Write where the most important instruction sits in your longest agent session and how far it is from where the answer is generated.', min:25 },
        { kind:'topic', ref:'models-how-models-are-made', why:'Most surprising behaviour traces to a training stage, which tells you whether a better prompt or a fine-tune is the fix.', do:'Match three odd model behaviours your team has seen to the stage that most likely produced each. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'models-architecture-choices', why:'Active versus total parameters decides what fits your hardware, and vendor size claims mix the two.', do:'Take one model you use or considered and write its total and active parameters, and whether your target machine holds it.', min:20 },
        { kind:'checklist', ref:'ai-architecture-boundary', why:'If a model call ships inside a game, this checklist says where the probabilistic part ends and what code validates its output.', do:'Run the checklist on one AI feature you have or plan and write the first group it fails.', min:25 },
        { kind:'topic', ref:'models-open-and-closed', why:'Closed, open-weight and on-device models trade capability against control, cost and offline play, and licences carry clauses that can block shipping.', do:'For one AI feature, write which of closed, open-weight or on-device it needs and the licence clause you would check first.', min:20 },
        { kind:'topic', ref:'models-reasoning-and-scaling', why:'Capability keeps moving, so plans need a review date and your own tasks are the test that counts.', do:'Write three tasks from your own project that you would use to test a new model, and a date to re-run them.', min:20 },
        { kind:'reflect', why:'Picking the assumption you would revisit first is what keeps a plan from freezing today’s capability.', do:'Write the workaround on your team that a stronger model might make dead weight, and the date you will check. Solo: use your own project and the people or AI tools you work with in place of a team.', min:15 }
      ],
      review:['craft-ai-orchestrates-tools-compute'],
      check:{
        recall:[
          { q:'Why can stuffing a whole document into a prompt make answers worse?', a:'Models use the start and end of their context better than the middle and degrade as input grows, and near-duplicate content acts as a distractor. Retrieving the relevant passages can be more faithful.' },
          { q:'What is the difference between total and active parameters?', a:'Memory scales with total parameters because every expert must be loaded, while compute per token scales with active parameters in a mixture-of-experts model.', ideas:['Memory scales with total parameters because every expert must be loaded', 'compute per token scales with active parameters in a mixture-of-experts model'] },
          { q:'What does open weights not guarantee?', a:'Many open-weight licences are custom and may cap company size, require attribution or bind you to an acceptable use policy, and open weights alone fall short of an open-source definition.', ideas:['Many open-weight licences are custom and may cap company size, require attribution or bind you to an acceptable use policy', 'open weights alone fall short of an open-source definition'] }
        ],
        build:'Write a one-page model choice note for one AI feature covering context use, size and hardware fit, hosting type and licence, and the tasks you will re-test.',
        solution:{ outline:'Write a one-page model choice note for one AI feature. Cover how much context it needs, the size and hardware fit, hosted or local with its licence, and the tasks you will re-test when the model changes. Give a fallback if the model is unavailable. Use the architecture and reasoning pages for the terms.', selfcheck:['Is the context need estimated with a number?', 'Are licence and hosting stated?', 'Is there a list of tasks to re-test?', 'Is there a fallback?'] },
        skip:['Do you know where your key instruction sits in a long session?','Can you say whether a behaviour comes from pre-training, feedback training or quantisation?','Do you know total versus active parameters for the models you rely on?','Have you read the licence of any open-weight model you plan to ship?']
      } },
    { id:'s5', t:'Plan on evidence', level:'advanced',
      goal:'Choose the engine, the documents and the working rhythm on purpose, and keep scope tied to what players have validated.', hours:2.25,
      steps:[
        { kind:'topic', ref:'design-documents', why:'A document exists to make a decision stick, and the right size prevents both theater and undocumented decisions.', do:'List your team’s current documents and write, for each, the reader and the decision it helps them make. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'platforms-choosing-an-engine', why:'The engine is close to irreversible, and it is decided by platforms, people and licence terms before features.', do:'Answer the seven questions in the topic for your project and write which one would change your engine if the answer moved.', min:20 },
        { kind:'topic', ref:'pm-agile-gamedev', why:'Sprints suit committed work and flow suits arriving work, and most game teams are both at once.', do:'Sort your team’s current work into planned and arriving, and write how much capacity is reserved for iteration on feel. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'pm-cross-discipline', why:'Most delay is in the gap between two people who each believe the other is next, so each seam needs an artifact.', do:'Pick one handoff on your team and write what ready means on each side and what artifact carries the intent. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'topic', ref:'scope-control', why:'Cheap implementation removes the natural brake on scope, so the brake has to be deliberate.', do:'Write your game’s not-this-game list and the validated evidence behind each item still in scope.', min:25 },
        { kind:'checklist', ref:'scope-sanity', why:'A monthly review is what makes the brake a habit rather than a reaction to trouble.', do:'Run the scope sanity checklist on this month and mark the first box your team fails. Solo: use your own project and the people or AI tools you work with in place of a team.', min:20 },
        { kind:'reflect', why:'The feature you would cut first shows how much of your scope rests on imagination.', do:'Write the one feature built because it was cheap to build, and what cutting it would cost the player.', min:15 }
      ],
      review:['bottleneck-shift','models-reasoning-and-scaling'],
      check:{
        recall:[
          { q:'What should a design document be judged on?', a:'The shared decisions it forces and the memory it keeps, not the page count. Match it to the reader and the decision, or write nothing.' },
          { q:'Why does AI make scope control harder?', a:'Implementation is cheap enough that a lot of mediocre content can be produced before anyone asks whether the core is fun, so scope must follow validated value, not what could be built.', ideas:['Implementation is cheap enough that a lot of mediocre content can be produced before anyone asks whether the core is fun', 'scope must follow validated value, not what could be built'] },
          { q:'What does a handoff need that a collaboration does not?', a:'A handoff needs an artifact that carries intent and a shared definition of ready on both sides. A collaboration needs a room.' }
        ],
        build:'Write a one-page plan with your engine choice and its reasons, the working rhythm, the not-this-game list and the artifact for your riskiest handoff.',
        solution:{ outline:'Write a one-page plan: the engine choice and the reasons, the working rhythm, a not-this-game list, and the artifact for your riskiest handoff (a spec, a capture or a prototype). Tie the rhythm to the agile and cross-discipline pages. Keep the not-this-game list to things you really tempted yourself with.', selfcheck:['Are the engine reasons tied to your game, not general praise?', 'Does the rhythm name its review points?', 'Is the not-this-game list specific?', 'Does the handoff artifact exist?'] },
        skip:['Can you say what decision each of your documents helps make?','Did you choose your engine from platforms, people and licence terms?','Can you say how much capacity your plan reserves for iteration on feel?','Is there a written not-this-game list?']
      } },
    { id:'s6', t:'Iterate, polish and submit', level:'advanced',
      goal:'Change one thing at a time on evidence, polish only what has been validated, and run the store checklist against the actual build.', hours:1.83,
      steps:[
        { kind:'topic', ref:'iteration-and-evidence', why:'AI makes iterations cheap, which only helps if each is informed by evidence, and fast wandering is still wandering.', do:'Count the iterations since a player last touched your build, and write the one change most likely to move the signal.', min:20 },
        { kind:'tool', ref:'hypothesis', why:'Writing the kill criterion in advance is what lets the next test say no.', do:'Build one hypothesis for your next playtest with what you will see and the result that would make you drop the change.', min:25 },
        { kind:'topic', ref:'polish-when', why:'Polish amplifies a validated loop and hides a weak one, so the timing is a production decision.', do:'Sort your open polish items into legibility for tests and emphasis for shipping, and write which the loop justifies today.', min:20 },
        { kind:'checklist', ref:'submit-pc', why:'Every item is checkable against the actual build and page, which is what catches the promise the build does not keep.', do:'Run the PC store checklist against your latest build and page and write the first item that fails.', min:25 },
        { kind:'reflect', why:'A shipping decision made in writing is one the team can review afterwards.', do:'Write the one thing that would make you delay submission, and who has the authority to call it.', min:20 }
      ],
      review:['scope-control','craft-what-matters-now'],
      check:{
        recall:[
          { q:'Why change one important thing per iteration?', a:'Changing many things at once makes the result unattributable, so you learn nothing even when it improves.' },
          { q:'What separates legibility from polish?', a:'Feel basics such as latency and clear feedback are legibility that testers need. Polish is emphasis, and belongs after the loop is voluntarily replayed.' },
          { q:'What is the point of the PC store checklist?', a:'Every item is checked against the actual build and store page, not against the plan for them.' }
        ],
        build:'Run the PC submission checklist on your build and write the fix list, ordered by which item would block submission first.',
        solution:{ outline:'Run the PC submission checklist on your build and list every failing item. Order the fix list by which item would block submission first, and give an owner and size for each. Say what evidence you have for items that pass. Re-run after the first fix to show the list changes.', selfcheck:['Is the list ordered by what blocks first?', 'Does each item have an owner and a size?', 'Is passing backed by evidence?', 'Was the checklist re-run after a fix?'] },
        skip:['Do you know how many iterations you have run without player contact?','Does every playtest you plan have a written kill criterion?','Can you tell legibility from emphasis in your polish backlog?','Have you run the store checklist against the real build rather than the plan?']
      } }
  ]
});

PATH('ship-it', {
  t:'Ship a game on PC, console and mobile', tag:'From choosing platforms to a release that survives its first patch.',
  pick:'Ship a game on PC, console and mobile',
  track:'production', level:'intermediate', hours:10,
  audience:'Producers, leads and developers taking a finished or nearly finished game to one or more stores for the first time. UGC, VR and web portals appear as optional routes next to the PC, console and mobile stores.',
  outcome:'You can choose platforms on purpose, start access early, pass certification on a planned calendar, file ratings and disclosures correctly, and release and patch without breaking saves.',
  prereq:[], next:['build-and-release-engineer','technical-lead'],
  stages:[
    { id:'s1', t:'Pick your platforms', level:'intermediate',
      goal:'Choose where the game ships, and know what each choice commits you to before a line of platform code.', hours:2.5,
      steps:[
        { kind:'topic', ref:'platform-choice', why:'The platform decides the engine, the input, the calendar and the audience before any feature does.', do:'Score two or three candidate platforms on reach, cost, gatekeeping and effort, and write which one your validated audience is on.', min:30 },
        { kind:'topic', ref:'platform-and-session', why:'Session length and input follow from the platform, and the loop has to fit them.', do:'Write how one session of your game changes between a PC and a phone: its length, its input, and where the player stops.', min:20 },
        { kind:'platform', ref:'steam', why:'Steam is the most open of the major stores (a fee and two reviews, no pitch), so it is the baseline every other gate is measured against.', do:'Read the Steam guide and list what you need on day one: the fee, the store page, both reviews and the Coming Soon runway.', min:25 },
        { kind:'topic', ref:'ugc-platforms', why:'Roblox and Fortnite are a platform choice that also picks the engine, the language and the economy.', do:'Decide in one paragraph whether your game belongs on a UGC platform instead of a store, and why.', min:20 },
        { kind:'platform', ref:'roblox', why:'Roblox is the clearest UGC platform to compare with a store: you publish from Studio and pass an age check and a content questionnaire, not a certification.', do:'Read the guide’s publish stage and its deploy walkthrough, then write the steps from Studio to a Public audience and where they differ from a store release.', min:20 },
        { kind:'game', ref:'fortnite', lens:'business', why:'Fortnite is the platform-choice question made concrete: the same game a player queues into is also the runtime a UEFN creator’s island runs inside, so building on it means renting Epic’s engine, audience and economy rather than shipping your own.', do:'Read its business lens, then note which of Fortnite’s own launches (Save the World, Battle Royale, Creative, UEFN) was a platform decision rather than a content update, and write one line on what each traded away for reach.', min:15 },
        { kind:'platform', ref:'fortnite', why:'Publishing to Fortnite shows the UGC route from the store side: a private version first, then a reviewed release, and the portal metric that says whether it worked.', do:'Read the publish stage and its deploy walkthrough, then write the steps from a private version to a release and the portal metric that would tell you the release worked.', min:20 }
      ],
      review:[],
      check:{
        recall:[
          { q:'What does a platform decide before any feature does?', a:'The engine and its export path, the input scheme and session length, the access and certification calendar, and which audience can find the game. It is a design constraint set first, not a marketing choice made at the end.' },
          { q:'Why is “we will port it later” never free?', a:'Porting touches input, save data, UI scale and sometimes the engine’s export path, and it competes with the current milestone for the same people. It needs an estimate and a place in the plan like any other feature.' },
          { q:'When is a UGC platform a better home than a store?', a:'When the game fits what that platform rewards (multiplayer, short sessions, engagement-ranked discovery), and the team accepts building inside its runtime and earning inside its economy in exchange for its audience, servers and payments.', ideas:['When the game fits what that platform rewards (multiplayer, short sessions, engagement-ranked discovery)', 'the team accepts building inside its runtime and earning inside its economy in exchange for its audience, servers and payments'] },
          { q:'How does a Roblox game go public?', a:'Publish the place from Studio, verify your age, answer the content questionnaire in Creator Dashboard, then move the audience from Private to Limited to Public.', ideas:['Publish the place from Studio', 'verify your age', 'answer the content questionnaire in Creator Dashboard', 'move the audience from Private to Limited to Public'] }
        ],
        build:'Write a one-page platform decision: the platforms you will ship on, in order, what each commits you to (access, calendar, input), and the one you decided against and why.',
        solution:{ outline:'Write a one-page platform decision. List platforms in shipping order and what each commits you to: access steps, a calendar and input support. Name the platform you decided against and the reason. Check the choice against your team size and the live-service plan. Mark which commitment is hardest to undo.', selfcheck:['Are platforms in an order with reasons?', 'Does each name its commitments?', 'Is the rejected platform justified?', 'Is the hardest-to-undo commitment marked?'] },
        skip:['Can you name what each of your target platforms commits you to before you write platform code?','Have you already decided the order you will ship platforms in, with a reason?','Can you explain why a port has to be estimated like a feature?','Could you take a Roblox place from Studio to a Public audience?']
      } },
    { id:'s2', t:'Get access and meet the requirements', level:'intermediate',
      goal:'Start the slow paperwork early, and build the behaviour every platform checks.', hours:2.25,
      steps:[
        { kind:'topic', ref:'platform-access', why:'Entity checks, NDAs and dev-kit approval can take longer than any technical work.', do:'For each target platform, list the entity, identity and NDA steps with an owner and a lead time.', min:25 },
        { kind:'platform', ref:'nintendo', why:'A console shows what an NDA-bound process looks like from outside: a queue first, then an SDK.', do:'Read the Nintendo guide and mark which of its stages you can plan now and which open only after the NDA.', min:15 },
        { kind:'platform', ref:'google-play', why:'Mobile stores add their own gates, such as testing rules for new accounts and target API deadlines.', do:'Read the Google Play guide and note every requirement that comes with a date.', min:15 },
        { kind:'platform', ref:'quest', why:'Meta Quest shows access and requirements in one flow: a verified organisation, release channels for testers and the VR checks before review.', do:'Walk the release stage’s deploy walkthrough, then write the ovr-platform-util upload command for the ALPHA channel and list the Virtual Reality Checks you would run once it is moved to RC.', min:20 },
        { kind:'topic', ref:'platform-requirements', why:'Suspend, resume, controller loss and a save that survives them are the entry fee on every platform.', do:'Test your build: suspend it mid-save, pull the controller mid-action, and write down what broke.', min:30 },
        { kind:'topic', ref:'infra-ci-pipelines', why:'One pipeline that builds every platform’s player is what keeps the requirements checked on every build.', do:'Ask your build owner for the one command that builds each platform target, or write down that there is none, and mark where the platform checks run.', min:25 }
      ],
      review:['platform-choice'],
      check:{
        recall:[
          { q:'Why start platform access before the build is ready?', a:'Entity, identity and NDA steps (a registered company, a D-U-N-S number, a signed NDA, a dev-kit request) can take longer than the technical work, and a console SDK does not exist for you until they are done.', ideas:['Entity, identity and NDA steps (a registered company, a D-U-N-S number, a signed NDA, a dev-kit request) can take longer than the technical work', 'a console SDK does not exist for you until they are done'] },
          { q:'Which lifecycle events does every platform expect a build to survive?', a:'Suspend and resume without losing progress, a controller disconnecting mid-session, and a save that is never left half written. A phone can suspend the game with no warning, so the save must happen on the pause notification.' },
          { q:'What should a CI pipeline for several platforms guarantee?', a:'That every platform’s player is built from one parameterised entry point by the same steps every time, so a requirement checked once stays checked on the next build.' },
          { q:'What must happen before a Quest build can be submitted?', a:'The organisation is verified, the build is uploaded to a release channel with ovr-platform-util, tested against the Virtual Reality Checks in RC, and submitted at least two weeks before launch.', ideas:['The organisation is verified', 'the build is uploaded to a release channel with ovr-platform-util', 'tested against the Virtual Reality Checks in RC', 'submitted at least two weeks before launch'] }
        ],
        build:'Write the access checklist for your platforms (an owner and a lead time per step) and a short test log of suspend, resume and controller loss on your current build.',
        solution:{ outline:'Write the access checklist for each platform: every step with an owner and a lead time in days. Add a test log from your current build: suspend mid-save, resume, and pull the controller mid-action. Record what broke each time. Mark which access step has the longest lead time.', selfcheck:['Does each step have an owner and a lead time?', 'Was suspend tested mid-save?', 'Was controller loss tested?', 'Is the longest lead time visible?'] },
        skip:['Have you already started the entity and NDA steps for every console you target?','Does your build already survive suspend, resume and controller loss without losing data?','Is every platform’s player built by one pipeline from one entry point?','Could you upload a Quest build to a release channel and name the checks it faces?']
      } },
    { id:'s3', t:'Pass the gates', level:'intermediate',
      goal:'Plan certification and store review as fixed dates, and file ratings and disclosures correctly the first time.', hours:2.5,
      steps:[
        { kind:'topic', ref:'certification-and-review', why:'Every platform has a gate and a clock, and a rejection costs the turnaround twice.', do:'Build a submission calendar backwards from your launch date, with each platform’s review window and one resubmission of buffer.', min:30 },
        { kind:'topic', ref:'ratings-and-disclosures', why:'A missing or wrong rating or privacy answer blocks a release as hard as a crash does.', do:'List every storefront you ship on and whether it uses IARC, its own questionnaire or a direct board rating, and every SDK whose data collection you must declare.', min:25 },
        { kind:'platform', ref:'apple', why:'Apple runs its own age rating and privacy labels, so it shows the disclosure work at its most detailed.', do:'Read the Apple guide’s review and ratings stages and list what your privacy label must declare.', min:20 },
        { kind:'platform', ref:'playstation', why:'PlayStation’s gate is partnership and the TRC: registration, agreements and dev kits come before any build, and the requirements are under NDA.', do:'Walk the release stage’s deploy walkthrough, then write the order of steps from registration to submission and which ratings you need for your markets.', min:20 },
        { kind:'topic', ref:'pm-qa-release', why:'Review windows are calendar commitments that the release plan has to hold.', do:'Put your submission dates into the release plan as fixed milestones, each with an owner.', min:25 },
        { kind:'checklist', ref:'submit-console', why:'A pre-submission pass catches the common rejections before the reviewer does.', do:'Run the submission checklist for your platform family (console here; PC and mobile are on the checklists page) and fix the first three failures.', min:20 },
        { kind:'game', ref:'dragon-quest', lens:'business', why:'Dragon Quest shows a release decision outweighing the game itself: the same core drew opposite verdicts in Japan and the West depending on when each market got it and in what edition, from Dragon Warrior’s late 1989 release to XI’s Definitive Edition.', do:'Read its reception and business lenses, then write for your own game which markets get which edition on which date, and what each market will compare it against on that day.', min:15 }
      ],
      review:['platform-access'],
      check:{
        recall:[
          { q:'Why is a review window a fixed date rather than an estimate?', a:'A rejection usually means a new queue, so a miss costs the turnaround twice. Put each platform’s published review time, or a conservative estimate where it is confidential, on the calendar with buffer for at least one resubmission.' },
          { q:'Which storefronts need something other than the shared IARC questionnaire?', a:'Steam and Apple run their own questionnaires, and a console release in Japan or any boxed release needs a rating from the local board directly, because that board is not part of the shared system.', ideas:['Steam and Apple run their own questionnaires', 'a console release in Japan or any boxed release needs a rating from the local board directly, because that board is not part of the shared system'] },
          { q:'What must a privacy form cover besides your own code?', a:'What every third-party SDK in the build collects on your behalf, such as ads, analytics and crash reporting, because the form is a statement about the whole game.' },
          { q:'What comes before a PlayStation build can be submitted?', a:'Registering with PlayStation Partners, signing the GDPA, getting dev and test kits, building to the TRC and rating the game through IARC, CERO or boards.', ideas:['Registering with PlayStation Partners', 'signing the GDPA', 'getting dev and test kits', 'building to the TRC and rating the game through IARC, CERO or boards'] }
        ],
        build:'Produce your submission calendar (dates, review windows, buffer) and the filled rating and privacy answers for one storefront, with every SDK checked.',
        solution:{ outline:'Produce the submission calendar with dates, review windows and a buffer. For one storefront, fill the rating and privacy answers, and check every SDK in the build against them. Note any SDK that changes your answers. Say how you handle a rejection within the calendar.', selfcheck:['Are review windows in the calendar?', 'Is there a buffer, and how large?', 'Was every SDK checked against the answers?', 'Is there a plan for rejection?'] },
        skip:['Is every review window in your plan a fixed date with resubmission buffer?','Do you know which of your storefronts use IARC and which do not?','Have you checked every SDK in your build for the data it collects?','Can you list PlayStation’s steps from registration to submission?']
      } },
    { id:'s4', t:'Launch and keep it running', level:'advanced',
      goal:'Put the store page up early, release on purpose, and patch without breaking a save.', hours:2.75,
      steps:[
        { kind:'topic', ref:'store-presence', why:'The store page sells the game before the game does, and a Coming Soon page needs runway.', do:'Draft your store page asset list to one store’s exact specs, and pick the date the page goes up.', min:25 },
        { kind:'topic', ref:'launch-and-discoverability', why:'A launch is found through the store’s own surfaces first, so plan for them.', do:'Write the three store surfaces you will aim for at launch and what each needs from you.', min:15 },
        { kind:'topic', ref:'soft-launch-and-playable-ads', why:'On mobile, a soft launch in a few markets decides whether a game gets a global launch at all, and a playable ad is often a player’s first contact with it.', do:'Write the retention and cost-per-install thresholds that would make you stop before a wider launch, and one playable-ad moment built only from gameplay a player will reach.', min:20 },
        { kind:'topic', ref:'release-and-updates', why:'Release is a button on some stores and a staged rollout on others, and the save has to survive every patch.', do:'Write the release runbook for each platform: who presses what, the rollout, and the day-one patch path, including a save-version check.', min:30 },
        { kind:'platform', ref:'xbox', why:'Xbox publishes its update certification times, which makes a realistic patch calendar possible.', do:'Read the Xbox guide’s release stage and plan your first patch against its update turnaround.', min:15 },
        { kind:'platform', ref:'web', why:'CrazyGames launches a game in two stages judged by live metrics, so a web release is decided by playtime, conversion to gameplay and retention from its first week.', do:'Walk the release stage’s deploy walkthrough, then write which metrics decide a move from CrazyGames’ Basic Launch to Full Launch, and what the SDK integration adds.', min:20 },
        { kind:'checklist', ref:'submit-mobile', why:'The last pass before release catches what the store will otherwise catch for you.', do:'Run the pre-submission checklist for your platform family on the release candidate.', min:20 },
        { kind:'topic', ref:'live-operations', why:'After launch the game is a service, and every update passes another gate.', do:'Plan the first month of updates with each platform’s review time built in.', min:15 }
      ],
      review:['certification-and-review','ratings-and-disclosures'],
      check:{
        recall:[
          { q:'Why open a Coming Soon or pre-registration page early?', a:'It turns attention gathered before launch into wishlists or pre-registrations the store can notify at launch, and some stores require the page to be public for a minimum time before release.', ideas:['It turns attention gathered before launch into wishlists or pre-registrations the store can notify at launch', 'some stores require the page to be public for a minimum time before release'] },
          { q:'What must a patch never break, and how do you protect it?', a:'The player’s save. Store a save-format version with the save, check it on load and migrate old saves, because an update arrives on a version the player did not choose.' },
          { q:'How does release differ between Steam and the mobile stores?', a:'On Steam an approved game waits until you press Release. Apple and Google let you hold an approved first version and release it by hand. Phased (Apple) and staged (Google) rollouts, which can be paused, apply only to later updates.' },
          { q:'How does a CrazyGames launch progress?', a:'A Basic Launch to a limited audience, with the SDK optional and no monetisation, for 7 to 21 days; Full Launch depends on playtime, conversion to gameplay and retention against benchmarks, and needs the SDK.', ideas:['A Basic Launch to a limited audience, with the SDK optional and no monetisation, for 7 to 21 days', 'Full Launch depends on playtime, conversion to gameplay and retention against benchmarks, and needs the SDK'] }
        ],
        build:'Write the release runbook for each platform (mechanism, owner, rollout, day-one patch path) and the save-version check your first patch relies on.',
        solution:{ outline:'Write the release runbook per platform: the release mechanism, an owner, the rollout steps and the path for a day-one patch. Add the save-version check your first patch depends on: the new build must read old saves. State how you stop a rollout.', selfcheck:['Does each platform have an owner and a mechanism?', 'Is a day-one patch path written?', 'Do old saves load in the patched build?', 'Is there a way to halt a rollout?'] },
        skip:['Is your store page planned with enough runway before launch?','Do you have a release runbook per platform with a named owner?','Does every save carry a version your code checks and migrates?','Do you know which metrics move a web game from Basic to Full Launch?']
      } }
  ]
});

PATH('ai-engineering-for-game-devs', {
  t:'AI engineering for game developers', tag:'How models work, how to work with agents, and how to ship AI inside a game.',
  pick:'Build and ship with AI, and ship AI in a game',
  track:'engineering', level:'intermediate', hours:13.25,
  audience:'Game programmers and technical designers who already ship code and now work with AI coding agents, or want a model inside a shipped game.',
  outcome:'You can explain what a model does with your context, set an agent up with rules and checks it cannot talk its way past, verify its output, draw the boundary where AI sits in a game’s architecture, and get an AI-assisted build through each store’s review.',
  prereq:[], next:['technical-lead','ship-it','studio-practice-ai-era'],
  stages:[
    { id:'s1', t:'How models work', level:'intermediate',
      goal:'Know what a model does with tokens, why it varies between runs, and why fluent output is not correct output.', hours:2.5,
      steps:[
        { kind:'topic', ref:'models-tokens-context', tab:'interview', why:'Every cost, limit and failure of a model starts with tokens and the context window.', do:'Answer the junior and mid questions aloud, then estimate the tokens in one source file and one design doc from your project.', min:30 },
        { kind:'topic', ref:'models-sampling', why:'Temperature and sampling explain why the same prompt gives different answers, and when that matters.', do:'Run one prompt five times and write which differences would be acceptable in a tool and which in a shipped game.', min:25 },
        { kind:'tool', ref:'prompt', why:'Writing a prompt in named parts shows what the model is actually given.', do:'Build one prompt for a real task in your project with the generator, and mark which part carries the most information.', min:20 },
        { kind:'topic', ref:'models-hallucination-sycophancy', tab:'interview', why:'A model that agrees with you and invents an API sounds the same as one that is right.', do:'Answer the interview questions, then ask a model about an engine API you know well and list every claim you would need to check.', min:25 },
        { kind:'topic', ref:'models-prompt-caching', why:'Caching changes what a long agent session costs, and it rewards a stable prompt prefix.', do:'Write which parts of your usual agent context never change between calls and could sit in a cached prefix.', min:25 },
        { kind:'topic', ref:'verifying-ai-output', why:'The rest of the path assumes you check output rather than trust it.', do:'Pick one recent AI answer you used and write how you would have verified it in under five minutes.', min:25 }
      ],
      review:[],
      check:{
        recall:[
          { q:'Why does the same prompt give different answers?', a:'The model outputs a probability distribution over the next token and sampling picks from it. Temperature and top-k or top-p change how often low-probability tokens get picked, and one early difference changes everything after it. Even at temperature 0 a hosted endpoint is not fully deterministic, because server load changes the batch and the arithmetic, which can flip a near-tie; store outputs you must keep.' },
          { q:'Why is fluent output not evidence of correct output?', a:'The model is trained to produce plausible text, evaluations have rewarded guessing over saying it does not know, and preference training rewards answers people like, including agreeable ones. An invented API or a wrong claim reads the same as a right one, so correctness has to come from a check outside the model.' },
          { q:'What does prompt caching reward?', a:'A long, stable prefix (instructions, rules, reference files) that stays byte-identical across calls, with the changing part at the end.', ideas:['A long, stable prefix (instructions, rules, reference files) that stays byte-identical across calls', 'with the changing part at the end'] }
        ],
        build:'Write a one-page note for your team: what a token is, what the context window holds in your agent sessions, and three claims a model made about your project that you checked.',
        solution:{ outline:'Write a one-page note for your team. Explain what a token is, what the context window holds in your agent sessions (rules, files, history, tool output), and why long sessions drift. List three claims a model made about your project and how you checked each. Say what you changed in your habits.', selfcheck:['Does it explain tokens in plain words?', 'Does it list what fills the window?', 'Were all three claims checked against the code or docs?', 'Does it end on a habit?'] },
        skip:['Can you explain temperature and why runs differ?','Can you estimate the token size of a file or doc?','Do you already check every API a model names against the docs?']
      } },
    { id:'s2', t:'Context and agents', level:'intermediate',
      goal:'Give an agent the context it needs and the limits it cannot ignore.', hours:2.5,
      steps:[
        { kind:'topic', ref:'models-context-engineering', why:'What goes into the context, and in what order, decides an agent’s output more than the wording of the request.', do:'List what your agent loads at the start of a session (in Claude Code, /context shows it) and cut one thing it never uses.', min:30 },
        { kind:'topic', ref:'models-agent-harnesses', tab:'interview', why:'An agent is a loop of model calls and tools, and the harness decides what it can see and do.', do:'Answer the interview questions, then draw the loop your agent runs for one task: calls, tools, stop condition. Then redraw it as a graph of fixed nodes and one model-driven loop, as the LangGraph course cited in the topic’s facts does, and say which part should stay a loop.', min:25 },
        { kind:'checklist', ref:'agent-rules-file', why:'The rules file is the context an agent loads every time, so it is where short and checkable pays most.', do:'Run the checklist on your CLAUDE.md or AGENTS.md, and move one rule into a hook or test.', min:20 },
        { kind:'topic', ref:'craft-teaching-agents', why:'An agent repeats a mistake until a check stops it, not until a sentence asks it to.', do:'Take one mistake an agent made twice and write the check that would have failed on it.', min:25 },
        { kind:'topic', ref:'models-tools-mcp-rag', why:'Tools and retrieval are how an agent reaches your engine, docs and data, and each one is a new input channel.', do:'List the tools and servers your agent can call, and mark which ones can write.', min:25 },
        { kind:'topic', ref:'models-security-and-operations', why:'Any text an agent reads can try to instruct it, and a tool that writes makes that dangerous.', do:'Name one place untrusted text reaches your agent and the permission that limits what it can then do.', min:25 }
      ],
      review:['models-tokens-context','models-hallucination-sycophancy'],
      check:{
        recall:[
          { q:'What belongs in an agent rules file, and what does not?', a:'The commands CI runs, where things live, conventions that cannot be inferred from code, and what to ask before doing. Anything a machine can check belongs in a linter, hook or test instead, and anything that must never happen belongs in a permission or hook.' },
          { q:'Why is a tool that writes a security question?', a:'Text the agent reads (a web page, an issue, a file) can contain instructions. If the agent can also write or run things, injected text can act through it, so write access needs limits the model cannot override.' },
          { q:'What is an agent harness responsible for?', a:'Running the loop: building the context for each call, offering tools, executing tool calls, enforcing permissions, and deciding when to stop.' }
        ],
        build:'Rewrite your agent rules file against the checklist, and add one hook or test that enforces a rule the file used to ask for.',
        solution:{ outline:'Rewrite your agent rules file against the checklist: short, specific, and with commands the agent can run. Remove advice the code already shows. Add one hook or test that enforces a rule the file used to ask for, and show it failing, then passing. Say which rules are still only requests.', selfcheck:['Is every rule specific and checkable?', 'Did you remove what the code already shows?', 'Does the hook or test fail on a violation?', 'Are the remaining soft rules named?'] },
        skip:['Is your rules file short enough to read in two minutes?','Is every must-never rule in your project enforced by a hook or permission?','Can you list every tool your agent can write through?']
      } },
    { id:'s3', t:'Craft and verification', level:'intermediate',
      goal:'Make verification the core of the work, and pick tools that let an agent check itself.', hours:3.25,
      steps:[
        { kind:'topic', ref:'craft-verification-as-the-job', tab:'interview', why:'When an agent writes the code, the engineer’s job becomes proving it works.', do:'Answer the interview questions, then write the check you ran, or should have run, for your last AI-written change.', min:30 },
        { kind:'topic', ref:'ai-evals', why:'An eval turns “it seemed fine” into a repeatable pass rate on cases you chose.', do:'Write five eval cases for one AI step in your pipeline from real inputs, including two adversarial ones (player text with instructions in it, an empty or very long field), and one hard-fail rule code can check.', min:25 },
        { kind:'prompt', ref:'verify', why:'A verification prompt makes the model list its assumptions and the source for each claim, so you can check them.', do:'Run the template on one AI answer you acted on, and check every claim it marks as inferred, invented or unsourced.', min:20 },
        { kind:'topic', ref:'craft-tools-that-work-with-ai', why:'Tools with text formats, a CLI and fast tests let an agent run the check itself.', do:'Mark which of your engine’s and pipeline’s tools an agent can run headless, and which need a person at a screen.', min:25 },
        { kind:'topic', ref:'craft-over-defensive-code', why:'Agents add guards for states that cannot happen, which hides the real invariant.', do:'Find one redundant null check or fallback in AI-written code and trace the upstream guard that makes it dead.', min:25 },
        { kind:'reflect', why:'An eval, a budget or a schema means nothing until a real call has returned a real number.', do:'Write a script of about forty lines that sends one prompt to a model API, asks for JSON in a schema you define, validates the reply, and logs latency, input and output tokens and any schema failure over twenty calls; note the slowest call and the cost per call.', min:45 },
        { kind:'tool', ref:'delegate', why:'Deciding what to hand an agent is easier once you know what you can verify.', do:'Plan one feature with the delegation planner, giving each task an owner, and write the check you will run on each task you give to AI.', min:25 }
      ],
      review:['models-context-engineering'],
      check:{
        recall:[
          { q:'What makes an eval useful rather than decorative?', a:'Real inputs across the spread plus adversarial ones, never the examples the prompt was tuned on; a rubric with hard fails, checked in code where code can; a model judge only where needed, compared against human labels; and a rerun on every prompt, model or data change, reading the outputs that changed rather than only the score.', ideas:['Real inputs across the spread plus adversarial ones, never the examples the prompt was tuned on', 'a rubric with hard fails, checked in code where code can', 'a model judge only where needed, compared against human labels', 'a rerun on every prompt, model or data change, reading the outputs that changed rather than only the score'] },
          { q:'Why prefer tools with text formats and a CLI when working with agents?', a:'The agent can read, diff and run them itself, so it can check its own work; a tool that needs a person at a screen puts every check back on you.', ideas:['The agent can read, diff and run them itself, so it can check its own work', 'a tool that needs a person at a screen puts every check back on you'] },
          { q:'What is wrong with a guard for a state that cannot occur?', a:'It suggests the invariant is uncertain, it hides where the real guard is, and it rots when that guard moves. Trace the flow and rely on the upstream guarantee.' }
        ],
        build:'For one AI-assisted feature, write the verification plan: the eval cases, the tests an agent can run headless, and the one check only a person can do.',
        solution:{ outline:'Write the verification plan for one AI-assisted feature. List the eval cases with expected results. List the tests an agent can run headless. Name the one check only a person can do, such as feel or fairness. Say what evidence you need before shipping, and what would stop it.', selfcheck:['Do the eval cases have expected results?', 'Can the agent run the tests without a person?', 'Is the human check named and justified?', 'Is the stop condition written?'] },
        skip:['Does every AI step in your pipeline have an eval with adversarial cases and hard fails?','Can your agent run your tests and build headless?','Do you review AI-written code for guards that duplicate an upstream guarantee?']
      } },
    { id:'s4', t:'AI inside a shipped game', level:'advanced',
      goal:'Choose the right technique for in-game AI, and draw the boundary where a model can and cannot decide.', hours:2.5,
      steps:[
        { kind:'topic', ref:'choosing-ai-technique', tab:'interview', why:'Most in-game AI is still state machines, behaviour trees and utility scores, and a model is one option among them.', do:'Answer the interview questions, then pick the technique for one character in your game and write why a model is or is not it.', min:25 },
        { kind:'tool', ref:'gameai', why:'The chooser forces the constraints (readability, budget, authoring) before the technique.', do:'Run one character through the chooser and keep the verdict.', min:20 },
        { kind:'topic', ref:'generative-characters', why:'A model-driven character is where the probabilistic part meets players directly.', do:'Write what a generative character in your game may decide, and what stays in scripted rules.', min:25 },
        { kind:'checklist', ref:'ai-architecture-boundary', why:'The boundary, validation, fallbacks and budgets decide whether a model feature survives real players.', do:'Run the checklist on one AI feature and write the fallback for each failure it names.', min:20 },
        { kind:'topic', ref:'ai-budgets-and-debugging', why:'In-game AI has a frame budget, and a model call has a latency and cost budget on top.', do:'Set a millisecond budget for your AI per frame and a latency budget for any model call.', min:25 },
        { kind:'engine', ref:'godot', alt:'unity', why:'An engine guide shows the main loop a model call has to fit around, and which checks an agent can run headless.', do:'Read the Godot guide’s architecture and AI sections, then sketch how a model reply would reach the scene tree (a signal, not a wait) so _process never blocks on it. In Unity, use an async call whose result raises an event.', min:20 },
        { kind:'topic', ref:'readable-and-fair-ai', why:'Players judge AI by what they can read of it, and a model is harder to make readable.', do:'List the tells your AI character shows before it acts, and how a generated one would keep them.', min:15 },
        { kind:'game', ref:'microsoft-flight-simulator', lens:'world', why:'Microsoft Flight Simulator shipped 1.5 billion buildings that a machine-learning model raised from satellite photos, and its makers accepted that about a fifth might be wrong.', do:'Read its world lens, then pick one content type your game could generate with a model. Write down the error rate you would accept, how you would measure it, and which ten items a human checks by hand before launch.', min:12 }
      ],
      review:['craft-verification-as-the-job'],
      check:{
        recall:[
          { q:'Where should the probabilistic and deterministic boundary sit in a game?', a:'The model proposes; deterministic code validates and applies. Rules the player can see, such as damage, prices and quest state, stay in code the model cannot change, and model output is parsed against a schema.' },
          { q:'What must a model feature do when the service fails?', a:'Fall back to something playable (scripted lines, a default choice, cached content), tested by forcing each failure, and the game must still start and save without the service.', ideas:['Fall back to something playable (scripted lines, a default choice, cached content)', 'tested by forcing each failure', 'the game must still start and save without the service'] },
          { q:'Why is a model rarely the first choice for enemy AI?', a:'It is hard to make readable, fair and tunable, it costs latency and money per decision, and state machines, behaviour trees and utility systems already give designers direct control.', ideas:['It is hard to make readable, fair and tunable', 'it costs latency and money per decision', 'state machines, behaviour trees and utility systems already give designers direct control'] }
        ],
        build:'Design one AI feature for your game with the boundary drawn: what the model decides, the schema, the validation, the fallback, and the latency and cost budgets.',
        solution:{ outline:'Design one AI feature with its boundary drawn. State what the model decides and what code decides. Give the output schema and the validation that rejects bad output. Add the fallback when validation fails or the call is slow. Set a latency budget and a cost budget per player. Use the readable-and-fair page to say how the player can tell what is happening.', selfcheck:['Is the model limited to choices code can validate?', 'Is there a schema and a rejection path?', 'Is there a fallback?', 'Are latency and cost numbers set?'] },
        skip:['Does every model output in your game pass a schema and validation before use?','Does your game run with the AI service unreachable?','Do you have a latency and cost budget per model call?']
      } },
    { id:'s5', t:'Shipping it', level:'advanced',
      goal:'Disclose AI use correctly and get an AI-assisted build through each store’s review.', hours:2.5,
      steps:[
        { kind:'topic', ref:'ai-disclosure-policy', tab:'interview', why:'Stores ask what AI made during development and what it generates while the game runs, and the answers have to stay true for each build.', do:'Answer the interview questions, then write your game’s AI disclosure for one store.', min:30 },
        { kind:'topic', ref:'certification-and-review', why:'An AI feature goes through the same gates and clocks as any other.', do:'Add your AI features to the submission calendar, with the checks each review will run on them.', min:25 },
        { kind:'checklist', ref:'ai-submission-by-platform', why:'An AI-assisted build skips particular checks, and they differ by platform family.', do:'Run the checklist for your platform families on the release candidate, next to the store checklist.', min:25 },
        { kind:'topic', ref:'ugc-platforms', why:'On a UGC platform the moderation and the audience belong to someone else; Roblox, for one, requires generated and externally fetched text to pass its own filter.', do:'Write how generated text in your game would pass the platform’s filtering and content questionnaire, or why you do not ship there.', min:20 },
        { kind:'topic', ref:'craft-source-control-for-games', why:'An agent in your repository meets the same traps as a person (binaries that cannot merge, regenerated folders), and shipped builds belong on a release branch, not in anyone’s workspace.', do:'Check that your release build comes from a release branch or tag through CI with regenerated folders ignored, and write the steps if it does not.', min:25 },
        { kind:'reflect', why:'The habits from this path only last if you write down which ones you will keep.', do:'Write the three verification habits you will keep for AI work, and the one AI use you decided against and why.', min:25 }
      ],
      review:['generative-characters','ai-evals'],
      check:{
        recall:[
          { q:'What does Steam ask about AI content?', a:'Whether the game ships pre-generated AI content, made with AI tools during development, and whether it generates content while running; for live-generated content, what guardrails stop it generating illegal content. Efficiency gains from AI development tools are not the focus.' },
          { q:'What must mobile store forms and review rules say about an AI feature?', a:'Google Play’s Data safety form counts any player data sent off the device, including to a model provider, as collected; Apple’s privacy label counts data kept longer than the request needs. Apple’s Guideline 5.1.2(i) also requires disclosing where personal data goes to third-party AI and getting explicit permission first, and Google Play requires in-app reporting of offensive AI output.' },
          { q:'Why must a model provider’s API key never ship in the client?', a:'Anything in the client can be extracted, so the key would let anyone run calls on your bill. Calls go through a server you control, which can also enforce limits.' }
        ],
        build:'Produce the AI disclosure for each store you ship on and a filled AI submission checklist for your release candidate.',
        solution:{ outline:'Produce the AI disclosure text for each store you ship on, using that store\'s own wording and fields. Fill the AI submission checklist for your release candidate: what is generated, by which tool, with what rights. Note differences between stores. Add where the records live in source control.', selfcheck:['Does each store have its own text?', 'Does the checklist cover every generated asset?', 'Are rights stated?', 'Are records kept with the project?'] },
        skip:['Have you filed AI disclosures for every store you ship on?','Is every model call routed through a server you control?','Is your release build made by CI from a tag?']
      } }
  ]
});
